(function(){
'use strict';
const PATCH_RELEASE='v2.3.0c';
const PATCH_NAME='Signature Deep Dive i18n';
const CASE_IDS=["MTB_CNS_001_v1_0","LAB_DOC_001_v1_0","RES_OMICS_001_v1_0","RES_ETH_001_v1_0"];
const SOURCE_DE={"MTB_CNS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"MTB_CNS_001_v1_0","title":"Glioblastom vor Therapieentscheidung: IDH, MGMT und Methylierung richtig integrieren","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Molekularpathologie / Neuropathologie / MTB","estimated_minutes_deep":"15–18","learning_objectives":["Diagnostische Klassifikation, molekulare Charakterisierung und prädiktive Biomarker als unterschiedliche Ebenen erkennen.","IDH, MGMT-Promotor-Methylierung und Methylierungsclassifier funktionell korrekt zuordnen.","Erkennen, dass ein breites DNA-NGS nicht automatisch jede klinische Fragestellung beantwortet.","Einen integrierten Befund nach klinischer Bedeutung und nicht nach technischer Breite priorisieren."],"opening_scene":"Freitagmittag in der Neuropathologie. Für einen 68-jährigen Patienten nach subtotaler Resektion eines hochgradigen hirneigenen Tumors soll der Befund vor der kommenden neuroonkologischen Therapieplanung finalisiert werden. Histologisch spricht vieles für ein Glioblastom. Die Neuroonkologie benötigt aber zusätzlich eine integrierte Klassifikation und ausdrücklich eine Einschätzung des Temozolomid-Kontextes. Material ist ausreichend vorhanden. Die entscheidende Frage lautet deshalb nicht: Wie viel können wir testen? Sondern: Welche Untersuchung beantwortet welche klinische Frage?","case_briefing":"68-jähriger Patient mit Krampfanfall und progressiver Aphasie. Im MRT zeigt sich eine ringförmig kontrastmittelaufnehmende Raumforderung. Nach subtotaler Resektion findet sich histologisch ein hochgradig glialer Tumor mit Nekrosen und mikrovaskulärer Proliferation; Ki-67 etwa 30–40 %. Die Arbeitsdiagnose lautet Glioblastom. Für molekulare Integration und Therapieplanung sind insbesondere IDH-Status, MGMT-Promotor-Methylierung und die Methylierungsklasse zu klären.","context_cards":[{"title":"Klinischer Kontext","content":"Krampfanfall, progressive Aphasie, subtotale Resektion; Radiochemotherapie wird diskutiert.","teaching_point":"Der molekulare Befund hat unterschiedliche diagnostische und therapeutische Funktionen."},{"title":"Histologie","content":"Hochgradig glialer Tumor mit Nekrosen und mikrovaskulärer Proliferation; Ki-67 ca. 30–40 %.","teaching_point":"Die Morphologie ist stark richtungsweisend, ersetzt aber nicht die molekulare Integration."},{"title":"Material","content":"FFPE-Resektat, Block T3, ca. 80 % Tumor; vitale Tumorareale markierbar; 14 Schnitte planbar.","teaching_point":"Kein akuter Materialmangel – rationale Diagnostik bleibt trotzdem erforderlich."},{"title":"Klinischer Auftrag","content":"Klassifikation, Prognose und Temozolomid-Kontext sollen vor Therapieplanung geklärt werden.","teaching_point":"Nicht jeder Marker beantwortet dieselbe Frage."}],"pre_results":[{"title":"HE","content":"Hochgradig glialer Tumor mit Nekrosen und mikrovaskulärer Proliferation."},{"title":"Ki-67","content":"Hoch, etwa 30–40 %."},{"title":"Arbeitsdiagnose","content":"Glioblastom wahrscheinlich."},{"title":"QC / offene Ebenen","content":"Hoher Tumoranteil; DNA-basierte und epigenetische Analysen sind technisch verwertbar. Offen sind IDH-Status, MGMT-Promotor-Methylierung und molekulare Integration."}],"material_or_resource_constraints":["Der Befund soll vor der anstehenden Therapieplanung finalisiert werden.","Die vorhandene Gewebemenge erlaubt mehrere Untersuchungen, rechtfertigt aber keine diagnostisch bedeutungslose Maximaldiagnostik.","DNA-basierte Sequenzierung und Methylierungsanalysen beantworten unterschiedliche Fragestellungen.","Ein technisch umfangreicher Befund kann klinisch trotzdem unvollständig sein."],"reasoning_gate_upgrade":[{"id":"cns_question_levels","type":"multi_select","prompt":"Welche Ebenen müssen Sie in diesem Fall auseinanderhalten?","options":[{"id":"classification","label":"Histologische/molekulare Klassifikation"},{"id":"tmz_prediction","label":"Prädiktiver Temozolomid-Kontext"},{"id":"molecular_characterization","label":"Zusätzliche molekulare Charakterisierung"},{"id":"max_gene_count","label":"Möglichst hohe Zahl getesteter Gene"},{"id":"tmb_msi_primary","label":"TMB/MSI als primärer Entscheidungsanker"}],"correct":["classification","tmz_prediction","molecular_characterization"],"rationale":"Die diagnostische Wertigkeit ergibt sich aus der klinischen Fragestellung. Möglichst viele Gene zu testen ist keine eigene diagnostische Ebene."},{"id":"cns_marker_roles","type":"multi_select","prompt":"Welche Zuordnungen sind korrekt?","options":[{"id":"idh_classification","label":"IDH → molekulare Klassifikation"},{"id":"mgmt_prediction","label":"MGMT-Promotor-Methylierung → epigenetischer/prädiktiver Therapie-Kontext"},{"id":"classifier_integration","label":"Methylierungsclassifier → zusätzliche diagnostische Klassifikations-/Integrationsebene"},{"id":"ngs_characterization","label":"Gliom-NGS → zusätzliche molekulare Charakterisierung"},{"id":"mgmt_driver","label":"MGMT → klassische Treibermutation im DNA-NGS"}],"correct":["idh_classification","mgmt_prediction","classifier_integration","ngs_characterization"],"rationale":"IDH, MGMT und Methylierungsclassifier beantworten unterschiedliche Fragen; MGMT ist hier keine klassische Treibermutation."},{"id":"cns_strategy","type":"single_choice","prompt":"Welche diagnostische Strategie beantwortet die klinische Fragestellung am vollständigsten?","options":[{"id":"integrated","label":"IDH-Status klären, MGMT-Promotor-Methylierung separat untersuchen und Methylierungsclassifier/Gliom-NGS sinnvoll integrieren."},{"id":"dna_only","label":"Nur ein breites DNA-NGS durchführen und davon ausgehen, damit sei die komplette Fragestellung beantwortet."},{"id":"tmb_first","label":"TMB/MSI priorisieren, weil der Tumor hochgradig ist."},{"id":"mgmt_mutation","label":"MGMT als Mutation innerhalb des NGS-Panels suchen."}],"correct":["integrated"],"rationale":"Diagnostische Breite ersetzt keine methodenspezifische Fragestellung. Die MGMT-Promotor-Methylierung muss separat adressiert werden."}],"decision_task":"Planen Sie die molekulare Diagnostik und formulieren Sie anschließend für das neuroonkologische Board: Welche Befunde stützen die integrierte Diagnose, welcher Befund ist für den Temozolomid-Kontext relevant und welche diagnostische Information wird durch ein DNA-NGS allein nicht ersetzt?","expected_path":["Morphologie und klinischen Kontext als Ausgangspunkt nutzen.","IDH-Status klären.","MGMT-Promotor-Methylierung als separate epigenetische Untersuchung einplanen.","Methylierungsclassifier sinnvoll in die Klassifikations-/Diagnoseintegration einordnen.","Gliom-NGS als zusätzliche molekulare Ebene verwenden.","Resultate nach klinischer Funktion gewichten.","MGMT nicht als Treibermutation beschreiben."],"acceptable_alternatives":["IDH kann über gezielte IHC/Sequenzierung oder geeignete Gliom-NGS-Diagnostik geklärt werden.","Ein breiteres molekulares Panel kann zusätzliche relevante Information liefern, solange klar bleibt, welche klinischen Fragen es nicht beantwortet.","Der diagnostische Umfang darf abhängig von Vorbefunden und institutioneller Workflowlogik variieren."],"low_value_traps":[{"label":"Breites Panel = vollständige Diagnostik","why_bad":"Technische Breite sagt nicht, ob die konkrete klinische Frage abgedeckt ist."},{"label":"MGMT als Mutation","why_bad":"Verwechselt epigenetische und genetische diagnostische Ebenen."},{"label":"TMB/MSI als Hauptfokus","why_bad":"Für die vorliegende IDH-/MGMT-/Temozolomid-Frage kein primärer Entscheidungsanker."},{"label":"Marker nur aufzählen","why_bad":"Ein integrierter Befund muss erklären, welche Information diagnostisch bzw. prädiktiv relevant ist."}],"twist":{"title":"Ein großes Panel – und trotzdem fehlt die entscheidende Information","content":"Die Sequenzierung zeigt IDH1/2-Wildtyp, TERT-Promotor-Mutation und ein EGFR-Amplifikationssignal; der molekulare Befund passt zum Glioblastom-Kontext. Im Board fällt der Satz: Dann sind wir doch fertig. MGMT wurde jedoch nicht untersucht. Erst die gezielte Ergänzung zeigt einen methylierten MGMT-Promotor; der Methylierungsclassifier unterstützt die Klasse Glioblastom, IDH-Wildtyp mit hohem Classifier Score.","why_critical":"Ein diagnostisch großer Befund kann eine konkrete Therapiefrage offenlassen. Die epigenetische MGMT-Ebene wird durch konventionelles DNA-NGS nicht ersetzt."},"result_packages":[{"id":"optimal","title":"Integrierter Befund","class":"optimal","result":"IDH-Wildtyp; MGMT-Promotor methyliert; Methylierungsklasse unterstützt Glioblastom, IDH-Wildtyp; molekulare Zusatzbefunde kompatibel mit dem Gesamtkontext.","feedback":"Sehr gut. Die einzelnen Methoden werden nach ihrer diagnostischen Funktion integriert."},{"id":"incomplete","title":"Viel Sequenzierung, offene Therapiefrage","class":"incomplete","result":"Umfangreiches DNA-NGS, aber keine MGMT-Promotor-Methylierung.","feedback":"Technisch umfangreich, klinisch unvollständig. Die Temozolomid-Fragestellung bleibt offen."},{"id":"wrong","title":"Falscher Fokus","class":"wrong","result":"Zusätzliche TMB/MSI-Diagnostik ohne vollständige IDH-/MGMT-Integration.","feedback":"Die Untersuchungen adressieren nicht die zentrale Fragestellung des Falles."}],"followup_logic":[{"trigger":"MGMT fehlt","action":"Gezielte MGMT-Methylierungsanalyse ergänzen.","consequence":"Therapieinterpretation bleibt bis dahin unvollständig."},{"trigger":"MGMT wird als Mutation interpretiert","action":"Konzeptfehler im Debrief adressieren.","consequence":"Deutlicher Reasoning-Abzug."},{"trigger":"Vollständige Integration","action":"Finalen neuroonkologischen/MTB-Befund formulieren.","consequence":"Vollständiger Deep-Dive-Pfad."}],"debrief_points":["Morphologie, molekulare Klassifikation und prädiktive Biomarker beantworten unterschiedliche Fragen.","MGMT-Promotor-Methylierung ist eine epigenetische diagnostische Ebene.","Ein breites Sequenzierpanel ist nicht automatisch ein vollständiger klinischer Befund.","Gute molekulare Pathologie priorisiert Informationen nach ihrer Bedeutung für Diagnose und Entscheidung."],"instructor_notes":{"model_answer":"Die morphologische Konstellation spricht für einen hochgradigen glialen Tumor. Für die integrierte Diagnostik wird der IDH-Status bestimmt. Die MGMT-Promotor-Methylierung muss separat als epigenetischer prädiktiver Marker beurteilt werden und wird nicht durch ein konventionelles DNA-NGS ersetzt. Methylierungsclassifier und Gliom-NGS können die diagnostische Integration ergänzen. Entscheidend ist die funktionelle Gewichtung der einzelnen Befunde.","scoring_focus":["Diagnostische Ebenen sauber getrennt.","IDH korrekt eingeordnet.","MGMT korrekt eingeordnet.","Kein Overcalling breiter Sequenzierung.","Klare MTB-/Neuroonkologie-Kommunikation."],"discussion_questions":["Wann bietet ein breites Panel echten Mehrwert?","Was bedeutet vollständige Diagnostik in diesem Fall?","Wie sollten unterschiedliche diagnostische Ebenen im Befund sprachlich sichtbar werden?"]},"report_additions":{"content_status":"DE curated deep dive","key_turning_point":"Breites NGS, aber MGMT fehlt","core_trap":"MGMT ist keine klassische Treibermutation","pattern":"Morphologie → Klassifikation → Prädiktion → Integration"},"is_signature_case":true},"LAB_DOC_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"LAB_DOC_001_v1_0","title":"‚PCR wie immer gemacht‘: analytisch valide, trotzdem ein QM-Fall","domain":"LAB","target_course":"QM Basics","deep_dive_priority":"signature","target_role":"Laborleitung / QM / molekularpathologisches Labor","estimated_minutes_deep":"12–15","learning_objectives":["Analytische Validität und Prozess-/Dokumentationskonformität getrennt bewerten.","Vor einer reflexhaften Wiederholung vorhandene Primärdaten systematisch rekonstruieren.","Eine schwache Patientenprobe risikobasiert freigeben, wenn die analytische Grundlage belastbar rekonstruiert wurde.","Erkennen, dass eine relevante systemische Dokumentationslücke trotz erfolgreicher Rekonstruktion als Abweichung/Near Miss bearbeitet und hier in eine CAPA überführt werden muss.","Die Wirksamkeit einer CAPA überprüfen."],"opening_scene":"Am Vormittag beginnt die interne Auditvorbereitung im molekularpathologischen Labor. Als Stichprobe wird ein qPCR-KRAS-Run herausgezogen. Im Laborbuch findet sich dazu genau ein Satz: ‚PCR wie immer gemacht. Hat geklappt. Probe 4 schwach.‘ Die Kollegin erinnert sich an den Run und sagt: ‚Das war alles okay. Die Kontrollen waren gut.‘ Das Ergebnis von Probe 4 ist klinisch relevant. Die Frage ist jetzt nicht nur: War die PCR technisch gut? Sondern: Können wir das heute noch belastbar nachweisen – und was tun wir, wenn wir es können?","case_briefing":"Routine-qPCR-KRAS-Hotspot-Test. Der Laborbucheintrag enthält weder eine ausreichende Methodenreferenz noch einen vollständigen Audit Trail. Es fehlen unter anderem Datum/Uhrzeit, Bearbeiter, SOP-Version, eindeutige Proben-IDs, Kit/Lot/MHD, Gerät und Run-ID, Positiv-/Negativ-/NTC-Kontrollen, Ct-Werte/Replikate, Rohdatenpfad und die dokumentierte fachliche Bewertung der schwachen Probe. Die eigentlichen Rohdaten und Metadaten könnten jedoch noch in Gerät, LIMS und elektronischen Systemen vorhanden sein.","context_cards":[{"title":"Originaleintrag","content":"‚PCR wie immer gemacht. Hat geklappt. Probe 4 schwach.‘","teaching_point":"Plausibilität ist keine Rückverfolgbarkeit."},{"title":"Assay","content":"qPCR-KRAS-Hotspot-Test aus der Routine.","teaching_point":"Routine reduziert Dokumentationsanforderungen nicht."},{"title":"Patientenprobe","content":"Probe 4 zeigt ein schwaches Signal.","teaching_point":"Gerade Grenz-/Schwachsignale benötigen nachvollziehbare Primärdaten und Bewertung."},{"title":"Konflikt","content":"Rekonstruieren oder vorsorglich alles wiederholen?","teaching_point":"Gute QM ist risikobasiert, nicht reflexhaft maximalistisch."}],"pre_results":[{"title":"Dokumentationslage","content":"Die ursprüngliche Dokumentation ist unzureichend; es gibt aber keinen Hinweis auf einen bekannten technischen Runfehler."},{"title":"Verfügbare Quellen","content":"Geräteexport, LIMS und weitere elektronische Metadaten sind noch verfügbar."},{"title":"Material-/Zeitkontext","content":"Das verbleibende Patientenmaterial ist begrenzt. Eine Wiederholung würde zusätzlich Zeit und Material verbrauchen."},{"title":"Offene Frage","content":"Noch ist nicht geklärt, ob sich der komplette analytische Pfad einschließlich der schwachen Probe belastbar rekonstruieren lässt."}],"material_or_resource_constraints":["Patientenmaterial ist nicht beliebig verfügbar.","Jede Wiederholung verbraucht Material und verursacht Zeit- und Ressourcenaufwand.","Eine unnötige Wiederholung ist deshalb nicht automatisch sicherer.","Eine Freigabe ohne belastbare Rekonstruktion wäre andererseits nicht vertretbar.","QM-Maßnahmen sollen die tatsächliche Ursache adressieren und nicht nur Symptome beseitigen."],"reasoning_gate_upgrade":[{"id":"labdoc_primary_problem","type":"single_choice","prompt":"Was ist das primäre Problem?","options":[{"id":"auto_invalid","label":"Der Run ist automatisch analytisch ungültig."},{"id":"traceability","label":"Die Rückverfolgbarkeit und dokumentierte Bewertungsgrundlage sind unzureichend."},{"id":"weak_never_release","label":"Eine schwache Probe ist grundsätzlich nicht freigabefähig."},{"id":"routine_less_docs","label":"Routine-PCR benötigt weniger Dokumentation."}],"correct":["traceability"],"rationale":"Aus einem Dokumentationsmangel folgt nicht automatisch ein analytischer Fehler. Zuerst muss geprüft werden, ob die analytische Gültigkeit quellenbasiert rekonstruierbar ist."},{"id":"labdoc_reconstruct","type":"multi_select","prompt":"Welche Informationen müssen für eine auditfähige Rekonstruktion herangezogen werden?","options":[{"id":"who_when","label":"Bearbeiter und Zeitpunkt"},{"id":"sop","label":"SOP-Version"},{"id":"lot","label":"Kit/Reagenzien-Lot und MHD"},{"id":"sample_id","label":"Eindeutige Probenidentität"},{"id":"run_id","label":"Gerät und Run-ID"},{"id":"controls","label":"Positiv-/Negativ-/NTC-Kontrollen"},{"id":"ct_replicates","label":"Ct-Werte und Replikate"},{"id":"rawdata","label":"Rohdatenpfad/Primärdaten"},{"id":"sample4_review","label":"Fachliche Bewertung von Probe 4"},{"id":"memory_only","label":"Mündliche Erinnerung der Kollegin als alleiniger Nachweis"}],"correct":["who_when","sop","lot","sample_id","run_id","controls","ct_replicates","rawdata","sample4_review"],"rationale":"Die Rekonstruktion muss quellenbasiert und auditfähig sein; Erinnerung allein reicht nicht."},{"id":"labdoc_release_or_repeat","type":"single_choice","prompt":"Die Rekonstruktion ergibt eindeutige Probenzuordnung, gültige SOP-/Lot-Daten, valide Kontrollen, vollständige Rohdaten und ein reproduzierbares schwaches Signal in Probe 4. Was ist jetzt richtig?","options":[{"id":"release_after_review","label":"Rekonstruktion und fachliche Neubewertung transparent dokumentieren; Probe 4 freigeben; keine unnötige Wiederholung."},{"id":"repeat_all","label":"Den kompletten Run unabhängig von den vorhandenen Primärdaten wiederholen."},{"id":"weak_hold","label":"Probe 4 nicht freigeben, weil schwach grundsätzlich unzuverlässig bedeutet."},{"id":"release_no_docs","label":"Einfach freigeben und die ursprüngliche Dokumentation unverändert lassen."}],"correct":["release_after_review"],"rationale":"Die analytische Validität ist anhand der Primärdaten nachvollziehbar. Wiederholung ist kein Selbstzweck und würde unnötig Material, Zeit und Ressourcen verbrauchen."},{"id":"labdoc_capa","type":"single_choice","prompt":"Ist der Fall nach der erfolgreichen Ergebnisrekonstruktion erledigt?","options":[{"id":"done_no_harm","label":"Ja. Es ist kein Patientenschaden entstanden."},{"id":"near_miss_capa","label":"Nein. Die relevante Dokumentationslücke wird als Abweichung/Near Miss risikobasiert bewertet; das hier erkennbare systemische Problem wird mit CAPA und Wirksamkeitsprüfung adressiert."},{"id":"verbal_reminder","label":"Eine informelle Erinnerung an das Team reicht."},{"id":"rewrite_old","label":"Der alte Laborbucheintrag wird gelöscht und neu geschrieben."}],"correct":["near_miss_capa"],"rationale":"Die erfolgreiche Rekonstruktion verhindert einen Fehler, beseitigt aber nicht die systemische Schwäche, die ihn beinahe ermöglicht hätte."}],"decision_task":"Treffen Sie zwei getrennte Entscheidungen: Ist das konkrete Patientenergebnis nach Rekonstruktion freigabefähig? Welche QM-Konsequenz folgt aus dem unzureichenden ursprünglichen Prozess?","expected_path":["Dokumentationsmangel erkennen.","Ergebnis nicht automatisch verwerfen.","Primärdaten und Metadaten systematisch rekonstruieren.","Run-Gültigkeit anhand der Kontrollen bestätigen.","Schwache Probe anhand von Ct/Replikaten und Rohdaten fachlich neu bewerten.","Ergebnis transparent freigeben.","Ursprünglichen Dokumentationsmangel als Abweichung/Near Miss erfassen.","Root Cause analysieren.","CAPA umsetzen.","Wirksamkeit anhand nachfolgender Dokumentationen prüfen."],"acceptable_alternatives":["Eine Wiederholung ist vertretbar, wenn entscheidende Elemente wie Probenidentität, Kontrollen, Primärdaten oder die fachliche Bewertung nicht belastbar rekonstruierbar sind.","Wiederholung folgt aus dem Risiko – nicht aus der bloßen Existenz einer Abweichung."],"low_value_traps":[{"label":"Bei Abweichung immer wiederholen","why_bad":"Kann unnötig Patientenmaterial, Zeit und Ressourcen verbrauchen und löst die Prozessursache nicht."},{"label":"Es ist nichts passiert, also keine CAPA","why_bad":"Near Miss und systemische Prozessschwäche bleiben bestehen."},{"label":"Nur Ct-Wert nachtragen","why_bad":"Die Rückverfolgbarkeit bleibt unvollständig."},{"label":"Nur Schulung","why_bad":"Eine Schulung ohne Ursachenbezug und Wirksamkeitsprüfung ist keine belastbare CAPA."},{"label":"Mündliche Erinnerung","why_bad":"Kein auditfähiger Ersatz für Primärdaten."}],"twist":{"title":"Die schwache Probe ist tatsächlich freigabefähig","content":"Die Rekonstruktion zeigt: Der Run war technisch valide, die Kontrollen waren korrekt und Probe 4 zeigt in den Primärdaten ein reproduzierbares schwaches Signal. Nach dokumentierter fachlicher Neubewertung kann die Probe freigegeben werden; eine komplette Wiederholung ist nicht erforderlich. Eine Stichprobe weiterer Laborbucheinträge zeigt jedoch mehrere ähnlich verkürzte Formulierungen – aus dem Einzelfall wird eine systemische Dokumentationsschwäche.","why_critical":"Analytische Validität und Prozesskonformität sind getrennte Fragen. Das konkrete Ergebnis kann gerettet werden, während der Near Miss trotzdem eine risikobasierte Abweichungs-/CAPA-Bearbeitung verlangt."},"result_packages":[{"id":"optimal","title":"Risikobasierte Freigabe + CAPA","class":"optimal","result":"Run und Probe 4 vollständig rekonstruiert, fachlich freigegeben, Abweichung dokumentiert, Root Cause adressiert, CAPA mit Wirksamkeitsprüfung etabliert.","feedback":"Sehr gut. Analytische Validität und Prozesskonformität wurden getrennt und risikobasiert bewertet."},{"id":"incomplete","title":"Sicherheitsreflex: alles wiederholen","class":"incomplete","result":"Kompletter Run wiederholt, obwohl alle relevanten Primärdaten verfügbar waren.","feedback":"Wiederholung ist kein Selbstzweck. Material- und Ressourcenverbrauch wurden nicht berücksichtigt; die Prozessursache bleibt ungelöst."},{"id":"release_no_capa","title":"Ergebnis richtig, QM falsch","class":"incomplete","result":"Probe korrekt freigegeben, Dokumentationsproblem danach als erledigt betrachtet.","feedback":"Das konkrete Ergebnis ist gerettet, die systemische Ursache aber nicht."},{"id":"wrong","title":"Freigabe nur nach Erinnerung","class":"wrong","result":"Freigabe allein aufgrund von Routine und Erinnerung.","feedback":"Nicht auditfähig und nicht belastbar."}],"followup_logic":[{"trigger":"Primärdaten nicht vollständig rekonstruierbar","action":"Hold und gezielte Wiederholung bzw. weitere Klärung.","consequence":"Keine Freigabe ohne belastbare Grundlage."},{"trigger":"Vollständige Rekonstruktion plus valide Kontrollen","action":"Fachliche Neubewertung durchführen und dokumentieren.","consequence":"Freigabe kann möglich sein."},{"trigger":"Systemische Dokumentationslücke","action":"Root Cause und CAPA durchführen.","consequence":"Template/Prozess/Schulung entsprechend Ursache anpassen."},{"trigger":"CAPA umgesetzt","action":"Stichprobe der nachfolgenden qPCR-Dokumentationen durchführen.","consequence":"Wirksamkeitsprüfung statt bloßer Maßnahmenabschluss."}],"debrief_points":["Analytische Validität und Prozesskonformität sind unterschiedliche Fragen.","Eine Abweichung macht ein Ergebnis nicht automatisch ungültig.","Eine Wiederholung muss risikobasiert begründet sein.","Begrenztes Material, Zeit und Ressourcen gehören in die Risikoabwägung.","Ein Near Miss ist besonders lehrreich, wenn die Schwachstelle erkannt wird, bevor ein Schaden entsteht.","CAPA endet mit einer Wirksamkeitsprüfung, nicht mit ‚Mitarbeiter geschult‘."],"instructor_notes":{"model_answer":"Zunächst wird die Rückverfolgbarkeit anhand von LIMS, Geräteexport, SOP-, Lot-, Kontroll- und Rohdaten rekonstruiert. Sind Probenidentität, Run-Gültigkeit und die schwache Positivität von Probe 4 belastbar nachvollziehbar, kann das Ergebnis nach dokumentierter Neubewertung freigegeben werden. Eine pauschale Wiederholung ist nicht erforderlich. Der ursprüngliche Dokumentationsmangel wird dennoch als relevante Abweichung mit Near-Miss-Charakter bearbeitet. Bei erkennbarem systemischem Problem folgen Root-Cause-Analyse, geeignete CAPA und Wirksamkeitsprüfung.","scoring_focus":["Rekonstruktion vor Wiederholung.","Primärdaten statt Erinnerung.","Korrekte Freigabe der schwachen Probe.","Abweichung/Near Miss nicht ignoriert.","CAPA ursachenbezogen.","Effectiveness Check."],"discussion_questions":["Wann ist Wiederholung tatsächlich erforderlich?","Kann ein Ergebnis valide sein, obwohl der Prozess fehlerhaft war?","Wo liegt die Grenze zwischen Correction und CAPA?","Warum ist mehr Sicherheit nicht automatisch gleichbedeutend mit mehr Wiederholungen?"]},"report_additions":{"content_status":"DE curated deep dive","key_turning_point":"Schwache Probe nach Rekonstruktion freigabefähig","core_message":"Analytische Validität ≠ Prozesskonformität","pattern":"Rekonstruktion → Risikobewertung → Freigabe → CAPA → Wirksamkeitsprüfung"},"is_signature_case":true},"RES_OMICS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_OMICS_001_v1_0","title":"200 DEGs, ein Biomarker? Vom RNA-Seq-Signal zur belastbaren Resistenzhypothese","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Translationale Forschung / Molekularpathologie / Bioinformatik","estimated_minutes_deep":"18–22","learning_objectives":["DEG-Listen in biologische Programme statt Einzelgen-Storys übersetzen.","Eine Omics-Beobachtung als überprüfbare Hypothese und PICO operationalisieren.","Discovery, technische Validierung, morphologische Validierung und externe Replikation unterscheiden.","Explorative Ergebnisse nicht als fertigen Biomarker überinterpretieren.","Robustheit einer Signatur gegenüber einem attraktiven Einzelgen priorisieren."],"opening_scene":"Montagmorgen im translationalen Forschungsmeeting. Eine Doktorandin hat ihre erste RNA-Seq-Auswertung fertig: 30 ICI-behandelte Tumoren, 15 Responder und 15 Non-Responder. Auf ihrer Folie steht: ‚200 signifikante DEGs.‘ Darunter eine sortierte Tabelle. Sie fragt: ‚Welches Gen nehme ich jetzt als Biomarker?‘ Der niedrigste p-Wert sieht spektakulär aus. Aber genau hier beginnt die eigentliche wissenschaftliche Arbeit.","case_briefing":"RNA-Seq von 30 ICI-behandelten Tumoren: 15 Responder und 15 Non-Responder. In den Non-Respondern sind unter anderem TGFB1, COL1A1, CXCL12, ACTA2, FN1 und weitere ECM-Gene erhöht; HLA-A, B2M, TAP1, CXCL9 und GZMB sind vermindert. Die Pathway-Analyse zeigt TGFβ/ECM hoch und Antigenpräsentation/T-Zell-Aktivierung niedrig. Klinisch fallen stromareiche Tumoren durch schlechteres ICI-Ansprechen auf.","context_cards":[{"title":"Discovery-Kohorte","content":"30 ICI-behandelte Tumoren, 15 Responder versus 15 Non-Responder.","teaching_point":"Kleine Discovery-Kohorten sind geeignet zur Hypothesengenerierung, nicht automatisch zum Biomarkerclaim."},{"title":"RNA-Seq-Signal","content":"200 differentiell exprimierte Gene.","teaching_point":"Eine Genliste ist noch keine biologische Erklärung."},{"title":"Biologisches Muster","content":"TGFβ/ECM hoch, Antigenpräsentation/T-Zell-Aktivierung niedrig.","teaching_point":"Koordinierte Programme können aussagekräftiger sein als ein Einzelgen."},{"title":"Translationales Ziel","content":"Mechanismus und klinisch überprüfbare Signatur entwickeln.","teaching_point":"Von Omics zu Translation braucht es mehrere Validierungsebenen."}],"pre_results":[{"title":"Non-Responder – erhöht","content":"TGFB1, COL1A1, CXCL12, ACTA2, FN1 und weitere ECM-Gene."},{"title":"Non-Responder – vermindert","content":"HLA-A, B2M, TAP1, CXCL9 und GZMB."},{"title":"Pathway-Enrichment","content":"TGFβ/ECM hoch; Antigenpräsentation/T-Zell-Aktivierung niedrig."},{"title":"Noch nicht entschieden","content":"Das stärkste Einzelgen, eine Signatur und ein biologisches Programm sind nicht dasselbe. Die Interpretation muss aktiv priorisiert werden."}],"material_or_resource_constraints":["Discovery-Kohorte: n = 30.","Multiple Tests/FDR müssen berücksichtigt werden.","Klinische Confounder wie Therapie, Tumorentität, ECOG und Tumoranteil müssen erfasst werden.","Budget reicht für gezielte technische und morphologische Validierung, nicht für unbegrenztes Multi-Omics.","Eine unabhängige Validierung ist notwendig, bevor ein Biomarkerclaim erhoben wird."],"reasoning_gate_upgrade":[{"id":"omics_from_degs","type":"single_choice","prompt":"Wie wird aus 200 DEGs eine belastbare Forschungsfrage?","options":[{"id":"lowest_p","label":"Das Gen mit dem niedrigsten p-Wert auswählen."},{"id":"all_genes","label":"Alle 200 Gene gleichwertig berichten."},{"id":"programs","label":"Koordinierte biologische Programme und gemeinsame Pathways identifizieren."},{"id":"expected_only","label":"Nur Gene behalten, die in die erwartete Story passen."}],"correct":["programs"],"rationale":"Das gemeinsame stromal/immunologische Muster liefert eine robustere Hypothese als ein isoliertes Einzelgen."},{"id":"omics_hypothesis","type":"single_choice","prompt":"Welche Hypothese passt am besten zu den vorliegenden Daten?","options":[{"id":"stroma_immune","label":"Primäre ICI-Non-Response ist mit einem stromal/TGFβ-dominierten und gleichzeitig antigenarmen Tumormikromilieu assoziiert."},{"id":"tgfb1_marker","label":"TGFB1 ist der neue prädiktive Biomarker."},{"id":"all_degs_explain","label":"Die 200 DEGs erklären ICI-Resistenz bereits vollständig."},{"id":"one_resistance_gene","label":"Alle Non-Responder besitzen dasselbe Resistenzgen."}],"correct":["stroma_immune"],"rationale":"Die Hypothese integriert mehrere koordinierte Expressionsprogramme und bleibt überprüfbar, ohne einen explorativen Einzelhit zu overcallen."},{"id":"omics_pico","type":"multi_select","prompt":"Welche Elemente gehören zur sauberen Operationalisierung der Hypothese?","options":[{"id":"population","label":"Population: ICI-behandelte Tumoren"},{"id":"exposure","label":"Exposition/Signatur: hohe CAF/TGFβ-Signatur"},{"id":"comparison","label":"Vergleich: niedrige Signatur"},{"id":"outcome","label":"Outcome: Ansprechen/PFS"},{"id":"score_cutoff","label":"Score-/Cutoff-Strategie vor Validierung definieren"},{"id":"confounders","label":"Relevante Confounder und Analyseplan definieren"},{"id":"posthoc_cutoff","label":"Cutoff erst nach schönstem Validierungsergebnis festlegen"}],"correct":["population","exposure","comparison","outcome","score_cutoff","confounders"],"rationale":"Hypothese, PICO, Score/Cutoff und Analyseplan müssen vor der Validierung operationalisiert werden."},{"id":"omics_validation","type":"multi_select","prompt":"Welche Validierungsschritte sind für die translationale Entwicklung belastbar?","options":[{"id":"targeted","label":"Targeted RNA/qPCR/NanoString"},{"id":"external","label":"Unabhängige ICI-Kohorte"},{"id":"morphology","label":"αSMA/FAP/CD8/HLA-I/B2M als morphologische Brücke"},{"id":"fdr","label":"FDR und multiple Tests transparent berichten"},{"id":"heatmap_only","label":"Heatmap erneut zeichnen"},{"id":"single_wb","label":"Nur stärkstes Einzelgen per Western Blot bestätigen"}],"correct":["targeted","external","morphology","fdr"],"rationale":"Technische, morphologische und unabhängige Validierung ergänzen sich; reine Visualisierung oder ein einzelner Bestätigungsassay reichen für eine Signaturhypothese nicht."}],"decision_task":"Entwickeln Sie aus der explorativen RNA-Seq-Auswertung eine belastbare translationale Strategie: biologische Hypothese, PICO, Signatur-/Analysekonzept, technische Validierung, morphologische Brücke, externe Validierung und Grenze des zulässigen Biomarkerclaims.","expected_path":["DEG-Liste nicht als Endprodukt behandeln.","Pathway-/Netzwerkebene priorisieren.","Stromal/TGFβ-dominiertes, antigenarmes Muster formulieren.","Hypothese und PICO definieren.","Signatur operationalisieren.","FDR und Confounder berücksichtigen.","Technisch gezielt validieren.","Morphologisch mit TME-Markern verbinden.","Unabhängige Kohorte verwenden.","Erst danach Biomarkerpotenzial diskutieren."],"acceptable_alternatives":["Die Studie ausdrücklich explorativ ohne Biomarkerclaim abschließen.","Eine fokussierte kleinere Signatur statt eines komplexen Scores entwickeln.","Targeted Expression/NanoString statt erneuter RNA-Seq zur technischen Validierung verwenden.","Funktionelle Validierung ergänzen, wenn die mechanistische Frage im Vordergrund steht."],"low_value_traps":[{"label":"Niedrigster p-Wert = Biomarker","why_bad":"Einzelgene können instabil sein und den biologischen Kontext verlieren."},{"label":"Heatmap = Validierung","why_bad":"Visualisierung bestätigt keine unabhängige Reproduzierbarkeit."},{"label":"200 DEGs als Ergebnis","why_bad":"Datenmenge ersetzt keine Hypothese."},{"label":"Cutoff nachträglich optimieren","why_bad":"Overfitting-/HARKing-Risiko."},{"label":"Nicht passende Ergebnisse entfernen","why_bad":"Selektive Berichterstattung."}],"twist":{"title":"Das ‚beste Gen‘ verschwindet – die Biologie bleibt","content":"In einer unabhängigen Validierungskohorte reproduziert sich das Einzelgen mit dem niedrigsten Discovery-p-Wert nicht überzeugend. Die zuvor definierte stromal/immune Signatur zeigt dagegen weiterhin dasselbe koordinierte Muster: stromale/TGFβ-Komponente erhöht, Antigenpräsentations-/T-Zell-Komponente vermindert. Auch die morphologische Validierung unterstützt die programmatische Interpretation.","why_critical":"Der attraktivste einzelne Discovery-Hit ist nicht zwangsläufig das robusteste biologische Signal. Der Fall trennt Einzelgen, Signatur, Mechanismus und validierten Biomarker voneinander."},"result_packages":[{"id":"optimal","title":"Signaturhypothese validiert","class":"optimal","result":"Pathway-basierte Hypothese, vorab definierte Signatur, technische Validierung, morphologische Brücke und unabhängige Kohorte zeigen ein konsistentes Muster.","feedback":"Sehr gute translationale Entwicklung. Biomarkerpotenzial kann jetzt vorsichtig diskutiert werden."},{"id":"incomplete","title":"Single-Gene-Collapse","class":"incomplete","result":"Das stärkste Discovery-Einzelgen reproduziert sich nicht, die übergeordnete Signatur bleibt jedoch konsistent.","feedback":"Kein Scheitern des Projekts, wenn die biologische Hypothese unabhängig gestützt wird."},{"id":"heatmap_story","title":"Schöne Heatmap, keine Validierung","class":"incomplete","result":"Exploratives Cluster ohne unabhängige Replikation.","feedback":"Interessant, aber kein belastbarer Biomarker."},{"id":"wrong","title":"Overclaim","class":"wrong","result":"Discovery-Signatur wird direkt als prädiktiver Biomarker bezeichnet.","feedback":"Die Aussagekraft der Daten wird überschritten."}],"followup_logic":[{"trigger":"Nur Einzelgen priorisiert","action":"Pathway-/Netzwerkanalyse in das Reasoning zurückholen.","consequence":"Reasoning-Cap bei monomarkerhafter Interpretation."},{"trigger":"Keine unabhängige Validierung","action":"Ergebnis als explorativ kennzeichnen.","consequence":"Kein Biomarkerclaim."},{"trigger":"Signatur repliziert","action":"Morphologische und klinische Translation prüfen.","consequence":"Deep-Dive-Optimalpfad."}],"debrief_points":["Eine DEG-Liste ist noch kein biologisches Modell.","Pathway- und Signaturinformationen können robuster sein als ein einzelnes Discovery-Gen.","Technische, morphologische und externe Validierung beantworten unterschiedliche Fragen.","Discovery und Validation müssen getrennt werden.","Negative Replikation eines Einzelhits kann eine Hypothese verbessern statt das Projekt zu zerstören.","Ein Biomarker ist das Ergebnis einer Validierungskette, nicht einer schönen Heatmap."],"instructor_notes":{"model_answer":"Die Daten werden zunächst auf Pathway-/Netzwerkebene interpretiert. Das koordinierte TGFβ/ECM-hohe und antigenpräsentationsarme Muster wird als explorative Resistenzhypothese formuliert. Anschließend werden Population, Signatur, Vergleich und Outcome operationalisiert. Die Signatur wird technisch, morphologisch und in einer unabhängigen Kohorte validiert. Einzelgene und Cutoffs werden nicht post hoc als fertige Biomarker überinterpretiert.","scoring_focus":["Pathway vor Einzelgen.","Klare Hypothese/PICO.","FDR/Confounder berücksichtigt.","Discovery versus Validation getrennt.","Morphologische Brücke.","Biomarkerclaim begrenzt."],"discussion_questions":["Wann ist eine Signatur einem Einzelmarker überlegen?","Was bedeutet unabhängige Validierung wirklich?","Wie kann ein negatives Validierungsergebnis wissenschaftlich wertvoll sein?","Wann darf aus einer Assoziation ein Biomarkerprojekt werden?"]},"report_additions":{"content_status":"DE curated deep dive","key_turning_point":"Bester Einzelhit repliziert nicht","core_message":"DEG → Pathway → Hypothese → Signatur → Validierung","pattern":"Discovery nicht mit Biomarkerbeweis verwechseln"},"is_signature_case":true},"RES_ETH_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_ETH_001_v1_0","title":"120 Archivblöcke und keine klare Einwilligung: Darf das Projekt starten?","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Translationale Projektleitung / Pathologie / Forschungs-QM","estimated_minutes_deep":"18–22","learning_objectives":["Governance als Voraussetzung wissenschaftlicher Arbeit und nicht als nachgelagerte Formalität verstehen.","Ethik/Einwilligung, Materialschutz, Datenschutz und Nebenbefundmanagement getrennt planen.","Erkennen, warum Restmaterial und Anonymisierung keine pauschalen Freigaben darstellen.","Eine Forschungsentscheidung so planen, dass spätere Keimbahnverdachts- und Data-Sharing-Situationen bereits abgedeckt sind."],"opening_scene":"Eine Forschungsgruppe präsentiert ein neues Projekt: 120 archivierte FFPE-Tumorblöcke sollen mit einem erweiterten DNA/RNA-Panel auf neue Resistenzmarker untersucht werden. Assay, Bioinformatik und Budget stehen. Die Projektleitung sagt: ‚Das ist doch nur Restmaterial. Wir können nächste Woche anfangen.‘ Die Blöcke stammen jedoch aus unterschiedlichen Jahren, die Einwilligungslage ist uneinheitlich und bei einigen kleinen Blöcken ist die diagnostische Restreserve unklar. Zusätzlich kann das geplante Tumor-only-Panel Hinweise auf potenziell keimbahnrelevante Varianten liefern. Noch bevor eine Probe geschnitten wird, muss deshalb die erste Entscheidung fallen.","case_briefing":"Projektziel: neue molekulare Marker therapeutischer Resistenz in einer retrospektiven Tumorkohorte identifizieren. Geplant sind 120 Routine-FFPE-Blöcke, ein erweitertes DNA/RNA-Panel, Verknüpfung mit klinischen Daten und Follow-up sowie Publikation und gegebenenfalls externe Validierung/Data Sharing. Die Einwilligungs-/Governance-Situation ist uneinheitlich, die Gewebereserve teilweise knapp, und ein definierter Nebenbefund-/Keimbahnverdachtsprozess fehlt noch.","context_cards":[{"title":"Material","content":"Routine-FFPE, teils kleine Blöcke; diagnostische Reserve nicht überall gesichert.","teaching_point":"Forschung darf zukünftige Patientenversorgung nicht gefährden."},{"title":"Einwilligung","content":"Unterschiedliche Jahrgänge und uneinheitliche Consent-/Governance-Situation.","teaching_point":"Archiviert bedeutet nicht automatisch frei verfügbar."},{"title":"Daten","content":"Klinische Daten und Follow-up sollen verknüpft werden.","teaching_point":"Datenschutz und Zugriff gehören in das Studiendesign."},{"title":"Genetik","content":"Tumor-only-Diagnostik kann einen Keimbahnverdacht erzeugen.","teaching_point":"Rückmeldewege müssen vor der Analyse definiert sein."},{"title":"Data Sharing","content":"Externe Validierung und Publikation sind geplant.","teaching_point":"Spätere Datennutzung muss vom Governance-Rahmen gedeckt sein."}],"pre_results":[{"title":"Kohorte","content":"120 mögliche Fälle aus unterschiedlichen Jahrgängen."},{"title":"Governance","content":"Keine einheitliche Einwilligungslage; finale Materialfreigabe steht aus."},{"title":"Datenplan","content":"Klinische Daten sollen retrospektiv ergänzt werden; externe Validierung ist als spätere Option im Gespräch."},{"title":"Vorhersehbare Nebenbefunde","content":"Das Tumor-only-Panel kann potenziell keimbahnrelevante Varianten erzeugen; ein geregelter Prozess muss vor Start feststehen."}],"material_or_resource_constraints":["Diagnostische Restreserve hat Vorrang vor Forschungsverbrauch.","Nicht jeder Fall muss zwingend in die finale Kohorte aufgenommen werden.","Follow-up und Rückmeldefähigkeit können mit vollständiger Anonymisierung kollidieren.","Datenumfang und Zugriff sollen auf das notwendige Maß begrenzt werden.","Governance-Entscheidungen müssen getroffen werden, bevor Material und Daten irreversibel verarbeitet werden."],"reasoning_gate_upgrade":[{"id":"eth_start","type":"single_choice","prompt":"Darf das Projekt sofort starten?","options":[{"id":"leftover_yes","label":"Ja, weil es Restmaterial ist."},{"id":"anonymized_yes","label":"Ja, wenn alle Fallnummern entfernt werden."},{"id":"governance_first","label":"Nein; zunächst Ethik-/Einwilligungssituation, Datenschutz, Materialfreigabe und Nebenbefundprozess klären."},{"id":"dna_extract_first","label":"Ja, solange zunächst nur DNA extrahiert wird."}],"correct":["governance_first"],"rationale":"Governance und Materialschutz müssen vor einer irreversiblen Nutzung von Proben und Daten geklärt sein."},{"id":"eth_prerequisites","type":"multi_select","prompt":"Welche Startvoraussetzungen müssen vor Analysebeginn geklärt sein?","options":[{"id":"ethics","label":"Ethikvotum/Amendment"},{"id":"consent","label":"Einwilligung/Broad Consent/Opt-out bzw. vorhandene Governance-Grundlage prüfen"},{"id":"material_release","label":"Pathologische Materialfreigabe"},{"id":"reserve","label":"Sicherung diagnostischer Reserve"},{"id":"pseudonym","label":"Pseudonymisierungs-/Schlüsselkonzept"},{"id":"roles","label":"Rollen- und Zugriffskonzept"},{"id":"side_findings","label":"Definierter Umgang mit Nebenbefund/Keimbahnverdacht"},{"id":"sharing","label":"Data-Sharing-Konzept"},{"id":"leftover_note","label":"Ein Restmaterial-Vermerk als alleinige Freigabe"}],"correct":["ethics","consent","material_release","reserve","pseudonym","roles","side_findings","sharing"],"rationale":"Governance umfasst Ethik, Einwilligung/Rechtsgrundlage, Materialschutz, Datenschutz, Rollen, Nebenbefunde und spätere Datennutzung."},{"id":"eth_anonymization","type":"single_choice","prompt":"Löst vollständige Anonymisierung die Governance-Fragen automatisch?","options":[{"id":"no","label":"Nein. Sie ersetzt Material-/Ethikprüfung nicht und kann Follow-up oder geregelte Rückmeldung erschweren."},{"id":"yes","label":"Ja. Nach Anonymisierung sind Einwilligung, Materialfreigabe und Nebenbefunde nicht mehr relevant."},{"id":"always_best","label":"Ja. Vollständige Anonymisierung ist für jede translationale Studie der bevorzugte Standard."}],"correct":["no"],"rationale":"Anonymisierung ist ein Datenschutzkonzept, kein universeller Governance-Radiergummi."},{"id":"eth_material_guard","type":"single_choice","prompt":"Die Materialprüfung zeigt bei mehreren kleinen Biopsien eine knappe diagnostische Restreserve. Was ist richtig?","options":[{"id":"exclude_reduce","label":"Fälle ausschließen oder Forschungsumfang reduzieren und die diagnostische Reserve sichern."},{"id":"use_all","label":"Alle Fälle verwenden, damit die wissenschaftliche Fallzahl maximal bleibt."},{"id":"split_half","label":"Unabhängig von der Restreserve immer die Hälfte des Materials für Forschung reservieren."}],"correct":["exclude_reduce"],"rationale":"Eine kleinere governance-saubere Kohorte ist besser als eine größere Kohorte auf Kosten zukünftiger Diagnostik."}],"decision_task":"Erstellen Sie ein Governance- und Freigabekonzept, das den gesamten Lebenszyklus des Projektes abdeckt: Projektstart, Materialnutzung, klinische Daten, Pseudonymisierung/Zugriff, genetische Nebenbefunde sowie Publikation und Data Sharing.","expected_path":["Projekt zunächst auf Hold setzen.","Forschungsfrage/PICO sauber definieren.","Ethik-/Einwilligungslage prüfen.","Pathologische Materialfreigabe durchführen.","Diagnostische Reserve schützen.","Pseudonymisierung und Rollen/Zugriff definieren.","Minimaldatensatz festlegen.","Nebenbefund-/Keimbahnverdachtsprozess vorab etablieren.","Data Sharing mit Governance abstimmen.","Erst danach Material freigeben und Analyse starten."],"acceptable_alternatives":["Kohorte auf Fälle mit eindeutiger Governance- und Materiallage einschränken.","Forschungsumfang reduzieren.","Projekt als kleinere Pilotstudie durchführen.","Data Sharing begrenzen, wenn der ursprüngliche Governance-Rahmen dies nicht trägt."],"low_value_traps":[{"label":"Restmaterial = frei verfügbar","why_bad":"Patientenbezogenes Material bleibt governance-relevant."},{"label":"Anonymisierung löst alles","why_bad":"Material-, Ethik- und Rückmeldefragen bleiben bestehen."},{"label":"Fallzahl vor Materialschutz","why_bad":"Forschung darf diagnostische Reserve nicht verdrängen."},{"label":"Nebenbefunde später klären","why_bad":"Der Prozess muss existieren, bevor ein vorhersehbarer Befund entsteht."},{"label":"Data Sharing erst bei Publikation prüfen","why_bad":"Zu spät, wenn Daten bereits in einer dafür ungeeigneten Struktur erhoben wurden."}],"twist":{"title":"Der vorhersehbare Nebenbefund wird Realität","content":"Das Projekt wurde nach abgeschlossener Governance-Prüfung gestartet. Während der Tumor-only-Auswertung findet sich bei einem Fall eine potenziell pathogene BRCA1-Konstellation mit möglichem Keimbahnbezug. Im Team kommt sofort die Frage auf: ‚Müssen wir jetzt die Patientin anrufen?‘ Die richtige Antwort ist weder ignorieren noch sofort melden. Es greift der vor Projektstart definierte Nebenbefund-/Keimbahnverdachtsprozess.","why_critical":"Der Wert guter Governance zeigt sich nicht im Ethikantrag, sondern in dem Moment, in dem eine vorhersehbare schwierige Situation tatsächlich auftritt."},"result_packages":[{"id":"optimal","title":"Governance first","class":"optimal","result":"Ethik, Consent/Governance, Materialreserve, Datenschutz, Zugriffsrollen, Nebenbefundprozess und Data Sharing sind vor Analyse geklärt. Problematische Blöcke werden geschützt bzw. ausgeschlossen.","feedback":"Sehr gute Projektarchitektur."},{"id":"wrong","title":"Start now","class":"wrong","result":"Material wird verarbeitet, bevor Einwilligungslage und diagnostische Reserve geklärt sind.","feedback":"Kritischer Governance-Fehler."},{"id":"incomplete","title":"Anonymize everything","class":"incomplete","result":"Fallbezug wird früh vollständig entfernt; Follow-up und geregelte Rückmeldung werden problematisch, während andere Governance-Fragen offen bleiben.","feedback":"Technischer Datenschutzschritt ersetzt kein Gesamtkonzept."},{"id":"material_wrong","title":"Science before material","class":"wrong","result":"Kleine diagnostisch relevante Blöcke werden für maximale Fallzahl aufgebraucht.","feedback":"Forschungsinteresse wurde vor Materialschutz gestellt."}],"followup_logic":[{"trigger":"Diagnostische Reserve knapp","action":"Fall ausschließen oder Forschungsverbrauch reduzieren.","consequence":"Kleinere, aber verantwortbare Kohorte."},{"trigger":"Potenzieller Keimbahnverdacht","action":"Vordefinierten Nebenbefund-/Humangenetikprozess anwenden.","consequence":"Keine ad-hoc-Kommunikation."},{"trigger":"Externer Kooperationspartner fordert Rohdaten","action":"Consent-/Governance-/Data-Sharing-Rahmen prüfen.","consequence":"Nur zulässige Daten weitergeben bzw. Sharing begrenzen."},{"trigger":"Governance ungeklärt","action":"Projekt bleibt auf Hold.","consequence":"Keine Materialfreigabe."}],"debrief_points":["Governance ist Teil des Studiendesigns.","Restmaterial ist nicht automatisch frei verfügbares Forschungsmaterial.","Diagnostische Restreserve hat Vorrang.","Pseudonymisierung, Anonymisierung und Governance sind nicht dasselbe.","Vorhersehbare genetische Nebenbefunde benötigen einen vorher definierten Prozess.","Gutes Forschungsdesign umfasst bereits den späteren Umgang mit Publikation und Data Sharing.","Eine kleinere, sauber definierte Kohorte kann wissenschaftlich und ethisch stärker sein als maximale Fallzahl."],"instructor_notes":{"model_answer":"Das Projekt darf erst nach Klärung von Ethik-/Einwilligungslage, Datenschutz, Materialfreigabe und Nebenbefundmanagement starten. Die diagnostische Reserve wird für jeden Fall gesichert. Klinische Daten werden pseudonymisiert und rollenbasiert verarbeitet. Ein möglicher Keimbahnverdacht aus Tumor-only-Daten wird nicht ad hoc kommuniziert, sondern über einen vorher definierten Prozess behandelt. Data Sharing wird nur innerhalb des festgelegten Governance-Rahmens durchgeführt.","scoring_focus":["Governance vor Projektstart.","Materialschutz.","Pseudonymisierung/Zugriff.","Nebenbefundprozess.","Keine ad-hoc-Rückmeldung.","Data Sharing vorausgedacht."],"discussion_questions":["Wann ist eine kleinere Kohorte die bessere Studie?","Warum ist vollständige Anonymisierung nicht immer die eleganteste Lösung?","Welche Konsequenzen hat Tumor-only-Sequenzierung bereits bei der Studienplanung?","Wann muss Data Sharing konzeptionell geplant werden?"]},"report_additions":{"content_status":"DE curated deep dive","key_turning_point":"Potenzieller BRCA1-Keimbahnverdacht","core_message":"Governance muss vor dem Projektstart stehen","pattern":"Start → Material → Analyse → Nebenbefund → Data Sharing"},"is_signature_case":true}};
const LOCALIZED={"en":{"MTB_CNS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"MTB_CNS_001_v1_0","title":"Glioblastoma before treatment decision: correctly integrate IDH, MGMT and methylation","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Molecular pathology / neuropathology / MTB","estimated_minutes_deep":"15–18","learning_objectives":["Recognize diagnostic classification, molecular characterization and predictive biomarkers as distinct levels.","Correctly assign the functional roles of IDH, MGMT promoter methylation and the methylation classifier.","Recognize that broad DNA NGS does not automatically answer every clinical question.","Prioritize an integrated report according to clinical relevance rather than technical breadth."],"opening_scene":"Friday lunchtime in neuropathology. The report for a 68-year-old patient after subtotal resection of a high-grade primary brain tumor has to be finalized before the upcoming neuro-oncology treatment planning. Histology strongly suggests glioblastoma. Neuro-oncology, however, also needs an integrated classification and explicitly an assessment of the temozolomide context. Sufficient tissue is available. The key question is therefore not: How much can we test? But rather: Which test answers which clinical question?","case_briefing":"68-year-old patient with seizure and progressive aphasia. MRI shows a ring-enhancing mass. After subtotal resection, histology demonstrates a high-grade glial tumor with necrosis and microvascular proliferation; Ki-67 approximately 30–40%. The working diagnosis is glioblastoma. For molecular integration and treatment planning, IDH status, MGMT promoter methylation and the methylation class in particular still need to be clarified.","context_cards":[{"title":"Clinical context","content":"Seizure, progressive aphasia, subtotal resection; chemoradiotherapy is being discussed.","teaching_point":"The molecular report serves different diagnostic and therapeutic functions."},{"title":"Histology","content":"High-grade glial tumor with necrosis and microvascular proliferation; Ki-67 approx. 30–40%.","teaching_point":"Morphology is strongly suggestive but does not replace molecular integration."},{"title":"Tissue","content":"FFPE resection specimen, block T3, approx. 80% tumor; viable tumor areas can be marked; 14 sections can be planned.","teaching_point":"There is no acute tissue shortage, but rational testing is still required."},{"title":"Clinical request","content":"Classification, prognosis and the temozolomide context should be clarified before treatment planning.","teaching_point":"Not every marker answers the same question."}],"pre_results":[{"title":"H&E","content":"High-grade glial tumor with necrosis and microvascular proliferation."},{"title":"Ki-67","content":"High, approximately 30–40%."},{"title":"Working diagnosis","content":"Glioblastoma likely."},{"title":"QC / unresolved levels","content":"High tumor content; DNA-based and epigenetic analyses are technically evaluable. IDH status, MGMT promoter methylation and molecular integration remain unresolved."}],"material_or_resource_constraints":["The report should be finalized before the upcoming treatment planning.","The available tissue permits several investigations but does not justify diagnostically meaningless maximal testing.","DNA-based sequencing and methylation analyses answer different questions.","A technically extensive report can still be clinically incomplete."],"reasoning_gate_upgrade":[{"id":"cns_question_levels","type":"multi_select","prompt":"Which levels must you distinguish in this case?","options":[{"id":"classification","label":"Histologic/molecular classification"},{"id":"tmz_prediction","label":"Predictive temozolomide context"},{"id":"molecular_characterization","label":"Additional molecular characterization"},{"id":"max_gene_count","label":"The highest possible number of genes tested"},{"id":"tmb_msi_primary","label":"TMB/MSI as the primary decision anchor"}],"correct":["classification","tmz_prediction","molecular_characterization"],"rationale":"Diagnostic value is determined by the clinical question. Testing as many genes as possible is not a diagnostic level in itself."},{"id":"cns_marker_roles","type":"multi_select","prompt":"Which assignments are correct?","options":[{"id":"idh_classification","label":"IDH → molecular classification"},{"id":"mgmt_prediction","label":"MGMT promoter methylation → epigenetic/predictive treatment context"},{"id":"classifier_integration","label":"Methylation classifier → additional diagnostic classification/integration level"},{"id":"ngs_characterization","label":"Glioma NGS → additional molecular characterization"},{"id":"mgmt_driver","label":"MGMT → classic driver mutation in DNA NGS"}],"correct":["idh_classification","mgmt_prediction","classifier_integration","ngs_characterization"],"rationale":"IDH, MGMT and the methylation classifier answer different questions; MGMT is not a classic driver mutation in this context."},{"id":"cns_strategy","type":"single_choice","prompt":"Which diagnostic strategy answers the clinical question most completely?","options":[{"id":"integrated","label":"Clarify IDH status, assess MGMT promoter methylation separately and appropriately integrate the methylation classifier/glioma NGS."},{"id":"dna_only","label":"Perform broad DNA NGS only and assume that this answers the entire clinical question."},{"id":"tmb_first","label":"Prioritize TMB/MSI because the tumor is high grade."},{"id":"mgmt_mutation","label":"Look for MGMT as a mutation within the NGS panel."}],"correct":["integrated"],"rationale":"Diagnostic breadth does not replace a method-specific question. MGMT promoter methylation must be addressed separately."}],"decision_task":"Plan the molecular workup and then formulate for the neuro-oncology board: Which findings support the integrated diagnosis, which finding is relevant to the temozolomide context, and which diagnostic information is not replaced by DNA NGS alone?","expected_path":["Use morphology and clinical context as the starting point.","Clarify IDH status.","Plan MGMT promoter methylation as a separate epigenetic investigation.","Appropriately place the methylation classifier within classification/diagnostic integration.","Use glioma NGS as an additional molecular level.","Weight results according to their clinical function.","Do not describe MGMT as a driver mutation."],"acceptable_alternatives":["IDH can be clarified by targeted IHC/sequencing or suitable glioma NGS diagnostics.","A broader molecular panel may provide additional relevant information as long as it remains clear which clinical questions it does not answer.","The diagnostic scope may vary depending on prior findings and institutional workflow."],"low_value_traps":[{"label":"Broad panel = complete diagnostics","why_bad":"Technical breadth does not tell you whether the specific clinical question has been covered."},{"label":"MGMT as a mutation","why_bad":"Confuses epigenetic and genetic diagnostic levels."},{"label":"TMB/MSI as the main focus","why_bad":"Not a primary decision anchor for the present IDH/MGMT/temozolomide question."},{"label":"Simply listing markers","why_bad":"An integrated report must explain which information is diagnostically or predictively relevant."}],"twist":{"title":"A large panel – and the crucial information is still missing","content":"Sequencing shows IDH1/2 wild type, a TERT promoter mutation and an EGFR amplification signal; the molecular findings fit the glioblastoma context. In the board, someone says: Then we are done. However, MGMT has not been assessed. Only targeted follow-up shows a methylated MGMT promoter; the methylation classifier supports the class glioblastoma, IDH-wildtype, with a high classifier score.","why_critical":"A diagnostically extensive result can still leave a specific treatment question unanswered. The epigenetic MGMT level is not replaced by conventional DNA NGS."},"result_packages":[{"id":"optimal","title":"Integrated report","class":"optimal","result":"IDH-wildtype; MGMT promoter methylated; methylation class supports glioblastoma, IDH-wildtype; additional molecular findings are compatible with the overall context.","feedback":"Very good. The individual methods are integrated according to their diagnostic function."},{"id":"incomplete","title":"Extensive sequencing, unresolved treatment question","class":"incomplete","result":"Extensive DNA NGS, but no MGMT promoter methylation result.","feedback":"Technically extensive, clinically incomplete. The temozolomide question remains unresolved."},{"id":"wrong","title":"Wrong focus","class":"wrong","result":"Additional TMB/MSI testing without complete IDH/MGMT integration.","feedback":"The investigations do not address the central question of the case."}],"followup_logic":[{"trigger":"MGMT missing","action":"Add targeted MGMT methylation analysis.","consequence":"Treatment interpretation remains incomplete until then."},{"trigger":"MGMT is interpreted as a mutation","action":"Address the conceptual error in the debrief.","consequence":"Clear reasoning penalty."},{"trigger":"Complete integration","action":"Formulate the final neuro-oncology/MTB report.","consequence":"Complete deep-dive pathway."}],"debrief_points":["Morphology, molecular classification and predictive biomarkers answer different questions.","MGMT promoter methylation is an epigenetic diagnostic level.","A broad sequencing panel is not automatically a complete clinical report.","Good molecular pathology prioritizes information according to its relevance for diagnosis and decision-making."],"instructor_notes":{"model_answer":"The morphologic constellation is consistent with a high-grade glial tumor. IDH status is determined for integrated diagnosis. MGMT promoter methylation must be assessed separately as an epigenetic predictive marker and is not replaced by conventional DNA NGS. The methylation classifier and glioma NGS can complement diagnostic integration. The decisive point is the functional weighting of the individual findings.","scoring_focus":["Diagnostic levels clearly separated.","IDH correctly classified.","MGMT correctly classified.","No overcalling of broad sequencing.","Clear MTB/neuro-oncology communication."],"discussion_questions":["When does a broad panel provide real added value?","What does complete diagnostics mean in this case?","How should different diagnostic levels be made linguistically visible in the report?"]},"report_additions":{"content_status":"EN curated deep dive","key_turning_point":"Broad NGS, but MGMT is missing","core_trap":"MGMT is not a classic driver mutation","pattern":"Morphology → classification → prediction → integration"},"is_signature_case":true},"LAB_DOC_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"LAB_DOC_001_v1_0","title":"‘PCR as always’: analytically valid, yet still a QM case","domain":"LAB","target_course":"QM Basics","deep_dive_priority":"signature","target_role":"Laboratory management / QM / molecular pathology laboratory","estimated_minutes_deep":"12–15","learning_objectives":["Assess analytical validity and process/documentation conformity separately.","Systematically reconstruct available primary data before reflexively repeating the test.","Release a weak patient sample on a risk-based basis when the analytical foundation has been robustly reconstructed.","Recognize that a relevant systemic documentation gap must still be handled as a deviation/near miss and, in this case, escalated into a CAPA despite successful reconstruction.","Verify the effectiveness of a CAPA."],"opening_scene":"During the morning, internal audit preparation begins in the molecular pathology laboratory. A qPCR KRAS run is selected as a sample. The laboratory notebook contains exactly one sentence: ‘PCR as always. Worked. Sample 4 weak.’ The colleague remembers the run and says: ‘Everything was fine. The controls were good.’ The result for sample 4 is clinically relevant. The question is now not only: Was the PCR technically sound? But rather: Can we still demonstrate that robustly today – and what do we do if we can?","case_briefing":"Routine qPCR KRAS hotspot assay. The laboratory notebook entry contains neither an adequate method reference nor a complete audit trail. Missing items include date/time, operator, SOP version, unique sample IDs, kit/lot/expiry, instrument and run ID, positive/negative/NTC controls, Ct values/replicates, raw-data path and the documented expert assessment of the weak sample. However, the actual raw data and metadata may still be available in the instrument, LIMS and electronic systems.","context_cards":[{"title":"Original entry","content":"‘PCR as always. Worked. Sample 4 weak.’","teaching_point":"Plausibility is not traceability."},{"title":"Assay","content":"Routine qPCR KRAS hotspot assay.","teaching_point":"Routine work does not reduce documentation requirements."},{"title":"Patient sample","content":"Sample 4 shows a weak signal.","teaching_point":"Borderline/weak signals in particular require traceable primary data and documented assessment."},{"title":"Conflict","content":"Reconstruct, or repeat everything as a precaution?","teaching_point":"Good QM is risk-based, not reflexively maximalist."}],"pre_results":[{"title":"Documentation status","content":"The original documentation is inadequate, but there is no indication of a known technical run failure."},{"title":"Available sources","content":"Instrument export, LIMS and additional electronic metadata are still available."},{"title":"Tissue/time context","content":"Remaining patient material is limited. A repeat would consume additional time and material."},{"title":"Open question","content":"It is not yet clear whether the complete analytical pathway, including the weak sample, can be robustly reconstructed."}],"material_or_resource_constraints":["Patient material is not available without limit.","Every repeat consumes material and causes time and resource expenditure.","An unnecessary repeat is therefore not automatically safer.","Conversely, release without robust reconstruction would not be acceptable.","QM measures should address the actual root cause rather than merely remove symptoms."],"reasoning_gate_upgrade":[{"id":"labdoc_primary_problem","type":"single_choice","prompt":"What is the primary problem?","options":[{"id":"auto_invalid","label":"The run is automatically analytically invalid."},{"id":"traceability","label":"Traceability and the documented basis for assessment are inadequate."},{"id":"weak_never_release","label":"A weak sample can never be released in principle."},{"id":"routine_less_docs","label":"Routine PCR requires less documentation."}],"correct":["traceability"],"rationale":"A documentation deficiency does not automatically imply an analytical failure. The first step is to determine whether analytical validity can be reconstructed from source data."},{"id":"labdoc_reconstruct","type":"multi_select","prompt":"Which information must be used for an audit-ready reconstruction?","options":[{"id":"who_when","label":"Operator and time point"},{"id":"sop","label":"SOP version"},{"id":"lot","label":"Kit/reagent lot and expiry date"},{"id":"sample_id","label":"Unambiguous sample identity"},{"id":"run_id","label":"Instrument and run ID"},{"id":"controls","label":"Positive/negative/NTC controls"},{"id":"ct_replicates","label":"Ct values and replicates"},{"id":"rawdata","label":"Raw-data path/primary data"},{"id":"sample4_review","label":"Expert assessment of sample 4"},{"id":"memory_only","label":"The colleague's verbal recollection as the sole evidence"}],"correct":["who_when","sop","lot","sample_id","run_id","controls","ct_replicates","rawdata","sample4_review"],"rationale":"Reconstruction must be source-based and audit-ready; memory alone is insufficient."},{"id":"labdoc_release_or_repeat","type":"single_choice","prompt":"The reconstruction shows unambiguous sample assignment, valid SOP/lot data, valid controls, complete raw data and a reproducible weak signal in sample 4. What is now the correct action?","options":[{"id":"release_after_review","label":"Transparently document the reconstruction and expert reassessment; release sample 4; avoid an unnecessary repeat."},{"id":"repeat_all","label":"Repeat the complete run regardless of the available primary data."},{"id":"weak_hold","label":"Do not release sample 4 because a weak signal is inherently unreliable."},{"id":"release_no_docs","label":"Simply release the result and leave the original documentation unchanged."}],"correct":["release_after_review"],"rationale":"Analytical validity is traceable from the primary data. Repetition is not an end in itself and would unnecessarily consume material, time and resources."},{"id":"labdoc_capa","type":"single_choice","prompt":"Is the case closed after the successful reconstruction of the result?","options":[{"id":"done_no_harm","label":"Yes. No patient harm occurred."},{"id":"near_miss_capa","label":"No. The relevant documentation gap is assessed on a risk basis as a deviation/near miss; the systemic problem identified here is addressed with CAPA and an effectiveness check."},{"id":"verbal_reminder","label":"An informal reminder to the team is sufficient."},{"id":"rewrite_old","label":"Delete the old laboratory notebook entry and rewrite it."}],"correct":["near_miss_capa"],"rationale":"Successful reconstruction prevents an error but does not eliminate the systemic weakness that nearly enabled it."}],"decision_task":"Make two separate decisions: Is the specific patient result releasable after reconstruction? What QM consequence follows from the inadequate original process?","expected_path":["Recognize the documentation deficiency.","Do not automatically discard the result.","Systematically reconstruct primary data and metadata.","Confirm run validity using the controls.","Reassess the weak sample professionally using Ct values/replicates and raw data.","Release the result transparently.","Record the original documentation deficiency as a deviation/near miss.","Analyze the root cause.","Implement CAPA.","Verify effectiveness using subsequent documentation."],"acceptable_alternatives":["A repeat is justifiable if decisive elements such as sample identity, controls, primary data or the expert assessment cannot be robustly reconstructed.","Repetition follows from risk – not merely from the existence of a deviation."],"low_value_traps":[{"label":"Always repeat when there is a deviation","why_bad":"May unnecessarily consume patient material, time and resources and does not solve the process root cause."},{"label":"Nothing happened, so no CAPA","why_bad":"The near miss and systemic process weakness remain."},{"label":"Only add the Ct value afterward","why_bad":"Traceability remains incomplete."},{"label":"Training only","why_bad":"Training without linkage to the root cause and without an effectiveness check is not a robust CAPA."},{"label":"Verbal recollection","why_bad":"Not an audit-ready substitute for primary data."}],"twist":{"title":"The weak sample is actually releasable","content":"Reconstruction shows that the run was technically valid, the controls were correct and sample 4 has a reproducible weak signal in the primary data. After documented expert reassessment, the sample can be released; a complete repeat is not required. However, a sample review of additional laboratory notebook entries reveals several similarly abbreviated formulations – what appeared to be an isolated case becomes a systemic documentation weakness.","why_critical":"Analytical validity and process conformity are separate questions. The specific result can be salvaged while the near miss still requires risk-based deviation/CAPA handling."},"result_packages":[{"id":"optimal","title":"Risk-based release + CAPA","class":"optimal","result":"Run and sample 4 fully reconstructed, professionally released, deviation documented, root cause addressed, CAPA established with effectiveness check.","feedback":"Very good. Analytical validity and process conformity were assessed separately and on a risk basis."},{"id":"incomplete","title":"Safety reflex: repeat everything","class":"incomplete","result":"Complete run repeated even though all relevant primary data were available.","feedback":"Repetition is not an end in itself. Material and resource consumption were not considered; the process root cause remains unresolved."},{"id":"release_no_capa","title":"Correct result, wrong QM","class":"incomplete","result":"Sample correctly released, but the documentation problem is then considered closed.","feedback":"The specific result is salvaged, but the systemic cause is not."},{"id":"wrong","title":"Release based only on recollection","class":"wrong","result":"Release based solely on routine and memory.","feedback":"Not audit-ready and not robust."}],"followup_logic":[{"trigger":"Primary data cannot be fully reconstructed","action":"Hold and perform targeted repeat testing and/or further clarification.","consequence":"No release without a robust basis."},{"trigger":"Complete reconstruction plus valid controls","action":"Perform and document expert reassessment.","consequence":"Release may be possible."},{"trigger":"Systemic documentation gap","action":"Perform root-cause analysis and CAPA.","consequence":"Adapt template/process/training according to the identified cause."},{"trigger":"CAPA implemented","action":"Review a sample of subsequent qPCR documentation.","consequence":"Effectiveness check rather than mere closure of the action."}],"debrief_points":["Analytical validity and process conformity are different questions.","A deviation does not automatically make a result invalid.","A repeat must be justified on a risk basis.","Limited material, time and resources belong in the risk assessment.","A near miss is particularly instructive when the weakness is identified before harm occurs.","CAPA ends with an effectiveness check, not with ‘staff trained’."],"instructor_notes":{"model_answer":"First, traceability is reconstructed from LIMS, instrument export, SOP, lot, control and raw-data information. If sample identity, run validity and the weak positivity of sample 4 can be robustly traced, the result can be released after documented reassessment. A blanket repeat is not required. The original documentation deficiency is nevertheless handled as a relevant deviation with near-miss character. If a systemic problem is identified, root-cause analysis, appropriate CAPA and an effectiveness check follow.","scoring_focus":["Reconstruction before repeat.","Primary data rather than recollection.","Correct release of the weak sample.","Deviation/near miss not ignored.","CAPA linked to root cause.","Effectiveness check."],"discussion_questions":["When is repetition actually necessary?","Can a result be valid even though the process was defective?","Where is the boundary between correction and CAPA?","Why does greater safety not automatically mean more repeats?"]},"report_additions":{"content_status":"EN curated deep dive","key_turning_point":"Weak sample releasable after reconstruction","core_message":"Analytical validity ≠ process conformity","pattern":"Reconstruction → risk assessment → release → CAPA → effectiveness check"},"is_signature_case":true},"RES_OMICS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_OMICS_001_v1_0","title":"200 DEGs, one biomarker? From an RNA-seq signal to a robust resistance hypothesis","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Translational research / molecular pathology / bioinformatics","estimated_minutes_deep":"18–22","learning_objectives":["Translate DEG lists into biological programs rather than single-gene stories.","Operationalize an omics observation as a testable hypothesis and PICO.","Distinguish discovery, technical validation, morphologic validation and external replication.","Do not overinterpret exploratory results as a finished biomarker.","Prioritize the robustness of a signature over an attractive single gene."],"opening_scene":"Monday morning at the translational research meeting. A doctoral researcher has completed her first RNA-seq analysis: 30 ICI-treated tumors, 15 responders and 15 non-responders. Her slide says: ‘200 significant DEGs.’ Below it is a ranked table. She asks: ‘Which gene should I use as my biomarker now?’ The lowest p-value looks spectacular. But this is exactly where the actual scientific work begins.","case_briefing":"RNA-seq of 30 ICI-treated tumors: 15 responders and 15 non-responders. In non-responders, TGFB1, COL1A1, CXCL12, ACTA2, FN1 and other ECM genes are increased, while HLA-A, B2M, TAP1, CXCL9 and GZMB are decreased. Pathway analysis shows high TGFβ/ECM and low antigen presentation/T-cell activation. Clinically, stroma-rich tumors are associated with poorer ICI response.","context_cards":[{"title":"Discovery cohort","content":"30 ICI-treated tumors, 15 responders versus 15 non-responders.","teaching_point":"Small discovery cohorts are suitable for hypothesis generation, not automatically for a biomarker claim."},{"title":"RNA-seq signal","content":"200 differentially expressed genes.","teaching_point":"A gene list is not yet a biological explanation."},{"title":"Biological pattern","content":"High TGFβ/ECM, low antigen presentation/T-cell activation.","teaching_point":"Coordinated programs can be more informative than a single gene."},{"title":"Translational goal","content":"Develop a mechanism and a clinically testable signature.","teaching_point":"Moving from omics to translation requires several levels of validation."}],"pre_results":[{"title":"Non-responders – increased","content":"TGFB1, COL1A1, CXCL12, ACTA2, FN1 and other ECM genes."},{"title":"Non-responders – decreased","content":"HLA-A, B2M, TAP1, CXCL9 and GZMB."},{"title":"Pathway enrichment","content":"High TGFβ/ECM; low antigen presentation/T-cell activation."},{"title":"Not yet decided","content":"The strongest single gene, a signature and a biological program are not the same thing. Interpretation must be actively prioritized."}],"material_or_resource_constraints":["Discovery cohort: n = 30.","Multiple testing/FDR must be taken into account.","Clinical confounders such as treatment, tumor entity, ECOG and tumor content must be captured.","The budget is sufficient for targeted technical and morphologic validation, not for unlimited multi-omics.","Independent validation is required before making a biomarker claim."],"reasoning_gate_upgrade":[{"id":"omics_from_degs","type":"single_choice","prompt":"How do 200 DEGs become a robust research question?","options":[{"id":"lowest_p","label":"Select the gene with the lowest p-value."},{"id":"all_genes","label":"Report all 200 genes as equally important."},{"id":"programs","label":"Identify coordinated biological programs and shared pathways."},{"id":"expected_only","label":"Keep only genes that fit the expected story."}],"correct":["programs"],"rationale":"The shared stromal/immune pattern provides a more robust hypothesis than an isolated single gene."},{"id":"omics_hypothesis","type":"single_choice","prompt":"Which hypothesis best fits the available data?","options":[{"id":"stroma_immune","label":"Primary ICI non-response is associated with a stromal/TGFβ-dominated and simultaneously antigen-poor tumor microenvironment."},{"id":"tgfb1_marker","label":"TGFB1 is the new predictive biomarker."},{"id":"all_degs_explain","label":"The 200 DEGs already fully explain ICI resistance."},{"id":"one_resistance_gene","label":"All non-responders have the same resistance gene."}],"correct":["stroma_immune"],"rationale":"The hypothesis integrates several coordinated expression programs and remains testable without overcalling an exploratory single hit."},{"id":"omics_pico","type":"multi_select","prompt":"Which elements belong to a clean operationalization of the hypothesis?","options":[{"id":"population","label":"Population: ICI-treated tumors"},{"id":"exposure","label":"Exposure/signature: high CAF/TGFβ signature"},{"id":"comparison","label":"Comparison: low signature"},{"id":"outcome","label":"Outcome: response/PFS"},{"id":"score_cutoff","label":"Define the score/cutoff strategy before validation"},{"id":"confounders","label":"Define relevant confounders and the analysis plan"},{"id":"posthoc_cutoff","label":"Set the cutoff only after seeing the most favorable validation result"}],"correct":["population","exposure","comparison","outcome","score_cutoff","confounders"],"rationale":"Hypothesis, PICO, score/cutoff and analysis plan must be operationalized before validation."},{"id":"omics_validation","type":"multi_select","prompt":"Which validation steps are robust for translational development?","options":[{"id":"targeted","label":"Targeted RNA/qPCR/NanoString"},{"id":"external","label":"Independent ICI cohort"},{"id":"morphology","label":"αSMA/FAP/CD8/HLA-I/B2M as a morphologic bridge"},{"id":"fdr","label":"Report FDR and multiple testing transparently"},{"id":"heatmap_only","label":"Draw the heatmap again"},{"id":"single_wb","label":"Confirm only the strongest single gene by Western blot"}],"correct":["targeted","external","morphology","fdr"],"rationale":"Technical, morphologic and independent validation complement each other; visualization alone or a single confirmation assay is insufficient for a signature hypothesis."}],"decision_task":"Develop a robust translational strategy from the exploratory RNA-seq analysis: biological hypothesis, PICO, signature/analysis concept, technical validation, morphologic bridge, external validation and the boundary of a permissible biomarker claim.","expected_path":["Do not treat the DEG list as the final product.","Prioritize the pathway/network level.","Formulate a stromal/TGFβ-dominated, antigen-poor pattern.","Define hypothesis and PICO.","Operationalize the signature.","Account for FDR and confounders.","Perform targeted technical validation.","Link the findings morphologically using TME markers.","Use an independent cohort.","Only then discuss biomarker potential."],"acceptable_alternatives":["Conclude the study explicitly as exploratory without a biomarker claim.","Develop a focused smaller signature rather than a complex score.","Use targeted expression/NanoString instead of repeat RNA-seq for technical validation.","Add functional validation if the mechanistic question is central."],"low_value_traps":[{"label":"Lowest p-value = biomarker","why_bad":"Single genes may be unstable and lose the biological context."},{"label":"Heatmap = validation","why_bad":"Visualization does not demonstrate independent reproducibility."},{"label":"200 DEGs as the result","why_bad":"Data volume does not replace a hypothesis."},{"label":"Optimize the cutoff afterward","why_bad":"Risk of overfitting/HARKing."},{"label":"Remove results that do not fit","why_bad":"Selective reporting."}],"twist":{"title":"The ‘best gene’ disappears – the biology remains","content":"In an independent validation cohort, the single gene with the lowest discovery p-value does not replicate convincingly. In contrast, the predefined stromal/immune signature continues to show the same coordinated pattern: increased stromal/TGFβ component and decreased antigen-presentation/T-cell component. Morphologic validation also supports the program-level interpretation.","why_critical":"The most attractive individual discovery hit is not necessarily the most robust biological signal. The case separates a single gene, a signature, a mechanism and a validated biomarker from one another."},"result_packages":[{"id":"optimal","title":"Signature hypothesis validated","class":"optimal","result":"Pathway-based hypothesis, predefined signature, technical validation, morphologic bridge and independent cohort show a consistent pattern.","feedback":"Very good translational development. Biomarker potential can now be discussed cautiously."},{"id":"incomplete","title":"Single-gene collapse","class":"incomplete","result":"The strongest discovery single gene does not replicate, but the overarching signature remains consistent.","feedback":"This is not a failure of the project if the biological hypothesis is independently supported."},{"id":"heatmap_story","title":"Beautiful heatmap, no validation","class":"incomplete","result":"Exploratory cluster without independent replication.","feedback":"Interesting, but not a robust biomarker."},{"id":"wrong","title":"Overclaim","class":"wrong","result":"The discovery signature is directly described as a predictive biomarker.","feedback":"The data are being interpreted beyond their evidentiary strength."}],"followup_logic":[{"trigger":"Only a single gene prioritized","action":"Bring pathway/network analysis back into the reasoning.","consequence":"Reasoning cap for a single-marker interpretation."},{"trigger":"No independent validation","action":"Label the result as exploratory.","consequence":"No biomarker claim."},{"trigger":"Signature replicates","action":"Assess morphologic and clinical translation.","consequence":"Optimal deep-dive pathway."}],"debrief_points":["A DEG list is not yet a biological model.","Pathway and signature information can be more robust than a single discovery gene.","Technical, morphologic and external validation answer different questions.","Discovery and validation must be kept separate.","Failure of a single hit to replicate can improve a hypothesis rather than destroy the project.","A biomarker is the result of a validation chain, not of a beautiful heatmap."],"instructor_notes":{"model_answer":"The data are first interpreted at pathway/network level. The coordinated TGFβ/ECM-high, antigen-presentation-low pattern is formulated as an exploratory resistance hypothesis. Population, signature, comparison and outcome are then operationalized. The signature is validated technically, morphologically and in an independent cohort. Single genes and cutoffs are not post hoc overinterpreted as finished biomarkers.","scoring_focus":["Pathway before single gene.","Clear hypothesis/PICO.","FDR/confounders accounted for.","Discovery versus validation separated.","Morphologic bridge.","Biomarker claim limited appropriately."],"discussion_questions":["When is a signature superior to a single marker?","What does independent validation really mean?","How can a negative validation result be scientifically valuable?","When can an association become a biomarker project?"]},"report_additions":{"content_status":"EN curated deep dive","key_turning_point":"Best single hit does not replicate","core_message":"DEG → pathway → hypothesis → signature → validation","pattern":"Do not confuse discovery with proof of a biomarker"},"is_signature_case":true},"RES_ETH_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_ETH_001_v1_0","title":"120 archive blocks and no clear consent: may the project start?","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Translational project leadership / pathology / research QM","estimated_minutes_deep":"18–22","learning_objectives":["Understand governance as a prerequisite for scientific work rather than a downstream formality.","Plan ethics/consent, tissue protection, data protection and incidental-finding management as separate components.","Recognize why leftover material and anonymization are not blanket approvals.","Plan a research decision so that later germline-suspicion and data-sharing scenarios are already covered."],"opening_scene":"A research group presents a new project: 120 archived FFPE tumor blocks are to be analyzed with an expanded DNA/RNA panel for new resistance markers. The assay, bioinformatics and budget are in place. The project lead says: ‘It is only leftover material. We can start next week.’ However, the blocks come from different years, the consent situation is inconsistent, and the diagnostic reserve is unclear for some small blocks. In addition, the planned tumor-only panel may generate findings suggestive of potentially germline-relevant variants. The first decision therefore has to be made before a single sample is cut.","case_briefing":"Project aim: identify new molecular markers of therapeutic resistance in a retrospective tumor cohort. The plan includes 120 routine FFPE blocks, an expanded DNA/RNA panel, linkage with clinical data and follow-up, publication and, if applicable, external validation/data sharing. The consent/governance situation is inconsistent, tissue reserve is limited in some cases, and a defined process for incidental findings/germline suspicion has not yet been established.","context_cards":[{"title":"Tissue","content":"Routine FFPE, some small blocks; diagnostic reserve is not secured in every case.","teaching_point":"Research must not jeopardize future patient care."},{"title":"Consent","content":"Different collection years and an inconsistent consent/governance situation.","teaching_point":"Archived does not automatically mean freely available."},{"title":"Data","content":"Clinical data and follow-up are to be linked.","teaching_point":"Data protection and access belong in the study design."},{"title":"Genetics","content":"Tumor-only testing may generate a suspicion of a germline finding.","teaching_point":"Feedback pathways must be defined before analysis."},{"title":"Data sharing","content":"External validation and publication are planned.","teaching_point":"Later data use must be covered by the governance framework."}],"pre_results":[{"title":"Cohort","content":"120 potential cases from different collection years."},{"title":"Governance","content":"No uniform consent status; final tissue release is still pending."},{"title":"Data plan","content":"Clinical data are to be added retrospectively; external validation is being discussed as a later option."},{"title":"Foreseeable incidental findings","content":"The tumor-only panel may identify potentially germline-relevant variants; a regulated process must be established before the project starts."}],"material_or_resource_constraints":["Diagnostic tissue reserve takes priority over research consumption.","Not every case has to be included in the final cohort.","Follow-up and the ability to provide regulated feedback may conflict with complete anonymization.","Data scope and access should be limited to what is necessary.","Governance decisions must be made before tissue and data are processed irreversibly."],"reasoning_gate_upgrade":[{"id":"eth_start","type":"single_choice","prompt":"May the project start immediately?","options":[{"id":"leftover_yes","label":"Yes, because it is leftover material."},{"id":"anonymized_yes","label":"Yes, if all case numbers are removed."},{"id":"governance_first","label":"No; first clarify the ethics/consent situation, data protection, tissue release and incidental-finding process."},{"id":"dna_extract_first","label":"Yes, as long as only DNA extraction is performed initially."}],"correct":["governance_first"],"rationale":"Governance and tissue protection must be clarified before irreversible use of samples and data."},{"id":"eth_prerequisites","type":"multi_select","prompt":"Which prerequisites must be clarified before analysis begins?","options":[{"id":"ethics","label":"Ethics approval/amendment"},{"id":"consent","label":"Review consent/broad consent/opt-out or the applicable governance basis"},{"id":"material_release","label":"Pathology tissue release"},{"id":"reserve","label":"Protection of diagnostic reserve"},{"id":"pseudonym","label":"Pseudonymization/key-management concept"},{"id":"roles","label":"Roles and access concept"},{"id":"side_findings","label":"Defined management of incidental findings/germline suspicion"},{"id":"sharing","label":"Data-sharing concept"},{"id":"leftover_note","label":"A leftover-material note as the sole authorization"}],"correct":["ethics","consent","material_release","reserve","pseudonym","roles","side_findings","sharing"],"rationale":"Governance includes ethics, consent/legal basis, tissue protection, data protection, roles, incidental findings and later data use."},{"id":"eth_anonymization","type":"single_choice","prompt":"Does complete anonymization automatically resolve the governance questions?","options":[{"id":"no","label":"No. It does not replace tissue/ethics review and may make follow-up or regulated feedback more difficult."},{"id":"yes","label":"Yes. After anonymization, consent, tissue release and incidental findings are no longer relevant."},{"id":"always_best","label":"Yes. Complete anonymization is the preferred standard for every translational study."}],"correct":["no"],"rationale":"Anonymization is a data-protection concept, not a universal governance eraser."},{"id":"eth_material_guard","type":"single_choice","prompt":"Tissue review shows limited diagnostic reserve in several small biopsies. What is correct?","options":[{"id":"exclude_reduce","label":"Exclude cases or reduce the research scope and protect the diagnostic reserve."},{"id":"use_all","label":"Use all cases so that the scientific sample size remains maximal."},{"id":"split_half","label":"Always reserve half of the tissue for research regardless of the remaining diagnostic reserve."}],"correct":["exclude_reduce"],"rationale":"A smaller, governance-compliant cohort is better than a larger cohort at the expense of future diagnostics."}],"decision_task":"Create a governance and release concept that covers the full project life cycle: project start, tissue use, clinical data, pseudonymization/access, genetic incidental findings, publication and data sharing.","expected_path":["Put the project on hold initially.","Define the research question/PICO clearly.","Review the ethics/consent situation.","Perform pathology tissue release.","Protect diagnostic reserve.","Define pseudonymization and roles/access.","Define a minimal dataset.","Establish the incidental-finding/germline-suspicion process in advance.","Align data sharing with governance.","Only then release tissue and start analysis."],"acceptable_alternatives":["Restrict the cohort to cases with a clear governance and tissue situation.","Reduce the research scope.","Conduct the project as a smaller pilot study.","Limit data sharing if the original governance framework does not support it."],"low_value_traps":[{"label":"Leftover material = freely available","why_bad":"Patient-derived material remains subject to governance."},{"label":"Anonymization solves everything","why_bad":"Tissue, ethics and feedback questions remain."},{"label":"Sample size before tissue protection","why_bad":"Research must not displace diagnostic reserve."},{"label":"Clarify incidental findings later","why_bad":"The process must exist before a foreseeable finding occurs."},{"label":"Check data sharing only at publication","why_bad":"Too late if data have already been collected in a structure that is unsuitable for that use."}],"twist":{"title":"The foreseeable incidental finding becomes reality","content":"The project starts after the governance review has been completed. During tumor-only analysis, one case shows a potentially pathogenic BRCA1 constellation with possible germline relevance. The team immediately asks: ‘Do we have to call the patient now?’ The correct answer is neither to ignore it nor to report it immediately. The incidental-finding/germline-suspicion process defined before the project began is now applied.","why_critical":"The value of good governance is not demonstrated in the ethics application, but at the moment when a foreseeable difficult situation actually occurs."},"result_packages":[{"id":"optimal","title":"Governance first","class":"optimal","result":"Ethics, consent/governance, tissue reserve, data protection, access roles, incidental-finding process and data sharing are clarified before analysis. Problematic blocks are protected or excluded.","feedback":"Very good project architecture."},{"id":"wrong","title":"Start now","class":"wrong","result":"Tissue is processed before the consent situation and diagnostic reserve have been clarified.","feedback":"Critical governance error."},{"id":"incomplete","title":"Anonymize everything","class":"incomplete","result":"Case linkage is removed completely at an early stage; follow-up and regulated feedback become problematic while other governance questions remain open.","feedback":"A technical data-protection step does not replace an overall concept."},{"id":"material_wrong","title":"Science before tissue","class":"wrong","result":"Small diagnostically relevant blocks are consumed to maximize sample size.","feedback":"Research interests were placed ahead of tissue protection."}],"followup_logic":[{"trigger":"Diagnostic reserve limited","action":"Exclude the case or reduce research consumption.","consequence":"Smaller, but responsible cohort."},{"trigger":"Potential germline suspicion","action":"Apply the predefined incidental-finding/clinical-genetics process.","consequence":"No ad hoc communication."},{"trigger":"External collaborator requests raw data","action":"Review the consent/governance/data-sharing framework.","consequence":"Share only permissible data or limit sharing."},{"trigger":"Governance unresolved","action":"Project remains on hold.","consequence":"No tissue release."}],"debrief_points":["Governance is part of study design.","Leftover material is not automatically freely available research material.","Diagnostic tissue reserve has priority.","Pseudonymization, anonymization and governance are not the same thing.","Foreseeable genetic incidental findings require a predefined process.","Good research design already includes later handling of publication and data sharing.","A smaller, well-defined cohort can be scientifically and ethically stronger than the maximum possible sample size."],"instructor_notes":{"model_answer":"The project may start only after clarification of the ethics/consent situation, data protection, tissue release and incidental-finding management. Diagnostic reserve is secured for every case. Clinical data are pseudonymized and processed with role-based access. A possible germline suspicion arising from tumor-only data is not communicated ad hoc but handled through a predefined process. Data sharing is performed only within the established governance framework.","scoring_focus":["Governance before project start.","Tissue protection.","Pseudonymization/access.","Incidental-finding process.","No ad hoc feedback.","Data sharing anticipated in advance."],"discussion_questions":["When is a smaller cohort the better study?","Why is complete anonymization not always the most elegant solution?","What consequences does tumor-only sequencing already have at the study-planning stage?","When must data sharing be planned conceptually?"]},"report_additions":{"content_status":"EN curated deep dive","key_turning_point":"Potential BRCA1 germline suspicion","core_message":"Governance must precede project start","pattern":"Start → tissue → analysis → incidental finding → data sharing"},"is_signature_case":true}},"ro":{"MTB_CNS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"MTB_CNS_001_v1_0","title":"Glioblastom înaintea deciziei terapeutice: integrarea corectă a IDH, MGMT și metilării","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Patologie moleculară / neuropatologie / MTB","estimated_minutes_deep":"15–18","learning_objectives":["Recunoașterea clasificării diagnostice, caracterizării moleculare și biomarkerilor predictivi ca niveluri distincte.","Atribuirea corectă a rolurilor funcționale pentru IDH, metilarea promotorului MGMT și clasificatorul de metilare.","Recunoașterea faptului că un DNA-NGS extins nu răspunde automat tuturor întrebărilor clinice.","Prioritizarea unui raport integrat în funcție de relevanța clinică, nu de amploarea tehnică."],"opening_scene":"Vineri la prânz, în neuropatologie. Raportul unui pacient de 68 de ani, după rezecția subtotală a unei tumori cerebrale primare de grad înalt, trebuie finalizat înaintea planificării terapeutice neuro-oncologice. Histologia sugerează puternic un glioblastom. Totuși, neuro-oncologia are nevoie și de o clasificare integrată și, în mod explicit, de evaluarea contextului temozolomidei. Există suficient material. Întrebarea decisivă nu este, așadar: Cât de mult putem testa? Ci: Ce investigație răspunde cărei întrebări clinice?","case_briefing":"Pacient de 68 de ani cu criză epileptică și afazie progresivă. RMN-ul arată o formațiune cu captare periferică inelară. După rezecția subtotală, histologia evidențiază o tumoră glială de grad înalt cu necroze și proliferare microvasculară; Ki-67 aproximativ 30–40%. Diagnosticul de lucru este glioblastom. Pentru integrarea moleculară și planificarea terapiei trebuie clarificate în special statusul IDH, metilarea promotorului MGMT și clasa de metilare.","context_cards":[{"title":"Context clinic","content":"Criză epileptică, afazie progresivă, rezecție subtotală; se discută radiochimioterapia.","teaching_point":"Raportul molecular are funcții diagnostice și terapeutice diferite."},{"title":"Histologie","content":"Tumoră glială de grad înalt cu necroze și proliferare microvasculară; Ki-67 aprox. 30–40%.","teaching_point":"Morfologia este puternic orientativă, dar nu înlocuiește integrarea moleculară."},{"title":"Material","content":"Piesă de rezecție FFPE, bloc T3, aprox. 80% tumoră; zonele tumorale viabile pot fi marcate; pot fi planificate 14 secțiuni.","teaching_point":"Nu există o lipsă acută de material, dar rămâne necesară o strategie diagnostică rațională."},{"title":"Solicitare clinică","content":"Clasificarea, prognosticul și contextul temozolomidei trebuie clarificate înainte de planificarea terapiei.","teaching_point":"Nu fiecare marker răspunde aceleiași întrebări."}],"pre_results":[{"title":"H&E","content":"Tumoră glială de grad înalt cu necroze și proliferare microvasculară."},{"title":"Ki-67","content":"Ridicat, aproximativ 30–40%."},{"title":"Diagnostic de lucru","content":"Glioblastom probabil."},{"title":"QC / niveluri încă neclarificate","content":"Conținut tumoral ridicat; analizele bazate pe ADN și cele epigenetice sunt tehnic interpretabile. Rămân de clarificat statusul IDH, metilarea promotorului MGMT și integrarea moleculară."}],"material_or_resource_constraints":["Raportul trebuie finalizat înaintea planificării terapeutice iminente.","Cantitatea de țesut disponibilă permite mai multe investigații, dar nu justifică testarea maximală fără valoare diagnostică.","Secvențierea bazată pe ADN și analizele de metilare răspund unor întrebări diferite.","Un raport foarte extins tehnic poate rămâne totuși incomplet clinic."],"reasoning_gate_upgrade":[{"id":"cns_question_levels","type":"multi_select","prompt":"Ce niveluri trebuie diferențiate în acest caz?","options":[{"id":"classification","label":"Clasificare histologică/moleculară"},{"id":"tmz_prediction","label":"Context predictiv pentru temozolomidă"},{"id":"molecular_characterization","label":"Caracterizare moleculară suplimentară"},{"id":"max_gene_count","label":"Cel mai mare număr posibil de gene testate"},{"id":"tmb_msi_primary","label":"TMB/MSI ca principal reper decizional"}],"correct":["classification","tmz_prediction","molecular_characterization"],"rationale":"Valoarea diagnostică rezultă din întrebarea clinică. Testarea unui număr cât mai mare de gene nu reprezintă în sine un nivel diagnostic."},{"id":"cns_marker_roles","type":"multi_select","prompt":"Care asocieri sunt corecte?","options":[{"id":"idh_classification","label":"IDH → clasificare moleculară"},{"id":"mgmt_prediction","label":"Metilarea promotorului MGMT → context terapeutic epigenetic/predictiv"},{"id":"classifier_integration","label":"Clasificator de metilare → nivel suplimentar de clasificare/integrare diagnostică"},{"id":"ngs_characterization","label":"NGS pentru gliom → caracterizare moleculară suplimentară"},{"id":"mgmt_driver","label":"MGMT → mutație driver clasică în DNA-NGS"}],"correct":["idh_classification","mgmt_prediction","classifier_integration","ngs_characterization"],"rationale":"IDH, MGMT și clasificatorul de metilare răspund unor întrebări diferite; MGMT nu este aici o mutație driver clasică."},{"id":"cns_strategy","type":"single_choice","prompt":"Care strategie diagnostică răspunde cel mai complet întrebării clinice?","options":[{"id":"integrated","label":"Clarificați statusul IDH, analizați separat metilarea promotorului MGMT și integrați adecvat clasificatorul de metilare/NGS pentru gliom."},{"id":"dna_only","label":"Efectuați doar un DNA-NGS extins și presupuneți că astfel este răspunsă întreaga întrebare clinică."},{"id":"tmb_first","label":"Prioritizați TMB/MSI deoarece tumora este de grad înalt."},{"id":"mgmt_mutation","label":"Căutați MGMT ca mutație în cadrul panelului NGS."}],"correct":["integrated"],"rationale":"Amploarea diagnosticului nu înlocuiește o întrebare specifică metodei. Metilarea promotorului MGMT trebuie abordată separat."}],"decision_task":"Planificați diagnosticul molecular și apoi formulați pentru boardul neuro-oncologic: Ce rezultate susțin diagnosticul integrat, ce rezultat este relevant pentru contextul temozolomidei și ce informație diagnostică nu este înlocuită de DNA-NGS singur?","expected_path":["Folosiți morfologia și contextul clinic ca punct de plecare.","Clarificați statusul IDH.","Planificați metilarea promotorului MGMT ca investigație epigenetică separată.","Încadrați adecvat clasificatorul de metilare în clasificarea/integrarea diagnostică.","Folosiți NGS pentru gliom ca nivel molecular suplimentar.","Ponderați rezultatele în funcție de funcția lor clinică.","Nu descrieți MGMT ca mutație driver."],"acceptable_alternatives":["Statusul IDH poate fi clarificat prin IHC/secvențiere țintită sau prin diagnostic NGS adecvat pentru gliom.","Un panel molecular mai larg poate furniza informații suplimentare relevante, atât timp cât rămâne clar ce întrebări clinice nu răspunde.","Amploarea diagnosticului poate varia în funcție de rezultatele anterioare și de fluxul de lucru instituțional."],"low_value_traps":[{"label":"Panel extins = diagnostic complet","why_bad":"Amploarea tehnică nu arată dacă întrebarea clinică specifică a fost acoperită."},{"label":"MGMT ca mutație","why_bad":"Confundă nivelurile diagnostice epigenetice și genetice."},{"label":"TMB/MSI ca obiectiv principal","why_bad":"Nu reprezintă un reper decizional principal pentru întrebarea actuală IDH/MGMT/temozolomidă."},{"label":"Doar enumerarea markerilor","why_bad":"Un raport integrat trebuie să explice ce informație este relevantă diagnostic sau predictiv."}],"twist":{"title":"Un panel mare – și totuși lipsește informația decisivă","content":"Secvențierea arată IDH1/2 de tip sălbatic, o mutație a promotorului TERT și un semnal de amplificare EGFR; rezultatul molecular se potrivește contextului de glioblastom. În board se spune: Atunci am terminat. Totuși, MGMT nu a fost analizat. Abia analiza țintită suplimentară arată un promotor MGMT metilat; clasificatorul de metilare susține clasa glioblastom, IDH de tip sălbatic, cu scor înalt al clasificatorului.","why_critical":"Un rezultat diagnostic amplu poate lăsa fără răspuns o întrebare terapeutică specifică. Nivelul epigenetic MGMT nu este înlocuit de DNA-NGS convențional."},"result_packages":[{"id":"optimal","title":"Raport integrat","class":"optimal","result":"IDH de tip sălbatic; promotor MGMT metilat; clasa de metilare susține glioblastom, IDH de tip sălbatic; rezultatele moleculare suplimentare sunt compatibile cu contextul general.","feedback":"Foarte bine. Metodele individuale sunt integrate în funcție de rolul lor diagnostic."},{"id":"incomplete","title":"Multă secvențiere, întrebare terapeutică încă deschisă","class":"incomplete","result":"DNA-NGS extins, dar fără rezultat pentru metilarea promotorului MGMT.","feedback":"Extins tehnic, incomplet clinic. Întrebarea privind temozolomida rămâne deschisă."},{"id":"wrong","title":"Focalizare greșită","class":"wrong","result":"Testare suplimentară TMB/MSI fără integrarea completă IDH/MGMT.","feedback":"Investigațiile nu răspund întrebării centrale a cazului."}],"followup_logic":[{"trigger":"MGMT lipsește","action":"Adăugați o analiză țintită a metilării MGMT.","consequence":"Interpretarea terapeutică rămâne incompletă până atunci."},{"trigger":"MGMT este interpretat ca mutație","action":"Abordați eroarea conceptuală în debriefing.","consequence":"Penalizare clară de raționament."},{"trigger":"Integrare completă","action":"Formulați raportul final neuro-oncologic/MTB.","consequence":"Parcurs Deep Dive complet."}],"debrief_points":["Morfologia, clasificarea moleculară și biomarkerii predictivi răspund unor întrebări diferite.","Metilarea promotorului MGMT reprezintă un nivel diagnostic epigenetic.","Un panel larg de secvențiere nu reprezintă automat un raport clinic complet.","Patologia moleculară de calitate prioritizează informațiile după relevanța lor pentru diagnostic și decizie."],"instructor_notes":{"model_answer":"Constelația morfologică este compatibilă cu o tumoră glială de grad înalt. Pentru diagnosticul integrat se determină statusul IDH. Metilarea promotorului MGMT trebuie evaluată separat ca marker predictiv epigenetic și nu este înlocuită de DNA-NGS convențional. Clasificatorul de metilare și NGS pentru gliom pot completa integrarea diagnostică. Esențială este ponderarea funcțională a fiecărui rezultat.","scoring_focus":["Nivelurile diagnostice sunt separate clar.","IDH încadrat corect.","MGMT încadrat corect.","Fără suprainterpretarea secvențierii extinse.","Comunicare clară MTB/neuro-oncologie."],"discussion_questions":["Când oferă un panel extins un beneficiu real?","Ce înseamnă diagnostic complet în acest caz?","Cum ar trebui diferențiate explicit în limbajul raportului nivelurile diagnostice diferite?"]},"report_additions":{"content_status":"Deep Dive curat în RO","key_turning_point":"NGS extins, dar MGMT lipsește","core_trap":"MGMT nu este o mutație driver clasică","pattern":"Morfologie → clasificare → predicție → integrare"},"is_signature_case":true},"LAB_DOC_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"LAB_DOC_001_v1_0","title":"„PCR ca de obicei”: valid analitic, dar totuși un caz de QM","domain":"LAB","target_course":"QM Basics","deep_dive_priority":"signature","target_role":"Conducerea laboratorului / QM / laborator de patologie moleculară","estimated_minutes_deep":"12–15","learning_objectives":["Evaluați separat validitatea analitică și conformitatea procesului/documentației.","Reconstruiți sistematic datele primare disponibile înainte de a repeta reflex testarea.","Eliberați o probă de pacient cu semnal slab pe baza riscului atunci când baza analitică a fost reconstruită în mod robust.","Recunoașteți că o lacună sistemică relevantă de documentare trebuie tratată, în ciuda reconstrucției reușite, ca abatere/near miss și, în acest caz, trebuie să conducă la o CAPA.","Verificați eficacitatea unei CAPA."],"opening_scene":"Dimineața începe pregătirea auditului intern în laboratorul de patologie moleculară. Este selectat ca eșantion un run qPCR KRAS. În caietul de laborator apare exact o propoziție: „PCR ca de obicei. A mers. Proba 4 slabă.” Colega își amintește run-ul și spune: „Totul a fost în regulă. Controalele au fost bune.” Rezultatul probei 4 este relevant clinic. Întrebarea nu mai este doar: A fost PCR-ul corect din punct de vedere tehnic? Ci: Putem demonstra asta în mod robust și astăzi – și ce facem dacă putem?","case_briefing":"Test de rutină qPCR pentru hotspoturi KRAS. Înregistrarea din caietul de laborator nu conține nici o referință metodologică suficientă, nici un audit trail complet. Lipsesc, printre altele, data/ora, operatorul, versiunea SOP, ID-uri univoce ale probelor, kit/lot/data expirării, aparatul și run-ID, controalele pozitiv/negativ/NTC, valorile Ct/replicatele, calea către datele brute și evaluarea profesională documentată a probei slabe. Totuși, datele brute și metadatele propriu-zise pot fi încă disponibile în aparat, LIMS și sistemele electronice.","context_cards":[{"title":"Înregistrare originală","content":"„PCR ca de obicei. A mers. Proba 4 slabă.”","teaching_point":"Plausibilitatea nu înseamnă trasabilitate."},{"title":"Test","content":"Test de rutină qPCR pentru hotspoturi KRAS.","teaching_point":"Rutina nu reduce cerințele de documentare."},{"title":"Proba pacientului","content":"Proba 4 prezintă un semnal slab.","teaching_point":"Tocmai semnalele limită/slabe necesită date primare trasabile și o evaluare documentată."},{"title":"Conflict","content":"Reconstruim sau repetăm preventiv totul?","teaching_point":"Un QM bun este bazat pe risc, nu pe maximalism reflex."}],"pre_results":[{"title":"Situația documentării","content":"Documentația originală este insuficientă, dar nu există indicii privind un eșec tehnic cunoscut al run-ului."},{"title":"Surse disponibile","content":"Exportul aparatului, LIMS și alte metadate electronice sunt încă disponibile."},{"title":"Context material/timp","content":"Materialul rămas de la pacient este limitat. O repetare ar consuma timp și material suplimentar."},{"title":"Întrebare deschisă","content":"Nu este încă clar dacă întregul traseu analitic, inclusiv proba slabă, poate fi reconstruit în mod robust."}],"material_or_resource_constraints":["Materialul pacientului nu este disponibil nelimitat.","Fiecare repetare consumă material și implică timp și resurse.","Prin urmare, o repetare inutilă nu este automat mai sigură.","Pe de altă parte, o eliberare fără reconstrucție robustă nu ar fi acceptabilă.","Măsurile de QM trebuie să abordeze cauza reală, nu doar să elimine simptomele."],"reasoning_gate_upgrade":[{"id":"labdoc_primary_problem","type":"single_choice","prompt":"Care este problema principală?","options":[{"id":"auto_invalid","label":"Run-ul este automat invalid din punct de vedere analitic."},{"id":"traceability","label":"Trasabilitatea și baza documentată a evaluării sunt insuficiente."},{"id":"weak_never_release","label":"O probă slabă nu poate fi eliberată niciodată, în principiu."},{"id":"routine_less_docs","label":"PCR-ul de rutină necesită mai puțină documentare."}],"correct":["traceability"],"rationale":"O deficiență de documentare nu implică automat o eroare analitică. Mai întâi trebuie verificat dacă validitatea analitică poate fi reconstruită pe baza datelor-sursă."},{"id":"labdoc_reconstruct","type":"multi_select","prompt":"Ce informații trebuie utilizate pentru o reconstrucție conformă pentru audit?","options":[{"id":"who_when","label":"Operator și momentul efectuării"},{"id":"sop","label":"Versiunea SOP"},{"id":"lot","label":"Lotul kitului/reactivilor și data expirării"},{"id":"sample_id","label":"Identitatea univocă a probei"},{"id":"run_id","label":"Aparat și run-ID"},{"id":"controls","label":"Controale pozitiv/negativ/NTC"},{"id":"ct_replicates","label":"Valori Ct și replicate"},{"id":"rawdata","label":"Calea către datele brute/date primare"},{"id":"sample4_review","label":"Evaluarea profesională a probei 4"},{"id":"memory_only","label":"Amintirea verbală a colegei ca singură dovadă"}],"correct":["who_when","sop","lot","sample_id","run_id","controls","ct_replicates","rawdata","sample4_review"],"rationale":"Reconstrucția trebuie să se bazeze pe surse și să fie conformă pentru audit; memoria singură nu este suficientă."},{"id":"labdoc_release_or_repeat","type":"single_choice","prompt":"Reconstrucția arată o atribuire univocă a probelor, date SOP/lot valide, controale valide, date brute complete și un semnal slab reproductibil în proba 4. Care este acum acțiunea corectă?","options":[{"id":"release_after_review","label":"Documentați transparent reconstrucția și reevaluarea profesională; eliberați proba 4; evitați o repetare inutilă."},{"id":"repeat_all","label":"Repetați întregul run indiferent de datele primare disponibile."},{"id":"weak_hold","label":"Nu eliberați proba 4, deoarece un semnal slab este în mod inerent nesigur."},{"id":"release_no_docs","label":"Eliberați pur și simplu rezultatul și lăsați documentația originală neschimbată."}],"correct":["release_after_review"],"rationale":"Validitatea analitică este trasabilă din datele primare. Repetarea nu este un scop în sine și ar consuma inutil material, timp și resurse."},{"id":"labdoc_capa","type":"single_choice","prompt":"Este cazul închis după reconstrucția reușită a rezultatului?","options":[{"id":"done_no_harm","label":"Da. Nu a existat un prejudiciu pentru pacient."},{"id":"near_miss_capa","label":"Nu. Lacuna relevantă de documentare este evaluată pe baza riscului ca abatere/near miss; problema sistemică identificată aici este abordată prin CAPA și verificarea eficacității."},{"id":"verbal_reminder","label":"Este suficientă o reamintire informală către echipă."},{"id":"rewrite_old","label":"Înregistrarea veche din caietul de laborator este ștearsă și rescrisă."}],"correct":["near_miss_capa"],"rationale":"Reconstrucția reușită previne o eroare, dar nu elimină slăbiciunea sistemică ce aproape a permis-o."}],"decision_task":"Luați două decizii separate: Rezultatul concret al pacientului poate fi eliberat după reconstrucție? Ce consecință de QM rezultă din procesul inițial insuficient?","expected_path":["Recunoașteți deficiența de documentare.","Nu respingeți automat rezultatul.","Reconstruiți sistematic datele primare și metadatele.","Confirmați validitatea run-ului pe baza controalelor.","Reevaluați profesional proba slabă folosind valorile Ct/replicatele și datele brute.","Eliberați transparent rezultatul.","Înregistrați deficiența inițială de documentare ca abatere/near miss.","Analizați cauza rădăcină.","Implementați CAPA.","Verificați eficacitatea folosind documentațiile ulterioare."],"acceptable_alternatives":["O repetare este justificabilă dacă elemente decisive precum identitatea probei, controalele, datele primare sau evaluarea profesională nu pot fi reconstruite în mod robust.","Repetarea rezultă din risc – nu din simpla existență a unei abateri."],"low_value_traps":[{"label":"Repetați întotdeauna când există o abatere","why_bad":"Poate consuma inutil material de la pacient, timp și resurse și nu rezolvă cauza procesului."},{"label":"Nu s-a întâmplat nimic, deci nu este nevoie de CAPA","why_bad":"Near miss-ul și slăbiciunea sistemică a procesului rămân."},{"label":"Adăugați ulterior doar valoarea Ct","why_bad":"Trasabilitatea rămâne incompletă."},{"label":"Doar instruire","why_bad":"O instruire fără legătură cu cauza rădăcină și fără verificarea eficacității nu reprezintă o CAPA robustă."},{"label":"Amintire verbală","why_bad":"Nu este un substitut conform pentru audit al datelor primare."}],"twist":{"title":"Proba slabă poate fi, de fapt, eliberată","content":"Reconstrucția arată că run-ul a fost tehnic valid, controalele au fost corecte, iar proba 4 prezintă în datele primare un semnal slab reproductibil. După reevaluare profesională documentată, proba poate fi eliberată; repetarea completă nu este necesară. Totuși, o verificare prin sondaj a altor înregistrări din caietul de laborator arată mai multe formulări prescurtate similare – ceea ce părea un caz izolat devine o slăbiciune sistemică de documentare.","why_critical":"Validitatea analitică și conformitatea procesului sunt întrebări separate. Rezultatul concret poate fi salvat, în timp ce near miss-ul necesită în continuare gestionarea pe bază de risc a abaterii/CAPA."},"result_packages":[{"id":"optimal","title":"Eliberare bazată pe risc + CAPA","class":"optimal","result":"Run-ul și proba 4 complet reconstruite, rezultat eliberat profesional, abatere documentată, cauză rădăcină abordată, CAPA stabilită cu verificarea eficacității.","feedback":"Foarte bine. Validitatea analitică și conformitatea procesului au fost evaluate separat și pe baza riscului."},{"id":"incomplete","title":"Reflex de siguranță: repetă tot","class":"incomplete","result":"Întregul run este repetat, deși toate datele primare relevante erau disponibile.","feedback":"Repetarea nu este un scop în sine. Consumul de material și resurse nu a fost luat în calcul; cauza procesului rămâne nerezolvată."},{"id":"release_no_capa","title":"Rezultat corect, QM greșit","class":"incomplete","result":"Proba este eliberată corect, dar problema documentării este apoi considerată închisă.","feedback":"Rezultatul concret este salvat, dar cauza sistemică nu."},{"id":"wrong","title":"Eliberare bazată doar pe amintire","class":"wrong","result":"Eliberare exclusiv pe baza rutinei și memoriei.","feedback":"Nu este conform pentru audit și nu este robust."}],"followup_logic":[{"trigger":"Datele primare nu pot fi reconstruite complet","action":"Mențineți pe hold și efectuați repetare țintită și/sau clarificări suplimentare.","consequence":"Fără eliberare în lipsa unei baze robuste."},{"trigger":"Reconstrucție completă plus controale valide","action":"Efectuați și documentați reevaluarea profesională.","consequence":"Eliberarea poate fi posibilă."},{"trigger":"Lacună sistemică de documentare","action":"Efectuați analiza cauzei rădăcină și CAPA.","consequence":"Adaptați template-ul/procesul/instruirea în funcție de cauza identificată."},{"trigger":"CAPA implementată","action":"Revizuiți prin sondaj documentațiile qPCR ulterioare.","consequence":"Verificarea eficacității, nu doar închiderea formală a măsurii."}],"debrief_points":["Validitatea analitică și conformitatea procesului sunt întrebări diferite.","O abatere nu face automat un rezultat invalid.","O repetare trebuie justificată pe baza riscului.","Materialul limitat, timpul și resursele fac parte din evaluarea riscului.","Un near miss este deosebit de instructiv atunci când slăbiciunea este identificată înainte de apariția unui prejudiciu.","CAPA se încheie cu verificarea eficacității, nu cu „personal instruit”."],"instructor_notes":{"model_answer":"Mai întâi, trasabilitatea este reconstruită din LIMS, exportul aparatului, SOP, lot, controale și date brute. Dacă identitatea probei, validitatea run-ului și pozitivitatea slabă a probei 4 pot fi demonstrate robust, rezultatul poate fi eliberat după reevaluare documentată. O repetare generală nu este necesară. Deficiența inițială de documentare este totuși tratată ca abatere relevantă cu caracter de near miss. Dacă se identifică o problemă sistemică, urmează analiza cauzei rădăcină, o CAPA adecvată și verificarea eficacității.","scoring_focus":["Reconstrucție înainte de repetare.","Date primare, nu amintiri.","Eliberarea corectă a probei slabe.","Abaterea/near miss-ul nu este ignorat.","CAPA legată de cauza rădăcină.","Verificarea eficacității."],"discussion_questions":["Când este într-adevăr necesară repetarea?","Poate fi un rezultat valid chiar dacă procesul a fost defectuos?","Unde este limita dintre correction și CAPA?","De ce o siguranță mai mare nu înseamnă automat mai multe repetări?"]},"report_additions":{"content_status":"Deep Dive curat în RO","key_turning_point":"Probă slabă eliberabilă după reconstrucție","core_message":"Validitate analitică ≠ conformitatea procesului","pattern":"Reconstrucție → evaluarea riscului → eliberare → CAPA → verificarea eficacității"},"is_signature_case":true},"RES_OMICS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_OMICS_001_v1_0","title":"200 DEGs, un biomarker? De la semnalul RNA-seq la o ipoteză robustă de rezistență","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Cercetare translațională / patologie moleculară / bioinformatică","estimated_minutes_deep":"18–22","learning_objectives":["Transformați listele de DEG-uri în programe biologice, nu în povești despre o singură genă.","Operaționalizați o observație omică drept ipoteză testabilă și PICO.","Distingeți discovery, validarea tehnică, validarea morfologică și replicarea externă.","Nu suprainterpretați rezultatele exploratorii ca biomarker deja stabilit.","Prioritizați robustețea unei semnături față de atractivitatea unei singure gene."],"opening_scene":"Luni dimineața, la ședința de cercetare translațională. O doctorandă și-a finalizat prima analiză RNA-seq: 30 de tumori tratate cu ICI, 15 responderi și 15 non-responderi. Pe slide scrie: „200 DEGs semnificative.” Dedesubt, un tabel ordonat. Ea întreabă: „Ce genă aleg acum ca biomarker?” Cel mai mic p-value arată spectaculos. Dar exact aici începe munca științifică propriu-zisă.","case_briefing":"RNA-seq pe 30 de tumori tratate cu ICI: 15 responderi și 15 non-responderi. La non-responderi sunt crescute, printre altele, TGFB1, COL1A1, CXCL12, ACTA2, FN1 și alte gene ECM; HLA-A, B2M, TAP1, CXCL9 și GZMB sunt scăzute. Analiza de pathway arată TGFβ/ECM crescut și prezentare antigenică/activare a celulelor T scăzută. Clinic, tumorile bogate în stromă sunt asociate cu răspuns mai slab la ICI.","context_cards":[{"title":"Cohortă de discovery","content":"30 de tumori tratate cu ICI, 15 responderi versus 15 non-responderi.","teaching_point":"Cohortele mici de discovery sunt adecvate pentru generarea de ipoteze, nu automat pentru un claim de biomarker."},{"title":"Semnal RNA-seq","content":"200 de gene diferențial exprimate.","teaching_point":"O listă de gene nu este încă o explicație biologică."},{"title":"Tipar biologic","content":"TGFβ/ECM crescut, prezentare antigenică/activare a celulelor T scăzută.","teaching_point":"Programele coordonate pot fi mai informative decât o singură genă."},{"title":"Obiectiv translațional","content":"Dezvoltarea unui mecanism și a unei semnături testabile clinic.","teaching_point":"Trecerea de la omics la translație necesită mai multe niveluri de validare."}],"pre_results":[{"title":"Non-responderi – crescute","content":"TGFB1, COL1A1, CXCL12, ACTA2, FN1 și alte gene ECM."},{"title":"Non-responderi – scăzute","content":"HLA-A, B2M, TAP1, CXCL9 și GZMB."},{"title":"Îmbogățire de pathway","content":"TGFβ/ECM crescut; prezentare antigenică/activare a celulelor T scăzută."},{"title":"Încă nedecis","content":"Cea mai puternică genă individuală, o semnătură și un program biologic nu sunt același lucru. Interpretarea trebuie prioritizată activ."}],"material_or_resource_constraints":["Cohortă de discovery: n = 30.","Testarea multiplă/FDR trebuie luată în calcul.","Trebuie înregistrați confounderi clinici precum tratamentul, entitatea tumorală, ECOG și conținutul tumoral.","Bugetul este suficient pentru validare tehnică și morfologică țintită, nu pentru multi-omics nelimitat.","Este necesară validare independentă înainte de a formula un claim de biomarker."],"reasoning_gate_upgrade":[{"id":"omics_from_degs","type":"single_choice","prompt":"Cum transformăm 200 DEGs într-o întrebare de cercetare robustă?","options":[{"id":"lowest_p","label":"Selectați gena cu cel mai mic p-value."},{"id":"all_genes","label":"Raportați toate cele 200 de gene ca fiind la fel de importante."},{"id":"programs","label":"Identificați programe biologice coordonate și pathways comune."},{"id":"expected_only","label":"Păstrați doar genele care se potrivesc poveștii așteptate."}],"correct":["programs"],"rationale":"Tiparul stromal/imun comun oferă o ipoteză mai robustă decât o genă individuală izolată."},{"id":"omics_hypothesis","type":"single_choice","prompt":"Care ipoteză se potrivește cel mai bine datelor disponibile?","options":[{"id":"stroma_immune","label":"Non-răspunsul primar la ICI este asociat cu un microambient tumoral dominat de stromă/TGFβ și simultan sărac în antigene."},{"id":"tgfb1_marker","label":"TGFB1 este noul biomarker predictiv."},{"id":"all_degs_explain","label":"Cele 200 DEGs explică deja complet rezistența la ICI."},{"id":"one_resistance_gene","label":"Toți non-responderii au aceeași genă de rezistență."}],"correct":["stroma_immune"],"rationale":"Ipoteza integrează mai multe programe de expresie coordonate și rămâne testabilă fără a suprainterpreta un hit explorator individual."},{"id":"omics_pico","type":"multi_select","prompt":"Ce elemente fac parte din operaționalizarea riguroasă a ipotezei?","options":[{"id":"population","label":"Populație: tumori tratate cu ICI"},{"id":"exposure","label":"Expunere/semnătură: semnătură CAF/TGFβ crescută"},{"id":"comparison","label":"Comparație: semnătură scăzută"},{"id":"outcome","label":"Outcome: răspuns/PFS"},{"id":"score_cutoff","label":"Definiți strategia de scor/cutoff înainte de validare"},{"id":"confounders","label":"Definiți confounderii relevanți și planul de analiză"},{"id":"posthoc_cutoff","label":"Stabiliți cutoff-ul abia după cel mai favorabil rezultat de validare"}],"correct":["population","exposure","comparison","outcome","score_cutoff","confounders"],"rationale":"Ipoteza, PICO, scorul/cutoff-ul și planul de analiză trebuie operaționalizate înainte de validare."},{"id":"omics_validation","type":"multi_select","prompt":"Ce pași de validare sunt robuști pentru dezvoltarea translațională?","options":[{"id":"targeted","label":"RNA țintit/qPCR/NanoString"},{"id":"external","label":"Cohortă ICI independentă"},{"id":"morphology","label":"αSMA/FAP/CD8/HLA-I/B2M ca punte morfologică"},{"id":"fdr","label":"Raportați transparent FDR și testarea multiplă"},{"id":"heatmap_only","label":"Desenați din nou heatmap-ul"},{"id":"single_wb","label":"Confirmați doar cea mai puternică genă individuală prin Western blot"}],"correct":["targeted","external","morphology","fdr"],"rationale":"Validarea tehnică, morfologică și independentă se completează reciproc; simpla vizualizare sau un singur test de confirmare nu sunt suficiente pentru o ipoteză bazată pe semnătură."}],"decision_task":"Dezvoltați din analiza exploratorie RNA-seq o strategie translațională robustă: ipoteză biologică, PICO, concept de semnătură/analiză, validare tehnică, punte morfologică, validare externă și limita unui claim de biomarker acceptabil.","expected_path":["Nu tratați lista de DEGs ca produs final.","Prioritizați nivelul de pathway/rețea.","Formulați un tipar dominat de stromă/TGFβ și sărac în antigene.","Definiți ipoteza și PICO.","Operaționalizați semnătura.","Luați în calcul FDR și confounderii.","Efectuați validare tehnică țintită.","Conectați morfologic rezultatele cu markeri TME.","Folosiți o cohortă independentă.","Abia apoi discutați potențialul de biomarker."],"acceptable_alternatives":["Încheiați studiul explicit ca exploratoriu, fără claim de biomarker.","Dezvoltați o semnătură mai mică și focalizată în locul unui scor complex.","Folosiți expresie țintită/NanoString în locul unui nou RNA-seq pentru validarea tehnică.","Adăugați validare funcțională dacă întrebarea mecanistică este centrală."],"low_value_traps":[{"label":"Cel mai mic p-value = biomarker","why_bad":"Genele individuale pot fi instabile și pot pierde contextul biologic."},{"label":"Heatmap = validare","why_bad":"Vizualizarea nu demonstrează reproductibilitate independentă."},{"label":"200 DEGs ca rezultat","why_bad":"Cantitatea de date nu înlocuiește o ipoteză."},{"label":"Optimizarea cutoff-ului post hoc","why_bad":"Risc de overfitting/HARKing."},{"label":"Eliminarea rezultatelor care nu se potrivesc","why_bad":"Raportare selectivă."}],"twist":{"title":"„Cea mai bună genă” dispare – biologia rămâne","content":"Într-o cohortă independentă de validare, gena individuală cu cel mai mic p-value din discovery nu se reproduce convingător. În schimb, semnătura stromală/imună definită anterior continuă să arate același tipar coordonat: componentă stromală/TGFβ crescută și componentă de prezentare antigenică/celule T scăzută. Validarea morfologică susține, de asemenea, interpretarea la nivel de program.","why_critical":"Cel mai atractiv hit individual din discovery nu este neapărat cel mai robust semnal biologic. Cazul separă gena individuală, semnătura, mecanismul și biomarkerul validat."},"result_packages":[{"id":"optimal","title":"Ipoteza de semnătură validată","class":"optimal","result":"Ipoteza bazată pe pathways, semnătura predefinită, validarea tehnică, puntea morfologică și cohorta independentă arată un tipar consistent.","feedback":"Dezvoltare translațională foarte bună. Potențialul de biomarker poate fi discutat acum cu prudență."},{"id":"incomplete","title":"Colapsul genei individuale","class":"incomplete","result":"Cea mai puternică genă individuală din discovery nu se reproduce, dar semnătura generală rămâne consistentă.","feedback":"Nu este un eșec al proiectului dacă ipoteza biologică este susținută independent."},{"id":"heatmap_story","title":"Heatmap frumos, fără validare","class":"incomplete","result":"Cluster exploratoriu fără replicare independentă.","feedback":"Interesant, dar nu un biomarker robust."},{"id":"wrong","title":"Overclaim","class":"wrong","result":"Semnătura din discovery este descrisă direct drept biomarker predictiv.","feedback":"Interpretarea depășește forța probatorie a datelor."}],"followup_logic":[{"trigger":"Este prioritizată doar o singură genă","action":"Readuceți analiza de pathways/rețele în raționament.","consequence":"Reasoning cap pentru interpretare monomarker."},{"trigger":"Fără validare independentă","action":"Etichetați rezultatul ca exploratoriu.","consequence":"Fără claim de biomarker."},{"trigger":"Semnătura se replică","action":"Evaluați translația morfologică și clinică.","consequence":"Parcurs optim Deep Dive."}],"debrief_points":["O listă de DEGs nu este încă un model biologic.","Informațiile de pathway și semnătură pot fi mai robuste decât o singură genă din discovery.","Validarea tehnică, morfologică și externă răspund unor întrebări diferite.","Discovery și validation trebuie menținute separate.","Lipsa replicării unui hit individual poate îmbunătăți o ipoteză în loc să distrugă proiectul.","Un biomarker este rezultatul unui lanț de validare, nu al unui heatmap frumos."],"instructor_notes":{"model_answer":"Datele sunt interpretate mai întâi la nivel de pathways/rețele. Tiparul coordonat TGFβ/ECM crescut și prezentare antigenică scăzută este formulat ca ipoteză exploratorie de rezistență. Apoi sunt operaționalizate populația, semnătura, comparația și outcome-ul. Semnătura este validată tehnic, morfologic și într-o cohortă independentă. Genele individuale și cutoff-urile nu sunt suprainterpretate post hoc ca biomarkeri deja stabiliți.","scoring_focus":["Pathway înaintea genei individuale.","Ipoteză/PICO clare.","FDR/confounderi luați în calcul.","Discovery versus validation separate.","Punte morfologică.","Claim de biomarker limitat corespunzător."],"discussion_questions":["Când este o semnătură superioară unui marker individual?","Ce înseamnă cu adevărat validare independentă?","Cum poate fi un rezultat negativ de validare valoros științific?","Când poate o asociere deveni proiect de biomarker?"]},"report_additions":{"content_status":"Deep Dive curat în RO","key_turning_point":"Cel mai bun hit individual nu se replică","core_message":"DEG → pathway → ipoteză → semnătură → validare","pattern":"Nu confundați discovery cu demonstrarea unui biomarker"},"is_signature_case":true},"RES_ETH_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_ETH_001_v1_0","title":"120 de blocuri de arhivă și fără consimțământ clar: poate începe proiectul?","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Conducere de proiect translațional / patologie / QM în cercetare","estimated_minutes_deep":"18–22","learning_objectives":["Înțelegeți governance ca o condiție prealabilă a activității științifice, nu ca o formalitate ulterioară.","Planificați separat etica/consimțământul, protecția materialului, protecția datelor și gestionarea descoperirilor incidentale.","Recunoașteți de ce materialul rezidual și anonimizarea nu reprezintă aprobări generale.","Planificați decizia de cercetare astfel încât eventualele situații ulterioare de suspiciune germinală și data sharing să fie acoperite dinainte."],"opening_scene":"Un grup de cercetare prezintă un proiect nou: 120 de blocuri tumorale FFPE arhivate urmează să fie analizate cu un panel DNA/RNA extins pentru noi markeri de rezistență. Assay-ul, bioinformatica și bugetul sunt pregătite. Conducerea proiectului spune: „Este doar material rezidual. Putem începe săptămâna viitoare.” Totuși, blocurile provin din ani diferiți, situația consimțământului este neuniformă, iar la unele blocuri mici rezerva diagnostică rămasă este neclară. În plus, panelul tumor-only planificat poate genera indicii privind variante potențial relevante pentru linia germinală. Prin urmare, prima decizie trebuie luată înainte de a tăia orice probă.","case_briefing":"Obiectivul proiectului: identificarea unor noi markeri moleculari ai rezistenței terapeutice într-o cohortă tumorală retrospectivă. Sunt planificate 120 de blocuri FFPE de rutină, un panel DNA/RNA extins, corelarea cu date clinice și follow-up, publicare și, dacă este cazul, validare externă/data sharing. Situația consimțământului/governance este neuniformă, rezerva de țesut este limitată în unele cazuri, iar un proces definit pentru descoperiri incidentale/suspiciune germinală nu există încă.","context_cards":[{"title":"Material","content":"FFPE de rutină, uneori blocuri mici; rezerva diagnostică nu este asigurată în toate cazurile.","teaching_point":"Cercetarea nu trebuie să pună în pericol îngrijirea viitoare a pacientului."},{"title":"Consimțământ","content":"Ani diferiți de arhivare și situație neuniformă de consent/governance.","teaching_point":"Arhivat nu înseamnă automat liber disponibil."},{"title":"Date","content":"Datele clinice și follow-up-ul urmează să fie corelate.","teaching_point":"Protecția datelor și accesul fac parte din designul studiului."},{"title":"Genetică","content":"Analiza tumor-only poate genera suspiciunea unui rezultat germinal.","teaching_point":"Căile de comunicare trebuie definite înainte de analiză."},{"title":"Data sharing","content":"Sunt planificate validarea externă și publicarea.","teaching_point":"Utilizarea ulterioară a datelor trebuie să fie acoperită de cadrul de governance."}],"pre_results":[{"title":"Cohortă","content":"120 de cazuri potențiale din ani diferiți."},{"title":"Governance","content":"Nu există o situație uniformă a consimțământului; eliberarea finală a materialului este încă în așteptare."},{"title":"Plan de date","content":"Datele clinice urmează să fie completate retrospectiv; validarea externă este discutată ca opțiune ulterioară."},{"title":"Descoperiri incidentale previzibile","content":"Panelul tumor-only poate identifica variante potențial relevante pentru linia germinală; trebuie stabilit un proces reglementat înainte de începerea proiectului."}],"material_or_resource_constraints":["Rezerva diagnostică rămasă are prioritate față de consumul pentru cercetare.","Nu fiecare caz trebuie neapărat inclus în cohorta finală.","Follow-up-ul și posibilitatea unei comunicări reglementate pot intra în conflict cu anonimizarea completă.","Volumul datelor și accesul trebuie limitate la ceea ce este necesar.","Deciziile de governance trebuie luate înainte ca materialul și datele să fie procesate ireversibil."],"reasoning_gate_upgrade":[{"id":"eth_start","type":"single_choice","prompt":"Poate începe proiectul imediat?","options":[{"id":"leftover_yes","label":"Da, pentru că este material rezidual."},{"id":"anonymized_yes","label":"Da, dacă sunt eliminate toate numerele de caz."},{"id":"governance_first","label":"Nu; mai întâi trebuie clarificate situația etică/a consimțământului, protecția datelor, eliberarea materialului și procesul pentru descoperiri incidentale."},{"id":"dna_extract_first","label":"Da, atât timp cât inițial se face doar extracția ADN."}],"correct":["governance_first"],"rationale":"Governance și protecția materialului trebuie clarificate înainte de utilizarea ireversibilă a probelor și datelor."},{"id":"eth_prerequisites","type":"multi_select","prompt":"Ce condiții prealabile trebuie clarificate înainte de începerea analizelor?","options":[{"id":"ethics","label":"Aviz etic/amendament"},{"id":"consent","label":"Verificarea consimțământului/broad consent/opt-out sau a bazei de governance aplicabile"},{"id":"material_release","label":"Eliberarea materialului de către patologie"},{"id":"reserve","label":"Protejarea rezervei diagnostice"},{"id":"pseudonym","label":"Concept de pseudonimizare/gestionare a cheii"},{"id":"roles","label":"Concept de roluri și acces"},{"id":"side_findings","label":"Gestionare definită a descoperirilor incidentale/suspiciunii germinale"},{"id":"sharing","label":"Concept de data sharing"},{"id":"leftover_note","label":"O mențiune „material rezidual” ca singură autorizare"}],"correct":["ethics","consent","material_release","reserve","pseudonym","roles","side_findings","sharing"],"rationale":"Governance include etica, consimțământul/baza juridică, protecția materialului, protecția datelor, rolurile, descoperirile incidentale și utilizarea ulterioară a datelor."},{"id":"eth_anonymization","type":"single_choice","prompt":"Anonimizarea completă rezolvă automat întrebările de governance?","options":[{"id":"no","label":"Nu. Nu înlocuiește evaluarea materialului/etică și poate îngreuna follow-up-ul sau comunicarea reglementată."},{"id":"yes","label":"Da. După anonimizare, consimțământul, eliberarea materialului și descoperirile incidentale nu mai sunt relevante."},{"id":"always_best","label":"Da. Anonimizarea completă este standardul preferat pentru orice studiu translațional."}],"correct":["no"],"rationale":"Anonimizarea este un concept de protecție a datelor, nu o radieră universală de governance."},{"id":"eth_material_guard","type":"single_choice","prompt":"Evaluarea materialului arată o rezervă diagnostică limitată în mai multe biopsii mici. Ce este corect?","options":[{"id":"exclude_reduce","label":"Excludeți cazurile sau reduceți amploarea cercetării și protejați rezerva diagnostică."},{"id":"use_all","label":"Folosiți toate cazurile pentru a maximiza dimensiunea științifică a cohortei."},{"id":"split_half","label":"Rezervați întotdeauna jumătate din material pentru cercetare, indiferent de rezerva diagnostică rămasă."}],"correct":["exclude_reduce"],"rationale":"O cohortă mai mică și conformă cu governance este mai bună decât o cohortă mai mare obținută în detrimentul diagnosticului viitor."}],"decision_task":"Elaborați un concept de governance și eliberare care să acopere întregul ciclu de viață al proiectului: începutul proiectului, utilizarea materialului, datele clinice, pseudonimizarea/accesul, descoperirile genetice incidentale, publicarea și data sharing.","expected_path":["Puneți inițial proiectul pe hold.","Definiți clar întrebarea de cercetare/PICO.","Verificați situația etică/a consimțământului.","Efectuați eliberarea materialului de către patologie.","Protejați rezerva diagnostică.","Definiți pseudonimizarea și rolurile/accesul.","Definiți un set minim de date.","Stabiliți în avans procesul pentru descoperiri incidentale/suspiciune germinală.","Aliniați data sharing cu governance.","Abia apoi eliberați materialul și începeți analiza."],"acceptable_alternatives":["Limitați cohorta la cazuri cu situație clară de governance și material.","Reduceți amploarea cercetării.","Realizați proiectul ca studiu pilot mai mic.","Limitați data sharing dacă cadrul inițial de governance nu îl permite."],"low_value_traps":[{"label":"Material rezidual = liber disponibil","why_bad":"Materialul derivat de la pacienți rămâne relevant pentru governance."},{"label":"Anonimizarea rezolvă totul","why_bad":"Întrebările privind materialul, etica și comunicarea rămân."},{"label":"Dimensiunea cohortei înaintea protecției materialului","why_bad":"Cercetarea nu trebuie să consume rezerva diagnostică."},{"label":"Clarificați descoperirile incidentale mai târziu","why_bad":"Procesul trebuie să existe înainte de apariția unui rezultat previzibil."},{"label":"Verificați data sharing doar la publicare","why_bad":"Prea târziu dacă datele au fost deja colectate într-o structură nepotrivită pentru această utilizare."}],"twist":{"title":"Descoperirea incidentală previzibilă devine realitate","content":"Proiectul începe după finalizarea evaluării de governance. În timpul analizei tumor-only, într-un caz apare o constelație BRCA1 potențial patogenă, cu posibilă relevanță germinală. Echipa întreabă imediat: „Trebuie să sunăm acum pacienta?” Răspunsul corect nu este nici să ignorăm rezultatul, nici să îl comunicăm imediat. Se aplică procesul pentru descoperiri incidentale/suspiciune germinală definit înainte de începerea proiectului.","why_critical":"Valoarea unui governance bun nu se vede în cererea către comisia de etică, ci în momentul în care apare efectiv o situație dificilă previzibilă."},"result_packages":[{"id":"optimal","title":"Governance first","class":"optimal","result":"Etica, consent/governance, rezerva de material, protecția datelor, rolurile de acces, procesul pentru descoperiri incidentale și data sharing sunt clarificate înainte de analiză. Blocurile problematice sunt protejate sau excluse.","feedback":"Arhitectură de proiect foarte bună."},{"id":"wrong","title":"Start now","class":"wrong","result":"Materialul este procesat înainte de clarificarea situației consimțământului și a rezervei diagnostice.","feedback":"Eroare critică de governance."},{"id":"incomplete","title":"Anonymize everything","class":"incomplete","result":"Legătura cu cazul este eliminată complet foarte devreme; follow-up-ul și comunicarea reglementată devin problematice, în timp ce alte întrebări de governance rămân deschise.","feedback":"Un pas tehnic de protecție a datelor nu înlocuiește un concept general."},{"id":"material_wrong","title":"Science before material","class":"wrong","result":"Blocuri mici, relevante diagnostic, sunt consumate pentru a maximiza dimensiunea cohortei.","feedback":"Interesul de cercetare a fost pus înaintea protecției materialului."}],"followup_logic":[{"trigger":"Rezervă diagnostică limitată","action":"Excludeți cazul sau reduceți consumul pentru cercetare.","consequence":"Cohortă mai mică, dar responsabilă."},{"trigger":"Posibilă suspiciune germinală","action":"Aplicați procesul predefinit pentru descoperiri incidentale/genetică clinică.","consequence":"Fără comunicare ad hoc."},{"trigger":"Un partener extern solicită date brute","action":"Verificați cadrul consent/governance/data sharing.","consequence":"Transmiteți doar datele permise sau limitați sharing-ul."},{"trigger":"Governance neclarificat","action":"Proiectul rămâne pe hold.","consequence":"Fără eliberarea materialului."}],"debrief_points":["Governance face parte din designul studiului.","Materialul rezidual nu este automat material de cercetare liber disponibil.","Rezerva diagnostică are prioritate.","Pseudonimizarea, anonimizarea și governance nu sunt același lucru.","Descoperirile genetice incidentale previzibile necesită un proces definit în prealabil.","Un design bun de cercetare include deja gestionarea ulterioară a publicării și data sharing.","O cohortă mai mică și bine definită poate fi mai solidă științific și etic decât dimensiunea maximă posibilă."],"instructor_notes":{"model_answer":"Proiectul poate începe doar după clarificarea situației etice/a consimțământului, protecției datelor, eliberării materialului și gestionării descoperirilor incidentale. Rezerva diagnostică este protejată pentru fiecare caz. Datele clinice sunt pseudonimizate și procesate cu acces bazat pe roluri. O posibilă suspiciune germinală rezultată din date tumor-only nu este comunicată ad hoc, ci gestionată printr-un proces definit în prealabil. Data sharing se face numai în cadrul de governance stabilit.","scoring_focus":["Governance înainte de începerea proiectului.","Protecția materialului.","Pseudonimizare/acces.","Proces pentru descoperiri incidentale.","Fără comunicare ad hoc.","Data sharing anticipat din etapa de proiectare."],"discussion_questions":["Când este o cohortă mai mică studiul mai bun?","De ce anonimizarea completă nu este întotdeauna cea mai elegantă soluție?","Ce consecințe are secvențierea tumor-only încă din etapa de planificare a studiului?","Când trebuie planificat conceptual data sharing?"]},"report_additions":{"content_status":"Deep Dive curat în RO","key_turning_point":"Posibilă suspiciune germinală BRCA1","core_message":"Governance trebuie să preceadă începerea proiectului","pattern":"Start → material → analiză → descoperire incidentală → data sharing"},"is_signature_case":true}},"el":{"MTB_CNS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"MTB_CNS_001_v1_0","title":"Γλοιοβλάστωμα πριν από τη θεραπευτική απόφαση: σωστή ενσωμάτωση IDH, MGMT και μεθυλίωσης","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Μοριακή παθολογία / νευροπαθολογία / MTB","estimated_minutes_deep":"15–18","learning_objectives":["Αναγνώριση της διαγνωστικής ταξινόμησης, του μοριακού χαρακτηρισμού και των προβλεπτικών βιοδεικτών ως διαφορετικών επιπέδων.","Σωστή λειτουργική αντιστοίχιση των IDH, μεθυλίωσης του υποκινητή MGMT και ταξινομητή μεθυλίωσης.","Αναγνώριση ότι ένα ευρύ DNA-NGS δεν απαντά αυτόματα σε κάθε κλινικό ερώτημα.","Ιεράρχηση μιας ολοκληρωμένης έκθεσης με βάση την κλινική σημασία και όχι το τεχνικό εύρος."],"opening_scene":"Παρασκευή μεσημέρι στη νευροπαθολογία. Η έκθεση για έναν ασθενή 68 ετών μετά από υφολική εκτομή υψηλόβαθμου πρωτοπαθούς όγκου του εγκεφάλου πρέπει να οριστικοποιηθεί πριν από τον επικείμενο νευρο-ογκολογικό θεραπευτικό σχεδιασμό. Η ιστολογία είναι έντονα συμβατή με γλοιοβλάστωμα. Ωστόσο, η νευρο-ογκολογία χρειάζεται επιπλέον ολοκληρωμένη ταξινόμηση και ρητά αξιολόγηση του πλαισίου της τεμοζολομίδης. Υπάρχει επαρκές υλικό. Το καθοριστικό ερώτημα λοιπόν δεν είναι: Πόσα μπορούμε να εξετάσουμε; Αλλά: Ποια εξέταση απαντά σε ποιο κλινικό ερώτημα;","case_briefing":"Ασθενής 68 ετών με επιληπτική κρίση και προοδευτική αφασία. Η MRI δείχνει δακτυλιοειδώς ενισχυόμενη μάζα. Μετά από υφολική εκτομή, η ιστολογία δείχνει υψηλόβαθμο γλοιακό όγκο με νέκρωση και μικροαγγειακό πολλαπλασιασμό· Ki-67 περίπου 30–40%. Η διάγνωση εργασίας είναι γλοιοβλάστωμα. Για τη μοριακή ολοκλήρωση και τον θεραπευτικό σχεδιασμό πρέπει να διευκρινιστούν κυρίως η κατάσταση IDH, η μεθυλίωση του υποκινητή MGMT και η κλάση μεθυλίωσης.","context_cards":[{"title":"Κλινικό πλαίσιο","content":"Επιληπτική κρίση, προοδευτική αφασία, υφολική εκτομή· συζητείται χημειοακτινοθεραπεία.","teaching_point":"Η μοριακή έκθεση έχει διαφορετικές διαγνωστικές και θεραπευτικές λειτουργίες."},{"title":"Ιστολογία","content":"Υψηλόβαθμος γλοιακός όγκος με νέκρωση και μικροαγγειακό πολλαπλασιασμό· Ki-67 περίπου 30–40%.","teaching_point":"Η μορφολογία είναι ιδιαίτερα κατευθυντική, αλλά δεν υποκαθιστά τη μοριακή ολοκλήρωση."},{"title":"Υλικό","content":"Παρασκεύασμα εκτομής FFPE, block T3, περίπου 80% όγκος· μπορούν να επισημανθούν βιώσιμες περιοχές όγκου· μπορούν να προγραμματιστούν 14 τομές.","teaching_point":"Δεν υπάρχει οξεία έλλειψη υλικού, αλλά εξακολουθεί να απαιτείται ορθολογική διαγνωστική στρατηγική."},{"title":"Κλινικό αίτημα","content":"Η ταξινόμηση, η πρόγνωση και το πλαίσιο τεμοζολομίδης πρέπει να διευκρινιστούν πριν από τον θεραπευτικό σχεδιασμό.","teaching_point":"Δεν απαντά κάθε δείκτης στο ίδιο ερώτημα."}],"pre_results":[{"title":"H&E","content":"Υψηλόβαθμος γλοιακός όγκος με νέκρωση και μικροαγγειακό πολλαπλασιασμό."},{"title":"Ki-67","content":"Υψηλό, περίπου 30–40%."},{"title":"Διάγνωση εργασίας","content":"Πιθανό γλοιοβλάστωμα."},{"title":"QC / εκκρεμή επίπεδα","content":"Υψηλή περιεκτικότητα σε όγκο· οι αναλύσεις με βάση το DNA και οι επιγενετικές αναλύσεις είναι τεχνικά αξιολογήσιμες. Εκκρεμούν η κατάσταση IDH, η μεθυλίωση του υποκινητή MGMT και η μοριακή ολοκλήρωση."}],"material_or_resource_constraints":["Η έκθεση πρέπει να οριστικοποιηθεί πριν από τον επικείμενο θεραπευτικό σχεδιασμό.","Η διαθέσιμη ποσότητα ιστού επιτρέπει πολλαπλές εξετάσεις, αλλά δεν δικαιολογεί διαγνωστικά άσκοπη μέγιστη διερεύνηση.","Η αλληλούχηση με βάση το DNA και οι αναλύσεις μεθυλίωσης απαντούν σε διαφορετικά ερωτήματα.","Μια τεχνικά εκτεταμένη έκθεση μπορεί παρ’ όλα αυτά να είναι κλινικά ελλιπής."],"reasoning_gate_upgrade":[{"id":"cns_question_levels","type":"multi_select","prompt":"Ποια επίπεδα πρέπει να διαχωρίσετε σε αυτή την περίπτωση;","options":[{"id":"classification","label":"Ιστολογική/μοριακή ταξινόμηση"},{"id":"tmz_prediction","label":"Προβλεπτικό πλαίσιο τεμοζολομίδης"},{"id":"molecular_characterization","label":"Πρόσθετος μοριακός χαρακτηρισμός"},{"id":"max_gene_count","label":"Ο μεγαλύτερος δυνατός αριθμός εξεταζόμενων γονιδίων"},{"id":"tmb_msi_primary","label":"TMB/MSI ως κύριος άξονας απόφασης"}],"correct":["classification","tmz_prediction","molecular_characterization"],"rationale":"Η διαγνωστική αξία καθορίζεται από το κλινικό ερώτημα. Η εξέταση όσο το δυνατόν περισσότερων γονιδίων δεν αποτελεί από μόνη της διαγνωστικό επίπεδο."},{"id":"cns_marker_roles","type":"multi_select","prompt":"Ποιες αντιστοιχίσεις είναι σωστές;","options":[{"id":"idh_classification","label":"IDH → μοριακή ταξινόμηση"},{"id":"mgmt_prediction","label":"Μεθυλίωση υποκινητή MGMT → επιγενετικό/προβλεπτικό θεραπευτικό πλαίσιο"},{"id":"classifier_integration","label":"Ταξινομητής μεθυλίωσης → πρόσθετο επίπεδο διαγνωστικής ταξινόμησης/ολοκλήρωσης"},{"id":"ngs_characterization","label":"NGS γλοιώματος → πρόσθετος μοριακός χαρακτηρισμός"},{"id":"mgmt_driver","label":"MGMT → κλασική οδηγός μετάλλαξη στο DNA-NGS"}],"correct":["idh_classification","mgmt_prediction","classifier_integration","ngs_characterization"],"rationale":"Τα IDH, MGMT και ο ταξινομητής μεθυλίωσης απαντούν σε διαφορετικά ερωτήματα· το MGMT δεν αποτελεί εδώ κλασική οδηγό μετάλλαξη."},{"id":"cns_strategy","type":"single_choice","prompt":"Ποια διαγνωστική στρατηγική απαντά πληρέστερα στο κλινικό ερώτημα;","options":[{"id":"integrated","label":"Διευκρινίστε την κατάσταση IDH, εξετάστε χωριστά τη μεθυλίωση του υποκινητή MGMT και ενσωματώστε κατάλληλα τον ταξινομητή μεθυλίωσης/NGS γλοιώματος."},{"id":"dna_only","label":"Πραγματοποιήστε μόνο ευρύ DNA-NGS και θεωρήστε ότι έτσι απαντάται ολόκληρο το κλινικό ερώτημα."},{"id":"tmb_first","label":"Δώστε προτεραιότητα σε TMB/MSI επειδή ο όγκος είναι υψηλού βαθμού."},{"id":"mgmt_mutation","label":"Αναζητήστε το MGMT ως μετάλλαξη μέσα στο panel NGS."}],"correct":["integrated"],"rationale":"Το διαγνωστικό εύρος δεν υποκαθιστά ένα ερώτημα ειδικό για τη μέθοδο. Η μεθυλίωση του υποκινητή MGMT πρέπει να αξιολογηθεί ξεχωριστά."}],"decision_task":"Σχεδιάστε τη μοριακή διερεύνηση και στη συνέχεια διατυπώστε για το νευρο-ογκολογικό board: Ποια ευρήματα στηρίζουν την ολοκληρωμένη διάγνωση, ποιο εύρημα είναι σχετικό με το πλαίσιο τεμοζολομίδης και ποια διαγνωστική πληροφορία δεν υποκαθίσταται από το DNA-NGS μόνο;","expected_path":["Χρησιμοποιήστε τη μορφολογία και το κλινικό πλαίσιο ως αφετηρία.","Διευκρινίστε την κατάσταση IDH.","Προγραμματίστε τη μεθυλίωση του υποκινητή MGMT ως ξεχωριστή επιγενετική εξέταση.","Εντάξτε κατάλληλα τον ταξινομητή μεθυλίωσης στην ταξινόμηση/διαγνωστική ολοκλήρωση.","Χρησιμοποιήστε NGS γλοιώματος ως πρόσθετο μοριακό επίπεδο.","Σταθμίστε τα αποτελέσματα ανάλογα με την κλινική τους λειτουργία.","Μην περιγράφετε το MGMT ως οδηγό μετάλλαξη."],"acceptable_alternatives":["Η κατάσταση IDH μπορεί να διευκρινιστεί με στοχευμένη IHC/αλληλούχηση ή κατάλληλη διαγνωστική NGS γλοιώματος.","Ένα ευρύτερο μοριακό panel μπορεί να προσφέρει πρόσθετες σημαντικές πληροφορίες, εφόσον παραμένει σαφές σε ποια κλινικά ερωτήματα δεν απαντά.","Το διαγνωστικό εύρος μπορεί να ποικίλλει ανάλογα με τα προηγούμενα ευρήματα και τη ροή εργασίας του ιδρύματος."],"low_value_traps":[{"label":"Ευρύ panel = πλήρης διάγνωση","why_bad":"Το τεχνικό εύρος δεν δείχνει αν έχει καλυφθεί το συγκεκριμένο κλινικό ερώτημα."},{"label":"MGMT ως μετάλλαξη","why_bad":"Συγχέει επιγενετικά και γενετικά διαγνωστικά επίπεδα."},{"label":"TMB/MSI ως κύριο επίκεντρο","why_bad":"Δεν αποτελεί κύριο άξονα απόφασης για το παρόν ερώτημα IDH/MGMT/τεμοζολομίδης."},{"label":"Απλή απαρίθμηση δεικτών","why_bad":"Μια ολοκληρωμένη έκθεση πρέπει να εξηγεί ποια πληροφορία είναι διαγνωστικά ή προβλεπτικά σημαντική."}],"twist":{"title":"Ένα μεγάλο panel – και παρ’ όλα αυτά λείπει η καθοριστική πληροφορία","content":"Η αλληλούχηση δείχνει IDH1/2 wild type, μετάλλαξη του υποκινητή TERT και σήμα ενίσχυσης EGFR· τα μοριακά ευρήματα ταιριάζουν στο πλαίσιο γλοιοβλαστώματος. Στο board ακούγεται: Τότε τελειώσαμε. Ωστόσο, το MGMT δεν έχει εξεταστεί. Μόνο η στοχευμένη συμπληρωματική εξέταση δείχνει μεθυλιωμένο υποκινητή MGMT· ο ταξινομητής μεθυλίωσης υποστηρίζει την κλάση γλοιοβλάστωμα, IDH-wildtype, με υψηλό classifier score.","why_critical":"Ένα διαγνωστικά εκτεταμένο εύρημα μπορεί να αφήσει αναπάντητο ένα συγκεκριμένο θεραπευτικό ερώτημα. Το επιγενετικό επίπεδο MGMT δεν υποκαθίσταται από συμβατικό DNA-NGS."},"result_packages":[{"id":"optimal","title":"Ολοκληρωμένη έκθεση","class":"optimal","result":"IDH-wildtype· μεθυλιωμένος υποκινητής MGMT· η κλάση μεθυλίωσης υποστηρίζει γλοιοβλάστωμα, IDH-wildtype· τα πρόσθετα μοριακά ευρήματα είναι συμβατά με το συνολικό πλαίσιο.","feedback":"Πολύ καλά. Οι επιμέρους μέθοδοι ενσωματώνονται σύμφωνα με τη διαγνωστική τους λειτουργία."},{"id":"incomplete","title":"Πολύ αλληλούχηση, ανοιχτό θεραπευτικό ερώτημα","class":"incomplete","result":"Εκτεταμένο DNA-NGS, αλλά χωρίς αποτέλεσμα μεθυλίωσης του υποκινητή MGMT.","feedback":"Τεχνικά εκτεταμένο, κλινικά ελλιπές. Το ερώτημα της τεμοζολομίδης παραμένει ανοιχτό."},{"id":"wrong","title":"Λανθασμένη εστίαση","class":"wrong","result":"Πρόσθετος έλεγχος TMB/MSI χωρίς πλήρη ολοκλήρωση IDH/MGMT.","feedback":"Οι εξετάσεις δεν απαντούν στο κεντρικό ερώτημα της περίπτωσης."}],"followup_logic":[{"trigger":"Λείπει MGMT","action":"Προσθέστε στοχευμένη ανάλυση μεθυλίωσης MGMT.","consequence":"Η θεραπευτική ερμηνεία παραμένει ελλιπής μέχρι τότε."},{"trigger":"Το MGMT ερμηνεύεται ως μετάλλαξη","action":"Αντιμετωπίστε το εννοιολογικό σφάλμα στο debriefing.","consequence":"Σαφής ποινή συλλογισμού."},{"trigger":"Πλήρης ολοκλήρωση","action":"Διατυπώστε την τελική νευρο-ογκολογική/MTB έκθεση.","consequence":"Πλήρης διαδρομή Deep Dive."}],"debrief_points":["Η μορφολογία, η μοριακή ταξινόμηση και οι προβλεπτικοί βιοδείκτες απαντούν σε διαφορετικά ερωτήματα.","Η μεθυλίωση του υποκινητή MGMT αποτελεί επιγενετικό διαγνωστικό επίπεδο.","Ένα ευρύ panel αλληλούχησης δεν ισοδυναμεί αυτόματα με πλήρη κλινική έκθεση.","Η καλή μοριακή παθολογία ιεραρχεί τις πληροφορίες ανάλογα με τη σημασία τους για τη διάγνωση και την απόφαση."],"instructor_notes":{"model_answer":"Η μορφολογική εικόνα είναι συμβατή με υψηλόβαθμο γλοιακό όγκο. Για την ολοκληρωμένη διάγνωση προσδιορίζεται η κατάσταση IDH. Η μεθυλίωση του υποκινητή MGMT πρέπει να αξιολογείται ξεχωριστά ως επιγενετικός προβλεπτικός δείκτης και δεν υποκαθίσταται από συμβατικό DNA-NGS. Ο ταξινομητής μεθυλίωσης και το NGS γλοιώματος μπορούν να συμπληρώσουν τη διαγνωστική ολοκλήρωση. Καθοριστική είναι η λειτουργική στάθμιση των επιμέρους ευρημάτων.","scoring_focus":["Τα διαγνωστικά επίπεδα διαχωρίζονται καθαρά.","Το IDH έχει ερμηνευθεί σωστά.","Το MGMT έχει ερμηνευθεί σωστά.","Χωρίς υπερερμηνεία της ευρείας αλληλούχησης.","Σαφής επικοινωνία MTB/νευρο-ογκολογίας."],"discussion_questions":["Πότε προσφέρει ένα ευρύ panel πραγματική προστιθέμενη αξία;","Τι σημαίνει πλήρης διάγνωση σε αυτή την περίπτωση;","Πώς πρέπει να αποτυπώνονται γλωσσικά στην έκθεση τα διαφορετικά διαγνωστικά επίπεδα;"]},"report_additions":{"content_status":"Επιμελημένο Deep Dive στα EL","key_turning_point":"Ευρύ NGS, αλλά λείπει MGMT","core_trap":"Το MGMT δεν είναι κλασική οδηγός μετάλλαξη","pattern":"Μορφολογία → ταξινόμηση → πρόβλεψη → ολοκλήρωση"},"is_signature_case":true},"LAB_DOC_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"LAB_DOC_001_v1_0","title":"«PCR όπως πάντα»: αναλυτικά έγκυρο, αλλά παρ’ όλα αυτά περίπτωση QM","domain":"LAB","target_course":"QM Basics","deep_dive_priority":"signature","target_role":"Διεύθυνση εργαστηρίου / QM / εργαστήριο μοριακής παθολογίας","estimated_minutes_deep":"12–15","learning_objectives":["Αξιολογήστε χωριστά την αναλυτική εγκυρότητα και τη συμμόρφωση διαδικασίας/τεκμηρίωσης.","Ανακατασκευάστε συστηματικά τα διαθέσιμα πρωτογενή δεδομένα πριν επαναλάβετε αντανακλαστικά την εξέταση.","Αποδεσμεύστε δείγμα ασθενούς με ασθενές σήμα βάσει κινδύνου, όταν η αναλυτική βάση έχει ανακατασκευαστεί με επαρκή τεκμηρίωση.","Αναγνωρίστε ότι ένα σημαντικό συστημικό κενό τεκμηρίωσης πρέπει, παρά την επιτυχή ανακατασκευή, να αντιμετωπιστεί ως απόκλιση/near miss και, στην παρούσα περίπτωση, να οδηγήσει σε CAPA.","Ελέγξτε την αποτελεσματικότητα μιας CAPA."],"opening_scene":"Το πρωί αρχίζει η προετοιμασία εσωτερικού audit στο εργαστήριο μοριακής παθολογίας. Επιλέγεται ως δείγμα ελέγχου ένα qPCR run KRAS. Στο εργαστηριακό βιβλίο υπάρχει ακριβώς μία πρόταση: «PCR όπως πάντα. Πήγε καλά. Δείγμα 4 ασθενές.» Η συνάδελφος θυμάται το run και λέει: «Όλα ήταν εντάξει. Οι μάρτυρες ήταν καλοί.» Το αποτέλεσμα του δείγματος 4 είναι κλινικά σημαντικό. Το ερώτημα πλέον δεν είναι μόνο: Ήταν τεχνικά σωστή η PCR; Αλλά: Μπορούμε να το αποδείξουμε με αξιοπιστία σήμερα – και τι κάνουμε αν μπορούμε;","case_briefing":"Routine qPCR test για hotspots KRAS. Η καταχώριση στο εργαστηριακό βιβλίο δεν περιέχει ούτε επαρκή αναφορά μεθόδου ούτε πλήρες audit trail. Λείπουν, μεταξύ άλλων, ημερομηνία/ώρα, χειριστής, έκδοση SOP, μοναδικά IDs δειγμάτων, kit/lot/ημερομηνία λήξης, όργανο και run-ID, θετικός/αρνητικός/NTC μάρτυρας, τιμές Ct/επαναλήψεις, διαδρομή ακατέργαστων δεδομένων και η τεκμηριωμένη επιστημονική αξιολόγηση του ασθενούς σήματος. Ωστόσο, τα πραγματικά ακατέργαστα δεδομένα και μεταδεδομένα μπορεί να παραμένουν διαθέσιμα στο όργανο, στο LIMS και στα ηλεκτρονικά συστήματα.","context_cards":[{"title":"Αρχική καταχώριση","content":"«PCR όπως πάντα. Πήγε καλά. Δείγμα 4 ασθενές.»","teaching_point":"Η ευλογοφάνεια δεν ισοδυναμεί με ιχνηλασιμότητα."},{"title":"Assay","content":"Routine qPCR test για hotspots KRAS.","teaching_point":"Η ρουτίνα δεν μειώνει τις απαιτήσεις τεκμηρίωσης."},{"title":"Δείγμα ασθενούς","content":"Το δείγμα 4 παρουσιάζει ασθενές σήμα.","teaching_point":"Ιδίως τα οριακά/ασθενή σήματα απαιτούν ιχνηλάσιμα πρωτογενή δεδομένα και τεκμηριωμένη αξιολόγηση."},{"title":"Σύγκρουση","content":"Ανακατασκευή ή προληπτική επανάληψη όλων;","teaching_point":"Το καλό QM βασίζεται στον κίνδυνο, όχι σε αντανακλαστικό μαξιμαλισμό."}],"pre_results":[{"title":"Κατάσταση τεκμηρίωσης","content":"Η αρχική τεκμηρίωση είναι ανεπαρκής, αλλά δεν υπάρχει ένδειξη γνωστής τεχνικής αποτυχίας του run."},{"title":"Διαθέσιμες πηγές","content":"Το export του οργάνου, το LIMS και πρόσθετα ηλεκτρονικά μεταδεδομένα παραμένουν διαθέσιμα."},{"title":"Πλαίσιο υλικού/χρόνου","content":"Το υπόλοιπο υλικό του ασθενούς είναι περιορισμένο. Μια επανάληψη θα κατανάλωνε επιπλέον χρόνο και υλικό."},{"title":"Ανοιχτό ερώτημα","content":"Δεν έχει ακόμη διευκρινιστεί αν μπορεί να ανακατασκευαστεί αξιόπιστα ολόκληρη η αναλυτική διαδρομή, συμπεριλαμβανομένου του ασθενούς δείγματος."}],"material_or_resource_constraints":["Το υλικό του ασθενούς δεν είναι απεριόριστα διαθέσιμο.","Κάθε επανάληψη καταναλώνει υλικό και απαιτεί χρόνο και πόρους.","Επομένως, μια περιττή επανάληψη δεν είναι αυτόματα ασφαλέστερη.","Από την άλλη, αποδέσμευση χωρίς αξιόπιστη ανακατασκευή δεν θα ήταν αποδεκτή.","Τα μέτρα QM πρέπει να αντιμετωπίζουν την πραγματική αιτία και όχι μόνο να εξαλείφουν συμπτώματα."],"reasoning_gate_upgrade":[{"id":"labdoc_primary_problem","type":"single_choice","prompt":"Ποιο είναι το κύριο πρόβλημα;","options":[{"id":"auto_invalid","label":"Το run είναι αυτόματα αναλυτικά άκυρο."},{"id":"traceability","label":"Η ιχνηλασιμότητα και η τεκμηριωμένη βάση αξιολόγησης είναι ανεπαρκείς."},{"id":"weak_never_release","label":"Ένα ασθενές δείγμα δεν μπορεί ποτέ να αποδεσμευθεί κατ’ αρχήν."},{"id":"routine_less_docs","label":"Η routine PCR απαιτεί λιγότερη τεκμηρίωση."}],"correct":["traceability"],"rationale":"Ένα έλλειμμα τεκμηρίωσης δεν συνεπάγεται αυτόματα αναλυτικό σφάλμα. Πρώτα πρέπει να ελεγχθεί αν η αναλυτική εγκυρότητα μπορεί να ανακατασκευαστεί από πηγαία δεδομένα."},{"id":"labdoc_reconstruct","type":"multi_select","prompt":"Ποιες πληροφορίες πρέπει να χρησιμοποιηθούν για ανακατασκευή κατάλληλη για audit;","options":[{"id":"who_when","label":"Χειριστής και χρονικό σημείο"},{"id":"sop","label":"Έκδοση SOP"},{"id":"lot","label":"Lot kit/αντιδραστηρίων και ημερομηνία λήξης"},{"id":"sample_id","label":"Μοναδική ταυτότητα δείγματος"},{"id":"run_id","label":"Όργανο και run-ID"},{"id":"controls","label":"Θετικός/αρνητικός/NTC μάρτυρας"},{"id":"ct_replicates","label":"Τιμές Ct και επαναλήψεις"},{"id":"rawdata","label":"Διαδρομή ακατέργαστων δεδομένων/πρωτογενή δεδομένα"},{"id":"sample4_review","label":"Επιστημονική αξιολόγηση του δείγματος 4"},{"id":"memory_only","label":"Η προφορική ανάμνηση της συναδέλφου ως μοναδική απόδειξη"}],"correct":["who_when","sop","lot","sample_id","run_id","controls","ct_replicates","rawdata","sample4_review"],"rationale":"Η ανακατασκευή πρέπει να βασίζεται σε πηγές και να είναι κατάλληλη για audit· η μνήμη από μόνη της δεν αρκεί."},{"id":"labdoc_release_or_repeat","type":"single_choice","prompt":"Η ανακατασκευή δείχνει μοναδική αντιστοίχιση δείγματος, έγκυρα δεδομένα SOP/lot, έγκυρους μάρτυρες, πλήρη ακατέργαστα δεδομένα και αναπαραγώγιμο ασθενές σήμα στο δείγμα 4. Ποια είναι τώρα η σωστή ενέργεια;","options":[{"id":"release_after_review","label":"Τεκμηριώστε με διαφάνεια την ανακατασκευή και την επιστημονική επαναξιολόγηση· αποδεσμεύστε το δείγμα 4· αποφύγετε περιττή επανάληψη."},{"id":"repeat_all","label":"Επαναλάβετε ολόκληρο το run ανεξάρτητα από τα διαθέσιμα πρωτογενή δεδομένα."},{"id":"weak_hold","label":"Μην αποδεσμεύσετε το δείγμα 4 επειδή ένα ασθενές σήμα θεωρείται εξ ορισμού αναξιόπιστο."},{"id":"release_no_docs","label":"Απλώς αποδεσμεύστε το αποτέλεσμα και αφήστε την αρχική τεκμηρίωση αμετάβλητη."}],"correct":["release_after_review"],"rationale":"Η αναλυτική εγκυρότητα τεκμηριώνεται από τα πρωτογενή δεδομένα. Η επανάληψη δεν είναι αυτοσκοπός και θα κατανάλωνε άσκοπα υλικό, χρόνο και πόρους."},{"id":"labdoc_capa","type":"single_choice","prompt":"Έχει κλείσει η περίπτωση μετά την επιτυχή ανακατασκευή του αποτελέσματος;","options":[{"id":"done_no_harm","label":"Ναι. Δεν προέκυψε βλάβη για τον ασθενή."},{"id":"near_miss_capa","label":"Όχι. Το σημαντικό κενό τεκμηρίωσης αξιολογείται βάσει κινδύνου ως απόκλιση/near miss· το συστημικό πρόβλημα που αναγνωρίστηκε εδώ αντιμετωπίζεται με CAPA και έλεγχο αποτελεσματικότητας."},{"id":"verbal_reminder","label":"Αρκεί μια ανεπίσημη υπενθύμιση προς την ομάδα."},{"id":"rewrite_old","label":"Η παλιά καταχώριση στο εργαστηριακό βιβλίο διαγράφεται και ξαναγράφεται."}],"correct":["near_miss_capa"],"rationale":"Η επιτυχής ανακατασκευή αποτρέπει ένα σφάλμα, αλλά δεν εξαλείφει τη συστημική αδυναμία που σχεδόν το επέτρεψε."}],"decision_task":"Λάβετε δύο ξεχωριστές αποφάσεις: Είναι αποδεσμεύσιμο το συγκεκριμένο αποτέλεσμα του ασθενούς μετά την ανακατασκευή; Ποια συνέπεια QM προκύπτει από την ανεπαρκή αρχική διαδικασία;","expected_path":["Αναγνωρίστε το έλλειμμα τεκμηρίωσης.","Μην απορρίψετε αυτόματα το αποτέλεσμα.","Ανακατασκευάστε συστηματικά τα πρωτογενή δεδομένα και τα μεταδεδομένα.","Επιβεβαιώστε την εγκυρότητα του run από τους μάρτυρες.","Επαναξιολογήστε επιστημονικά το ασθενές δείγμα βάσει Ct/επαναλήψεων και ακατέργαστων δεδομένων.","Αποδεσμεύστε το αποτέλεσμα με διαφανή τεκμηρίωση.","Καταγράψτε το αρχικό έλλειμμα τεκμηρίωσης ως απόκλιση/near miss.","Αναλύστε τη βασική αιτία.","Εφαρμόστε CAPA.","Ελέγξτε την αποτελεσματικότητα μέσω επόμενων τεκμηριώσεων."],"acceptable_alternatives":["Μια επανάληψη δικαιολογείται εάν κρίσιμα στοιχεία όπως η ταυτότητα δείγματος, οι μάρτυρες, τα πρωτογενή δεδομένα ή η επιστημονική αξιολόγηση δεν μπορούν να ανακατασκευαστούν αξιόπιστα.","Η επανάληψη προκύπτει από τον κίνδυνο – όχι απλώς από την ύπαρξη μιας απόκλισης."],"low_value_traps":[{"label":"Πάντα επανάληψη όταν υπάρχει απόκλιση","why_bad":"Μπορεί να καταναλώσει άσκοπα υλικό ασθενούς, χρόνο και πόρους και δεν λύνει τη βασική αιτία της διαδικασίας."},{"label":"Δεν συνέβη τίποτα, άρα δεν χρειάζεται CAPA","why_bad":"Το near miss και η συστημική αδυναμία της διαδικασίας παραμένουν."},{"label":"Προσθήκη μόνο της τιμής Ct εκ των υστέρων","why_bad":"Η ιχνηλασιμότητα παραμένει ελλιπής."},{"label":"Μόνο εκπαίδευση","why_bad":"Εκπαίδευση χωρίς σύνδεση με τη βασική αιτία και χωρίς έλεγχο αποτελεσματικότητας δεν αποτελεί ισχυρή CAPA."},{"label":"Προφορική ανάμνηση","why_bad":"Δεν αποτελεί υποκατάστατο πρωτογενών δεδομένων κατάλληλο για audit."}],"twist":{"title":"Το ασθενές δείγμα είναι πράγματι αποδεσμεύσιμο","content":"Η ανακατασκευή δείχνει ότι το run ήταν τεχνικά έγκυρο, οι μάρτυρες ήταν σωστοί και το δείγμα 4 παρουσιάζει αναπαραγώγιμο ασθενές σήμα στα πρωτογενή δεδομένα. Μετά από τεκμηριωμένη επιστημονική επαναξιολόγηση, το δείγμα μπορεί να αποδεσμευθεί· δεν απαιτείται πλήρης επανάληψη. Ωστόσο, δειγματοληπτικός έλεγχος άλλων καταχωρίσεων στο εργαστηριακό βιβλίο δείχνει αρκετές παρόμοια συντομευμένες διατυπώσεις – από μεμονωμένη περίπτωση προκύπτει συστημική αδυναμία τεκμηρίωσης.","why_critical":"Η αναλυτική εγκυρότητα και η συμμόρφωση της διαδικασίας είναι ξεχωριστά ερωτήματα. Το συγκεκριμένο αποτέλεσμα μπορεί να διασωθεί, ενώ το near miss εξακολουθεί να απαιτεί διαχείριση απόκλισης/CAPA βάσει κινδύνου."},"result_packages":[{"id":"optimal","title":"Αποδέσμευση βάσει κινδύνου + CAPA","class":"optimal","result":"Run και δείγμα 4 πλήρως ανακατασκευασμένα, επιστημονικά αποδεσμευμένα, απόκλιση τεκμηριωμένη, βασική αιτία αντιμετωπισμένη, CAPA με έλεγχο αποτελεσματικότητας.","feedback":"Πολύ καλά. Η αναλυτική εγκυρότητα και η συμμόρφωση της διαδικασίας αξιολογήθηκαν χωριστά και βάσει κινδύνου."},{"id":"incomplete","title":"Αντανακλαστικό ασφάλειας: επανάληψη όλων","class":"incomplete","result":"Ολόκληρο το run επαναλαμβάνεται παρότι όλα τα σημαντικά πρωτογενή δεδομένα ήταν διαθέσιμα.","feedback":"Η επανάληψη δεν είναι αυτοσκοπός. Δεν λήφθηκαν υπόψη η κατανάλωση υλικού και πόρων· η βασική αιτία της διαδικασίας παραμένει άλυτη."},{"id":"release_no_capa","title":"Σωστό αποτέλεσμα, λάθος QM","class":"incomplete","result":"Το δείγμα αποδεσμεύεται σωστά, αλλά το πρόβλημα τεκμηρίωσης θεωρείται στη συνέχεια λήξαν.","feedback":"Το συγκεκριμένο αποτέλεσμα διασώθηκε, αλλά όχι η συστημική αιτία."},{"id":"wrong","title":"Αποδέσμευση μόνο βάσει μνήμης","class":"wrong","result":"Αποδέσμευση αποκλειστικά βάσει ρουτίνας και ανάμνησης.","feedback":"Δεν είναι κατάλληλο για audit ούτε επαρκώς τεκμηριωμένο."}],"followup_logic":[{"trigger":"Τα πρωτογενή δεδομένα δεν μπορούν να ανακατασκευαστούν πλήρως","action":"Διατηρήστε σε hold και εκτελέστε στοχευμένη επανάληψη ή/και περαιτέρω διευκρίνιση.","consequence":"Καμία αποδέσμευση χωρίς αξιόπιστη βάση."},{"trigger":"Πλήρης ανακατασκευή συν έγκυροι μάρτυρες","action":"Εκτελέστε και τεκμηριώστε επιστημονική επαναξιολόγηση.","consequence":"Η αποδέσμευση μπορεί να είναι δυνατή."},{"trigger":"Συστημικό κενό τεκμηρίωσης","action":"Εκτελέστε ανάλυση βασικής αιτίας και CAPA.","consequence":"Προσαρμόστε template/διαδικασία/εκπαίδευση ανάλογα με την αιτία."},{"trigger":"Εφαρμόστηκε CAPA","action":"Ελέγξτε δειγματοληπτικά τις επόμενες τεκμηριώσεις qPCR.","consequence":"Έλεγχος αποτελεσματικότητας αντί απλής τυπικής ολοκλήρωσης του μέτρου."}],"debrief_points":["Η αναλυτική εγκυρότητα και η συμμόρφωση της διαδικασίας είναι διαφορετικά ερωτήματα.","Μια απόκλιση δεν καθιστά αυτόματα ένα αποτέλεσμα άκυρο.","Μια επανάληψη πρέπει να αιτιολογείται βάσει κινδύνου.","Το περιορισμένο υλικό, ο χρόνος και οι πόροι ανήκουν στην εκτίμηση κινδύνου.","Ένα near miss είναι ιδιαίτερα διδακτικό όταν η αδυναμία εντοπίζεται πριν προκύψει βλάβη.","Η CAPA ολοκληρώνεται με έλεγχο αποτελεσματικότητας, όχι με «το προσωπικό εκπαιδεύτηκε»."],"instructor_notes":{"model_answer":"Πρώτα ανακατασκευάζεται η ιχνηλασιμότητα από LIMS, export οργάνου, SOP, lot, μάρτυρες και ακατέργαστα δεδομένα. Εάν η ταυτότητα δείγματος, η εγκυρότητα του run και η ασθενής θετικότητα του δείγματος 4 μπορούν να τεκμηριωθούν αξιόπιστα, το αποτέλεσμα μπορεί να αποδεσμευθεί μετά από τεκμηριωμένη επαναξιολόγηση. Δεν απαιτείται γενικευμένη επανάληψη. Το αρχικό έλλειμμα τεκμηρίωσης αντιμετωπίζεται παρ’ όλα αυτά ως σημαντική απόκλιση με χαρακτήρα near miss. Εάν αναγνωριστεί συστημικό πρόβλημα, ακολουθούν ανάλυση βασικής αιτίας, κατάλληλη CAPA και έλεγχος αποτελεσματικότητας.","scoring_focus":["Ανακατασκευή πριν από επανάληψη.","Πρωτογενή δεδομένα αντί για μνήμη.","Σωστή αποδέσμευση του ασθενούς δείγματος.","Η απόκλιση/near miss δεν αγνοείται.","CAPA συνδεδεμένη με τη βασική αιτία.","Έλεγχος αποτελεσματικότητας."],"discussion_questions":["Πότε είναι πράγματι απαραίτητη η επανάληψη;","Μπορεί ένα αποτέλεσμα να είναι έγκυρο παρότι η διαδικασία ήταν ελαττωματική;","Πού βρίσκεται το όριο μεταξύ correction και CAPA;","Γιατί περισσότερη ασφάλεια δεν σημαίνει αυτόματα περισσότερες επαναλήψεις;"]},"report_additions":{"content_status":"Επιμελημένο Deep Dive στα EL","key_turning_point":"Ασθενές δείγμα αποδεσμεύσιμο μετά από ανακατασκευή","core_message":"Αναλυτική εγκυρότητα ≠ συμμόρφωση διαδικασίας","pattern":"Ανακατασκευή → εκτίμηση κινδύνου → αποδέσμευση → CAPA → έλεγχος αποτελεσματικότητας"},"is_signature_case":true},"RES_OMICS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_OMICS_001_v1_0","title":"200 DEGs, ένας βιοδείκτης; Από το σήμα RNA-seq σε μια ισχυρή υπόθεση αντοχής","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Μεταφραστική έρευνα / μοριακή παθολογία / βιοπληροφορική","estimated_minutes_deep":"18–22","learning_objectives":["Μετατρέψτε λίστες DEGs σε βιολογικά προγράμματα αντί για ιστορίες ενός γονιδίου.","Μετατρέψτε μια παρατήρηση omics σε ελέγξιμη υπόθεση και PICO.","Διακρίνετε discovery, τεχνική επικύρωση, μορφολογική επικύρωση και εξωτερική αναπαραγωγή.","Μην υπερερμηνεύετε διερευνητικά αποτελέσματα ως έτοιμο βιοδείκτη.","Δώστε προτεραιότητα στην ανθεκτικότητα μιας υπογραφής έναντι ενός ελκυστικού μεμονωμένου γονιδίου."],"opening_scene":"Δευτέρα πρωί στη συνάντηση μεταφραστικής έρευνας. Μια υποψήφια διδάκτωρ ολοκλήρωσε την πρώτη της ανάλυση RNA-seq: 30 όγκοι που έλαβαν ICI, 15 responders και 15 non-responders. Στη διαφάνειά της γράφει: «200 σημαντικά DEGs». Από κάτω υπάρχει ταξινομημένος πίνακας. Ρωτά: «Ποιο γονίδιο παίρνω τώρα ως βιοδείκτη;» Το χαμηλότερο p-value φαίνεται εντυπωσιακό. Αλλά ακριβώς εδώ αρχίζει η πραγματική επιστημονική εργασία.","case_briefing":"RNA-seq σε 30 όγκους που έλαβαν ICI: 15 responders και 15 non-responders. Στους non-responders αυξάνονται μεταξύ άλλων TGFB1, COL1A1, CXCL12, ACTA2, FN1 και άλλα γονίδια ECM, ενώ HLA-A, B2M, TAP1, CXCL9 και GZMB μειώνονται. Η ανάλυση pathways δείχνει αυξημένα TGFβ/ECM και μειωμένη παρουσίαση αντιγόνου/ενεργοποίηση Τ-κυττάρων. Κλινικά, οι πλούσιοι σε στρώμα όγκοι συνδέονται με χειρότερη ανταπόκριση σε ICI.","context_cards":[{"title":"Κοόρτη discovery","content":"30 όγκοι με ICI, 15 responders έναντι 15 non-responders.","teaching_point":"Μικρές κοόρτες discovery είναι κατάλληλες για δημιουργία υποθέσεων, όχι αυτόματα για claim βιοδείκτη."},{"title":"Σήμα RNA-seq","content":"200 διαφορικά εκφραζόμενα γονίδια.","teaching_point":"Μια λίστα γονιδίων δεν αποτελεί ακόμη βιολογική εξήγηση."},{"title":"Βιολογικό πρότυπο","content":"TGFβ/ECM αυξημένα, παρουσίαση αντιγόνου/ενεργοποίηση Τ-κυττάρων μειωμένη.","teaching_point":"Συντονισμένα προγράμματα μπορεί να είναι πιο πληροφοριακά από ένα μεμονωμένο γονίδιο."},{"title":"Μεταφραστικός στόχος","content":"Ανάπτυξη μηχανισμού και κλινικά ελέγξιμης υπογραφής.","teaching_point":"Η μετάβαση από omics σε μεταφραστική εφαρμογή απαιτεί πολλαπλά επίπεδα επικύρωσης."}],"pre_results":[{"title":"Non-responders – αυξημένα","content":"TGFB1, COL1A1, CXCL12, ACTA2, FN1 και άλλα γονίδια ECM."},{"title":"Non-responders – μειωμένα","content":"HLA-A, B2M, TAP1, CXCL9 και GZMB."},{"title":"Εμπλουτισμός pathways","content":"TGFβ/ECM αυξημένα· παρουσίαση αντιγόνου/ενεργοποίηση Τ-κυττάρων μειωμένη."},{"title":"Δεν έχει ακόμη αποφασιστεί","content":"Το ισχυρότερο μεμονωμένο γονίδιο, μια υπογραφή και ένα βιολογικό πρόγραμμα δεν είναι το ίδιο πράγμα. Η ερμηνεία πρέπει να ιεραρχηθεί ενεργά."}],"material_or_resource_constraints":["Κοόρτη discovery: n = 30.","Πρέπει να λαμβάνονται υπόψη πολλαπλοί έλεγχοι/FDR.","Πρέπει να καταγράφονται κλινικοί συγχυτικοί παράγοντες όπως θεραπεία, οντότητα όγκου, ECOG και περιεκτικότητα όγκου.","Ο προϋπολογισμός επαρκεί για στοχευμένη τεχνική και μορφολογική επικύρωση, όχι για απεριόριστο multi-omics.","Απαιτείται ανεξάρτητη επικύρωση πριν από οποιοδήποτε claim βιοδείκτη."],"reasoning_gate_upgrade":[{"id":"omics_from_degs","type":"single_choice","prompt":"Πώς μετατρέπονται 200 DEGs σε ισχυρό ερευνητικό ερώτημα;","options":[{"id":"lowest_p","label":"Επιλέξτε το γονίδιο με το χαμηλότερο p-value."},{"id":"all_genes","label":"Αναφέρετε και τα 200 γονίδια ως ισοδύναμης σημασίας."},{"id":"programs","label":"Εντοπίστε συντονισμένα βιολογικά προγράμματα και κοινά pathways."},{"id":"expected_only","label":"Κρατήστε μόνο τα γονίδια που ταιριάζουν στην αναμενόμενη ιστορία."}],"correct":["programs"],"rationale":"Το κοινό στρωματικό/ανοσολογικό πρότυπο παρέχει ισχυρότερη υπόθεση από ένα απομονωμένο μεμονωμένο γονίδιο."},{"id":"omics_hypothesis","type":"single_choice","prompt":"Ποια υπόθεση ταιριάζει καλύτερα στα διαθέσιμα δεδομένα;","options":[{"id":"stroma_immune","label":"Η πρωτοπαθής μη ανταπόκριση σε ICI σχετίζεται με μικροπεριβάλλον όγκου που κυριαρχείται από στρώμα/TGFβ και ταυτόχρονα είναι φτωχό σε αντιγόνα."},{"id":"tgfb1_marker","label":"Το TGFB1 είναι ο νέος προβλεπτικός βιοδείκτης."},{"id":"all_degs_explain","label":"Τα 200 DEGs εξηγούν ήδη πλήρως την αντοχή σε ICI."},{"id":"one_resistance_gene","label":"Όλοι οι non-responders έχουν το ίδιο γονίδιο αντοχής."}],"correct":["stroma_immune"],"rationale":"Η υπόθεση ενσωματώνει πολλαπλά συντονισμένα προγράμματα έκφρασης και παραμένει ελέγξιμη χωρίς υπερερμηνεία ενός μεμονωμένου διερευνητικού hit."},{"id":"omics_pico","type":"multi_select","prompt":"Ποια στοιχεία ανήκουν σε μια σωστή επιχειρησιακή διατύπωση της υπόθεσης;","options":[{"id":"population","label":"Πληθυσμός: όγκοι που έλαβαν ICI"},{"id":"exposure","label":"Έκθεση/υπογραφή: υψηλή υπογραφή CAF/TGFβ"},{"id":"comparison","label":"Σύγκριση: χαμηλή υπογραφή"},{"id":"outcome","label":"Outcome: ανταπόκριση/PFS"},{"id":"score_cutoff","label":"Ορίστε τη στρατηγική score/cutoff πριν από την επικύρωση"},{"id":"confounders","label":"Ορίστε σχετικούς συγχυτικούς παράγοντες και το πλάνο ανάλυσης"},{"id":"posthoc_cutoff","label":"Ορίστε το cutoff μόνο αφού φανεί το πιο ευνοϊκό αποτέλεσμα επικύρωσης"}],"correct":["population","exposure","comparison","outcome","score_cutoff","confounders"],"rationale":"Η υπόθεση, το PICO, το score/cutoff και το πλάνο ανάλυσης πρέπει να έχουν οριστεί επιχειρησιακά πριν από την επικύρωση."},{"id":"omics_validation","type":"multi_select","prompt":"Ποια βήματα επικύρωσης είναι ισχυρά για μεταφραστική ανάπτυξη;","options":[{"id":"targeted","label":"Στοχευμένο RNA/qPCR/NanoString"},{"id":"external","label":"Ανεξάρτητη κοόρτη ICI"},{"id":"morphology","label":"αSMA/FAP/CD8/HLA-I/B2M ως μορφολογική γέφυρα"},{"id":"fdr","label":"Διαφανής αναφορά FDR και πολλαπλών ελέγχων"},{"id":"heatmap_only","label":"Ξανασχεδιάστε το heatmap"},{"id":"single_wb","label":"Επιβεβαιώστε μόνο το ισχυρότερο μεμονωμένο γονίδιο με Western blot"}],"correct":["targeted","external","morphology","fdr"],"rationale":"Η τεχνική, μορφολογική και ανεξάρτητη επικύρωση αλληλοσυμπληρώνονται· η απλή οπτικοποίηση ή μία μόνο επιβεβαιωτική δοκιμή δεν επαρκούν για υπόθεση υπογραφής."}],"decision_task":"Αναπτύξτε από τη διερευνητική ανάλυση RNA-seq μια ισχυρή μεταφραστική στρατηγική: βιολογική υπόθεση, PICO, concept υπογραφής/ανάλυσης, τεχνική επικύρωση, μορφολογική γέφυρα, εξωτερική επικύρωση και όριο επιτρεπτής διεκδίκησης βιοδείκτη.","expected_path":["Μην αντιμετωπίζετε τη λίστα DEGs ως τελικό προϊόν.","Δώστε προτεραιότητα στο επίπεδο pathway/δικτύου.","Διατυπώστε πρότυπο που κυριαρχείται από στρώμα/TGFβ και είναι φτωχό σε αντιγόνα.","Ορίστε υπόθεση και PICO.","Καταστήστε επιχειρησιακά μετρήσιμη την υπογραφή.","Λάβετε υπόψη FDR και συγχυτικούς παράγοντες.","Πραγματοποιήστε στοχευμένη τεχνική επικύρωση.","Συνδέστε μορφολογικά τα ευρήματα με δείκτες TME.","Χρησιμοποιήστε ανεξάρτητη κοόρτη.","Μόνο τότε συζητήστε τη δυνατότητα βιοδείκτη."],"acceptable_alternatives":["Ολοκληρώστε τη μελέτη ρητά ως διερευνητική χωρίς claim βιοδείκτη.","Αναπτύξτε μικρότερη, εστιασμένη υπογραφή αντί για σύνθετο score.","Χρησιμοποιήστε targeted expression/NanoString αντί για νέο RNA-seq για τεχνική επικύρωση.","Προσθέστε λειτουργική επικύρωση εάν το μηχανιστικό ερώτημα είναι κεντρικό."],"low_value_traps":[{"label":"Χαμηλότερο p-value = βιοδείκτης","why_bad":"Μεμονωμένα γονίδια μπορεί να είναι ασταθή και να χάνουν το βιολογικό πλαίσιο."},{"label":"Heatmap = επικύρωση","why_bad":"Η οπτικοποίηση δεν αποδεικνύει ανεξάρτητη αναπαραγωγιμότητα."},{"label":"200 DEGs ως αποτέλεσμα","why_bad":"Ο όγκος δεδομένων δεν υποκαθιστά μια υπόθεση."},{"label":"Βελτιστοποίηση cutoff εκ των υστέρων","why_bad":"Κίνδυνος overfitting/HARKing."},{"label":"Αφαίρεση αποτελεσμάτων που δεν ταιριάζουν","why_bad":"Επιλεκτική αναφορά."}],"twist":{"title":"Το «καλύτερο γονίδιο» εξαφανίζεται – η βιολογία παραμένει","content":"Σε ανεξάρτητη κοόρτη επικύρωσης, το μεμονωμένο γονίδιο με το χαμηλότερο discovery p-value δεν αναπαράγεται πειστικά. Αντίθετα, η προκαθορισμένη στρωματική/ανοσολογική υπογραφή συνεχίζει να δείχνει το ίδιο συντονισμένο πρότυπο: αυξημένη στρωματική/TGFβ συνιστώσα και μειωμένη συνιστώσα παρουσίασης αντιγόνου/Τ-κυττάρων. Η μορφολογική επικύρωση υποστηρίζει επίσης την ερμηνεία σε επίπεδο προγράμματος.","why_critical":"Το πιο ελκυστικό μεμονωμένο discovery hit δεν είναι κατ’ ανάγκη το πιο ανθεκτικό βιολογικό σήμα. Η περίπτωση διαχωρίζει μεμονωμένο γονίδιο, υπογραφή, μηχανισμό και επικυρωμένο βιοδείκτη."},"result_packages":[{"id":"optimal","title":"Επικυρωμένη υπόθεση υπογραφής","class":"optimal","result":"Υπόθεση βασισμένη σε pathways, προκαθορισμένη υπογραφή, τεχνική επικύρωση, μορφολογική γέφυρα και ανεξάρτητη κοόρτη δείχνουν συνεπές πρότυπο.","feedback":"Πολύ καλή μεταφραστική ανάπτυξη. Η δυνατότητα βιοδείκτη μπορεί πλέον να συζητηθεί με προσοχή."},{"id":"incomplete","title":"Κατάρρευση μεμονωμένου γονιδίου","class":"incomplete","result":"Το ισχυρότερο μεμονωμένο discovery γονίδιο δεν αναπαράγεται, αλλά η συνολική υπογραφή παραμένει συνεπής.","feedback":"Δεν αποτελεί αποτυχία του project εάν η βιολογική υπόθεση υποστηρίζεται ανεξάρτητα."},{"id":"heatmap_story","title":"Όμορφο heatmap, χωρίς επικύρωση","class":"incomplete","result":"Διερευνητικό cluster χωρίς ανεξάρτητη αναπαραγωγή.","feedback":"Ενδιαφέρον, αλλά όχι ισχυρός βιοδείκτης."},{"id":"wrong","title":"Overclaim","class":"wrong","result":"Η discovery υπογραφή περιγράφεται απευθείας ως προβλεπτικός βιοδείκτης.","feedback":"Η ερμηνεία υπερβαίνει την αποδεικτική ισχύ των δεδομένων."}],"followup_logic":[{"trigger":"Ιεραρχείται μόνο ένα μεμονωμένο γονίδιο","action":"Επαναφέρετε την ανάλυση pathways/δικτύων στον συλλογισμό.","consequence":"Reasoning cap για μονοδεικτική ερμηνεία."},{"trigger":"Χωρίς ανεξάρτητη επικύρωση","action":"Χαρακτηρίστε το αποτέλεσμα ως διερευνητικό.","consequence":"Κανένα claim βιοδείκτη."},{"trigger":"Η υπογραφή αναπαράγεται","action":"Ελέγξτε τη μορφολογική και κλινική μετάφραση.","consequence":"Βέλτιστη διαδρομή Deep Dive."}],"debrief_points":["Μια λίστα DEGs δεν είναι ακόμη βιολογικό μοντέλο.","Οι πληροφορίες pathway και υπογραφής μπορεί να είναι πιο ανθεκτικές από ένα μεμονωμένο discovery γονίδιο.","Η τεχνική, μορφολογική και εξωτερική επικύρωση απαντούν σε διαφορετικά ερωτήματα.","Discovery και validation πρέπει να διαχωρίζονται.","Η αποτυχία αναπαραγωγής ενός μεμονωμένου hit μπορεί να βελτιώσει μια υπόθεση αντί να καταστρέψει το project.","Ένας βιοδείκτης είναι αποτέλεσμα αλυσίδας επικύρωσης, όχι ενός όμορφου heatmap."],"instructor_notes":{"model_answer":"Τα δεδομένα ερμηνεύονται πρώτα σε επίπεδο pathways/δικτύων. Το συντονισμένο πρότυπο υψηλού TGFβ/ECM και χαμηλής παρουσίασης αντιγόνου διατυπώνεται ως διερευνητική υπόθεση αντοχής. Στη συνέχεια ορίζονται επιχειρησιακά ο πληθυσμός, η υπογραφή, η σύγκριση και το outcome. Η υπογραφή επικυρώνεται τεχνικά, μορφολογικά και σε ανεξάρτητη κοόρτη. Μεμονωμένα γονίδια και cutoffs δεν υπερερμηνεύονται post hoc ως έτοιμοι βιοδείκτες.","scoring_focus":["Pathway πριν από μεμονωμένο γονίδιο.","Σαφής υπόθεση/PICO.","FDR/συγχυτικοί παράγοντες λαμβάνονται υπόψη.","Discovery έναντι validation διαχωρισμένα.","Μορφολογική γέφυρα.","Κατάλληλα περιορισμένο claim βιοδείκτη."],"discussion_questions":["Πότε μια υπογραφή υπερέχει ενός μεμονωμένου δείκτη;","Τι σημαίνει πραγματικά ανεξάρτητη επικύρωση;","Πώς μπορεί ένα αρνητικό αποτέλεσμα επικύρωσης να έχει επιστημονική αξία;","Πότε μπορεί μια συσχέτιση να γίνει project βιοδείκτη;"]},"report_additions":{"content_status":"Επιμελημένο Deep Dive στα EL","key_turning_point":"Το καλύτερο μεμονωμένο hit δεν αναπαράγεται","core_message":"DEG → pathway → υπόθεση → υπογραφή → επικύρωση","pattern":"Μην συγχέετε το discovery με την απόδειξη βιοδείκτη"},"is_signature_case":true},"RES_ETH_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_ETH_001_v1_0","title":"120 αρχειακά blocks και χωρίς σαφή συγκατάθεση: μπορεί να ξεκινήσει το project;","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Διοίκηση μεταφραστικού project / παθολογία / QM έρευνας","estimated_minutes_deep":"18–22","learning_objectives":["Κατανοήστε το governance ως προϋπόθεση της επιστημονικής εργασίας και όχι ως μεταγενέστερη τυπική διαδικασία.","Σχεδιάστε χωριστά ηθική/συγκατάθεση, προστασία υλικού, προστασία δεδομένων και διαχείριση τυχαίων ευρημάτων.","Αναγνωρίστε γιατί το υπολειπόμενο υλικό και η ανωνυμοποίηση δεν αποτελούν γενικές εγκρίσεις.","Σχεδιάστε μια ερευνητική απόφαση έτσι ώστε να καλύπτονται εκ των προτέρων μεταγενέστερες καταστάσεις υποψίας βλαστικής παραλλαγής και data sharing."],"opening_scene":"Μια ερευνητική ομάδα παρουσιάζει νέο project: 120 αρχειοθετημένα FFPE blocks όγκων πρόκειται να αναλυθούν με διευρυμένο panel DNA/RNA για νέους δείκτες αντοχής. Το assay, η βιοπληροφορική και ο προϋπολογισμός είναι έτοιμα. Η διοίκηση του project λέει: «Είναι απλώς υπολειπόμενο υλικό. Μπορούμε να ξεκινήσουμε την επόμενη εβδομάδα.» Ωστόσο, τα blocks προέρχονται από διαφορετικά έτη, η κατάσταση συγκατάθεσης είναι ανομοιογενής και σε ορισμένα μικρά blocks δεν είναι σαφές το διαγνωστικό απόθεμα. Επιπλέον, το σχεδιαζόμενο tumor-only panel μπορεί να δώσει ενδείξεις για παραλλαγές με πιθανή σημασία για τη βλαστική σειρά. Επομένως, η πρώτη απόφαση πρέπει να ληφθεί πριν κοπεί οποιοδήποτε δείγμα.","case_briefing":"Στόχος project: αναγνώριση νέων μοριακών δεικτών θεραπευτικής αντοχής σε αναδρομική κοόρτη όγκων. Σχεδιάζονται 120 routine FFPE blocks, διευρυμένο panel DNA/RNA, σύνδεση με κλινικά δεδομένα και follow-up, δημοσίευση και, εφόσον απαιτείται, εξωτερική επικύρωση/data sharing. Η κατάσταση συγκατάθεσης/governance είναι ανομοιογενής, το απόθεμα ιστού είναι περιορισμένο σε ορισμένες περιπτώσεις και δεν υπάρχει ακόμη καθορισμένη διαδικασία για τυχαία ευρήματα/υποψία βλαστικής προέλευσης.","context_cards":[{"title":"Υλικό","content":"Routine FFPE, εν μέρει μικρά blocks· το διαγνωστικό απόθεμα δεν είναι εξασφαλισμένο σε κάθε περίπτωση.","teaching_point":"Η έρευνα δεν πρέπει να θέτει σε κίνδυνο τη μελλοντική φροντίδα των ασθενών."},{"title":"Συγκατάθεση","content":"Διαφορετικά έτη και ανομοιογενής κατάσταση consent/governance.","teaching_point":"Αρχειοθετημένο δεν σημαίνει αυτόματα ελεύθερα διαθέσιμο."},{"title":"Δεδομένα","content":"Τα κλινικά δεδομένα και το follow-up πρόκειται να συνδεθούν.","teaching_point":"Η προστασία δεδομένων και η πρόσβαση ανήκουν στον σχεδιασμό της μελέτης."},{"title":"Γενετική","content":"Η tumor-only ανάλυση μπορεί να δημιουργήσει υποψία ευρήματος βλαστικής προέλευσης.","teaching_point":"Οι οδοί ενημέρωσης πρέπει να έχουν οριστεί πριν από την ανάλυση."},{"title":"Data sharing","content":"Σχεδιάζονται εξωτερική επικύρωση και δημοσίευση.","teaching_point":"Η μεταγενέστερη χρήση δεδομένων πρέπει να καλύπτεται από το πλαίσιο governance."}],"pre_results":[{"title":"Κοόρτη","content":"120 πιθανά περιστατικά από διαφορετικά έτη."},{"title":"Governance","content":"Δεν υπάρχει ενιαία κατάσταση συγκατάθεσης· εκκρεμεί η τελική αποδέσμευση υλικού."},{"title":"Πλάνο δεδομένων","content":"Τα κλινικά δεδομένα θα συμπληρωθούν αναδρομικά· η εξωτερική επικύρωση συζητείται ως μεταγενέστερη επιλογή."},{"title":"Προβλέψιμα τυχαία ευρήματα","content":"Το tumor-only panel μπορεί να εντοπίσει παραλλαγές με πιθανή βλαστική σημασία· πρέπει να υπάρχει καθορισμένη διαδικασία πριν από την έναρξη."}],"material_or_resource_constraints":["Το διαγνωστικό απόθεμα έχει προτεραιότητα έναντι της κατανάλωσης για έρευνα.","Δεν είναι απαραίτητο να ενταχθεί κάθε περίπτωση στην τελική κοόρτη.","Το follow-up και η δυνατότητα ελεγχόμενης ενημέρωσης μπορεί να συγκρούονται με πλήρη ανωνυμοποίηση.","Το εύρος δεδομένων και η πρόσβαση πρέπει να περιορίζονται στα απολύτως απαραίτητα.","Οι αποφάσεις governance πρέπει να λαμβάνονται πριν από μη αναστρέψιμη επεξεργασία υλικού και δεδομένων."],"reasoning_gate_upgrade":[{"id":"eth_start","type":"single_choice","prompt":"Μπορεί να ξεκινήσει αμέσως το project;","options":[{"id":"leftover_yes","label":"Ναι, επειδή πρόκειται για υπολειπόμενο υλικό."},{"id":"anonymized_yes","label":"Ναι, εάν αφαιρεθούν όλοι οι αριθμοί περιστατικών."},{"id":"governance_first","label":"Όχι· πρώτα πρέπει να διευκρινιστούν η ηθική/συγκατάθεση, η προστασία δεδομένων, η αποδέσμευση υλικού και η διαδικασία για τυχαία ευρήματα."},{"id":"dna_extract_first","label":"Ναι, αρκεί αρχικά να γίνεται μόνο εξαγωγή DNA."}],"correct":["governance_first"],"rationale":"Το governance και η προστασία υλικού πρέπει να διευκρινιστούν πριν από μη αναστρέψιμη χρήση δειγμάτων και δεδομένων."},{"id":"eth_prerequisites","type":"multi_select","prompt":"Ποιες προϋποθέσεις πρέπει να έχουν διευκρινιστεί πριν αρχίσει η ανάλυση;","options":[{"id":"ethics","label":"Έγκριση επιτροπής δεοντολογίας/amendment"},{"id":"consent","label":"Έλεγχος συγκατάθεσης/broad consent/opt-out ή της εφαρμοζόμενης βάσης governance"},{"id":"material_release","label":"Αποδέσμευση υλικού από την παθολογία"},{"id":"reserve","label":"Προστασία διαγνωστικού αποθέματος"},{"id":"pseudonym","label":"Σχέδιο ψευδωνυμοποίησης/διαχείρισης κλειδιού"},{"id":"roles","label":"Σχέδιο ρόλων και πρόσβασης"},{"id":"side_findings","label":"Καθορισμένη διαχείριση τυχαίων ευρημάτων/υποψίας βλαστικής προέλευσης"},{"id":"sharing","label":"Σχέδιο data sharing"},{"id":"leftover_note","label":"Μια ένδειξη «υπολειπόμενο υλικό» ως μοναδική έγκριση"}],"correct":["ethics","consent","material_release","reserve","pseudonym","roles","side_findings","sharing"],"rationale":"Το governance περιλαμβάνει ηθική, συγκατάθεση/νομική βάση, προστασία υλικού, προστασία δεδομένων, ρόλους, τυχαία ευρήματα και μεταγενέστερη χρήση δεδομένων."},{"id":"eth_anonymization","type":"single_choice","prompt":"Η πλήρης ανωνυμοποίηση επιλύει αυτόματα τα ζητήματα governance;","options":[{"id":"no","label":"Όχι. Δεν αντικαθιστά την αξιολόγηση υλικού/ηθικής και μπορεί να δυσχεράνει το follow-up ή ελεγχόμενη ενημέρωση."},{"id":"yes","label":"Ναι. Μετά την ανωνυμοποίηση, η συγκατάθεση, η αποδέσμευση υλικού και τα τυχαία ευρήματα δεν είναι πλέον σημαντικά."},{"id":"always_best","label":"Ναι. Η πλήρης ανωνυμοποίηση είναι το προτιμώμενο πρότυπο για κάθε μεταφραστική μελέτη."}],"correct":["no"],"rationale":"Η ανωνυμοποίηση είναι έννοια προστασίας δεδομένων, όχι καθολική γόμα governance."},{"id":"eth_material_guard","type":"single_choice","prompt":"Η αξιολόγηση υλικού δείχνει περιορισμένο διαγνωστικό απόθεμα σε αρκετές μικρές βιοψίες. Ποια είναι η σωστή ενέργεια;","options":[{"id":"exclude_reduce","label":"Αποκλείστε περιπτώσεις ή μειώστε το εύρος της έρευνας και προστατέψτε το διαγνωστικό απόθεμα."},{"id":"use_all","label":"Χρησιμοποιήστε όλες τις περιπτώσεις ώστε το επιστημονικό μέγεθος δείγματος να είναι μέγιστο."},{"id":"split_half","label":"Δεσμεύετε πάντα το μισό υλικό για έρευνα ανεξάρτητα από το διαγνωστικό απόθεμα."}],"correct":["exclude_reduce"],"rationale":"Μια μικρότερη κοόρτη που συμμορφώνεται με governance είναι καλύτερη από μεγαλύτερη κοόρτη εις βάρος μελλοντικής διάγνωσης."}],"decision_task":"Δημιουργήστε ένα concept governance και αποδέσμευσης που καλύπτει ολόκληρο τον κύκλο ζωής του project: έναρξη, χρήση υλικού, κλινικά δεδομένα, ψευδωνυμοποίηση/πρόσβαση, γενετικά τυχαία ευρήματα, δημοσίευση και data sharing.","expected_path":["Θέστε αρχικά το project σε hold.","Ορίστε καθαρά το ερευνητικό ερώτημα/PICO.","Ελέγξτε την κατάσταση ηθικής/συγκατάθεσης.","Πραγματοποιήστε αποδέσμευση υλικού από την παθολογία.","Προστατέψτε το διαγνωστικό απόθεμα.","Ορίστε ψευδωνυμοποίηση και ρόλους/πρόσβαση.","Ορίστε ελάχιστο σύνολο δεδομένων.","Καθιερώστε εκ των προτέρων διαδικασία για τυχαία ευρήματα/υποψία βλαστικής προέλευσης.","Ευθυγραμμίστε το data sharing με το governance.","Μόνο τότε αποδεσμεύστε υλικό και ξεκινήστε ανάλυση."],"acceptable_alternatives":["Περιορίστε την κοόρτη σε περιπτώσεις με σαφή κατάσταση governance και υλικού.","Μειώστε το εύρος της έρευνας.","Εκτελέστε το project ως μικρότερη πιλοτική μελέτη.","Περιορίστε το data sharing εάν το αρχικό πλαίσιο governance δεν το επιτρέπει."],"low_value_traps":[{"label":"Υπολειπόμενο υλικό = ελεύθερα διαθέσιμο","why_bad":"Το υλικό που προέρχεται από ασθενείς παραμένει σχετικό με governance."},{"label":"Η ανωνυμοποίηση λύνει τα πάντα","why_bad":"Τα ζητήματα υλικού, ηθικής και ενημέρωσης παραμένουν."},{"label":"Μέγεθος δείγματος πριν από προστασία υλικού","why_bad":"Η έρευνα δεν πρέπει να εκτοπίζει το διαγνωστικό απόθεμα."},{"label":"Διευκρινίστε τα τυχαία ευρήματα αργότερα","why_bad":"Η διαδικασία πρέπει να υπάρχει πριν εμφανιστεί προβλέψιμο εύρημα."},{"label":"Ελέγξτε το data sharing μόνο κατά τη δημοσίευση","why_bad":"Πολύ αργά εάν τα δεδομένα έχουν ήδη συλλεχθεί σε δομή ακατάλληλη για αυτή τη χρήση."}],"twist":{"title":"Το προβλέψιμο τυχαίο εύρημα γίνεται πραγματικότητα","content":"Το project ξεκινά μετά την ολοκλήρωση του ελέγχου governance. Κατά την tumor-only ανάλυση, σε μία περίπτωση εντοπίζεται δυνητικά παθογόνος συνδυασμός BRCA1 με πιθανή βλαστική σημασία. Η ομάδα ρωτά αμέσως: «Πρέπει να καλέσουμε τώρα την ασθενή;» Η σωστή απάντηση δεν είναι ούτε να αγνοηθεί ούτε να ανακοινωθεί άμεσα. Εφαρμόζεται η διαδικασία για τυχαία ευρήματα/υποψία βλαστικής προέλευσης που είχε οριστεί πριν από την έναρξη του project.","why_critical":"Η αξία του καλού governance δεν φαίνεται στην αίτηση δεοντολογίας, αλλά τη στιγμή που πράγματι προκύπτει μια προβλέψιμη δύσκολη κατάσταση."},"result_packages":[{"id":"optimal","title":"Governance first","class":"optimal","result":"Ηθική, consent/governance, απόθεμα υλικού, προστασία δεδομένων, ρόλοι πρόσβασης, διαδικασία τυχαίων ευρημάτων και data sharing έχουν διευκρινιστεί πριν από την ανάλυση. Προβληματικά blocks προστατεύονται ή αποκλείονται.","feedback":"Πολύ καλή αρχιτεκτονική project."},{"id":"wrong","title":"Start now","class":"wrong","result":"Το υλικό επεξεργάζεται πριν διευκρινιστούν η κατάσταση συγκατάθεσης και το διαγνωστικό απόθεμα.","feedback":"Κρίσιμο σφάλμα governance."},{"id":"incomplete","title":"Anonymize everything","class":"incomplete","result":"Η σύνδεση με το περιστατικό αφαιρείται πλήρως και νωρίς· το follow-up και η ελεγχόμενη ενημέρωση γίνονται προβληματικά, ενώ άλλα ζητήματα governance παραμένουν ανοιχτά.","feedback":"Ένα τεχνικό βήμα προστασίας δεδομένων δεν αντικαθιστά συνολικό concept."},{"id":"material_wrong","title":"Science before material","class":"wrong","result":"Μικρά blocks με διαγνωστική σημασία καταναλώνονται για να μεγιστοποιηθεί το μέγεθος δείγματος.","feedback":"Το ερευνητικό ενδιαφέρον τέθηκε πριν από την προστασία υλικού."}],"followup_logic":[{"trigger":"Περιορισμένο διαγνωστικό απόθεμα","action":"Αποκλείστε την περίπτωση ή μειώστε την κατανάλωση για έρευνα.","consequence":"Μικρότερη αλλά υπεύθυνη κοόρτη."},{"trigger":"Πιθανή υποψία βλαστικής προέλευσης","action":"Εφαρμόστε την προκαθορισμένη διαδικασία τυχαίων ευρημάτων/κλινικής γενετικής.","consequence":"Καμία ad hoc επικοινωνία."},{"trigger":"Εξωτερικός συνεργάτης ζητά ακατέργαστα δεδομένα","action":"Ελέγξτε το πλαίσιο consent/governance/data sharing.","consequence":"Διαβιβάστε μόνο επιτρεπτά δεδομένα ή περιορίστε το sharing."},{"trigger":"Governance μη διευκρινισμένο","action":"Το project παραμένει σε hold.","consequence":"Καμία αποδέσμευση υλικού."}],"debrief_points":["Το governance αποτελεί μέρος του σχεδιασμού μελέτης.","Το υπολειπόμενο υλικό δεν είναι αυτόματα ελεύθερα διαθέσιμο ερευνητικό υλικό.","Το διαγνωστικό απόθεμα έχει προτεραιότητα.","Ψευδωνυμοποίηση, ανωνυμοποίηση και governance δεν είναι το ίδιο πράγμα.","Προβλέψιμα γενετικά τυχαία ευρήματα απαιτούν προκαθορισμένη διαδικασία.","Ο καλός ερευνητικός σχεδιασμός περιλαμβάνει ήδη τον μεταγενέστερο χειρισμό δημοσίευσης και data sharing.","Μια μικρότερη, καλά καθορισμένη κοόρτη μπορεί να είναι επιστημονικά και ηθικά ισχυρότερη από το μέγιστο δυνατό μέγεθος δείγματος."],"instructor_notes":{"model_answer":"Το project μπορεί να ξεκινήσει μόνο αφού διευκρινιστούν η ηθική/συγκατάθεση, η προστασία δεδομένων, η αποδέσμευση υλικού και η διαχείριση τυχαίων ευρημάτων. Το διαγνωστικό απόθεμα προστατεύεται για κάθε περίπτωση. Τα κλινικά δεδομένα ψευδωνυμοποιούνται και επεξεργάζονται με πρόσβαση βάσει ρόλων. Πιθανή υποψία βλαστικής προέλευσης από tumor-only δεδομένα δεν ανακοινώνεται ad hoc αλλά διαχειρίζεται μέσω προκαθορισμένης διαδικασίας. Data sharing γίνεται μόνο εντός του καθορισμένου πλαισίου governance.","scoring_focus":["Governance πριν από την έναρξη του project.","Προστασία υλικού.","Ψευδωνυμοποίηση/πρόσβαση.","Διαδικασία τυχαίων ευρημάτων.","Καμία ad hoc ενημέρωση.","Data sharing προβλεμμένο εκ των προτέρων."],"discussion_questions":["Πότε μια μικρότερη κοόρτη είναι η καλύτερη μελέτη;","Γιατί η πλήρης ανωνυμοποίηση δεν είναι πάντα η πιο κομψή λύση;","Ποιες συνέπειες έχει το tumor-only sequencing ήδη στο στάδιο σχεδιασμού της μελέτης;","Πότε πρέπει να σχεδιαστεί εννοιολογικά το data sharing;"]},"report_additions":{"content_status":"Επιμελημένο Deep Dive στα EL","key_turning_point":"Πιθανή υποψία βλαστικής παραλλαγής BRCA1","core_message":"Το governance πρέπει να προηγείται της έναρξης του project","pattern":"Έναρξη → υλικό → ανάλυση → τυχαίο εύρημα → data sharing"},"is_signature_case":true}},"es":{"MTB_CNS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"MTB_CNS_001_v1_0","title":"Glioblastoma antes de la decisión terapéutica: integrar correctamente IDH, MGMT y metilación","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Patología molecular / neuropatología / MTB","estimated_minutes_deep":"15–18","learning_objectives":["Reconocer la clasificación diagnóstica, la caracterización molecular y los biomarcadores predictivos como niveles diferentes.","Asignar correctamente la función de IDH, la metilación del promotor de MGMT y el clasificador de metilación.","Reconocer que un DNA-NGS amplio no responde automáticamente a todas las preguntas clínicas.","Priorizar un informe integrado según su relevancia clínica y no según la amplitud técnica."],"opening_scene":"Viernes al mediodía en neuropatología. Debe finalizarse el informe de un paciente de 68 años tras resección subtotal de un tumor cerebral primario de alto grado antes de la próxima planificación terapéutica neurooncológica. La histología sugiere claramente un glioblastoma. Sin embargo, neurooncología necesita además una clasificación integrada y, de forma explícita, una valoración del contexto de temozolomida. Hay material suficiente. Por tanto, la pregunta decisiva no es: ¿Cuánto podemos analizar? Sino: ¿Qué prueba responde a qué pregunta clínica?","case_briefing":"Paciente de 68 años con crisis epiléptica y afasia progresiva. La RM muestra una masa con realce periférico en anillo. Tras la resección subtotal, la histología muestra un tumor glial de alto grado con necrosis y proliferación microvascular; Ki-67 aproximadamente 30–40 %. El diagnóstico de trabajo es glioblastoma. Para la integración molecular y la planificación terapéutica deben aclararse especialmente el estado de IDH, la metilación del promotor de MGMT y la clase de metilación.","context_cards":[{"title":"Contexto clínico","content":"Crisis epiléptica, afasia progresiva, resección subtotal; se está valorando radioquimioterapia.","teaching_point":"El informe molecular cumple funciones diagnósticas y terapéuticas diferentes."},{"title":"Histología","content":"Tumor glial de alto grado con necrosis y proliferación microvascular; Ki-67 aprox. 30–40 %.","teaching_point":"La morfología orienta claramente, pero no sustituye la integración molecular."},{"title":"Material","content":"Pieza de resección FFPE, bloque T3, aprox. 80 % de tumor; pueden marcarse áreas tumorales viables; se pueden planificar 14 cortes.","teaching_point":"No hay una escasez aguda de material, pero sigue siendo necesaria una estrategia diagnóstica racional."},{"title":"Solicitud clínica","content":"Deben aclararse la clasificación, el pronóstico y el contexto de temozolomida antes de la planificación terapéutica.","teaching_point":"No todos los marcadores responden a la misma pregunta."}],"pre_results":[{"title":"H&E","content":"Tumor glial de alto grado con necrosis y proliferación microvascular."},{"title":"Ki-67","content":"Alto, aproximadamente 30–40 %."},{"title":"Diagnóstico de trabajo","content":"Glioblastoma probable."},{"title":"QC / niveles pendientes","content":"Alto contenido tumoral; los análisis basados en DNA y los análisis epigenéticos son técnicamente evaluables. Quedan pendientes el estado de IDH, la metilación del promotor de MGMT y la integración molecular."}],"material_or_resource_constraints":["El informe debe finalizarse antes de la próxima planificación terapéutica.","La cantidad de tejido disponible permite varias pruebas, pero no justifica una batería máxima de pruebas sin relevancia diagnóstica.","La secuenciación basada en DNA y los análisis de metilación responden a preguntas diferentes.","Un informe técnicamente muy amplio puede seguir siendo clínicamente incompleto."],"reasoning_gate_upgrade":[{"id":"cns_question_levels","type":"multi_select","prompt":"¿Qué niveles debe diferenciar en este caso?","options":[{"id":"classification","label":"Clasificación histológica/molecular"},{"id":"tmz_prediction","label":"Contexto predictivo de temozolomida"},{"id":"molecular_characterization","label":"Caracterización molecular adicional"},{"id":"max_gene_count","label":"El mayor número posible de genes analizados"},{"id":"tmb_msi_primary","label":"TMB/MSI como eje principal de decisión"}],"correct":["classification","tmz_prediction","molecular_characterization"],"rationale":"El valor diagnóstico depende de la pregunta clínica. Analizar el mayor número posible de genes no constituye por sí mismo un nivel diagnóstico."},{"id":"cns_marker_roles","type":"multi_select","prompt":"¿Qué asignaciones son correctas?","options":[{"id":"idh_classification","label":"IDH → clasificación molecular"},{"id":"mgmt_prediction","label":"Metilación del promotor de MGMT → contexto terapéutico epigenético/predictivo"},{"id":"classifier_integration","label":"Clasificador de metilación → nivel adicional de clasificación/integración diagnóstica"},{"id":"ngs_characterization","label":"NGS de glioma → caracterización molecular adicional"},{"id":"mgmt_driver","label":"MGMT → mutación driver clásica en DNA-NGS"}],"correct":["idh_classification","mgmt_prediction","classifier_integration","ngs_characterization"],"rationale":"IDH, MGMT y el clasificador de metilación responden a preguntas distintas; MGMT no es aquí una mutación driver clásica."},{"id":"cns_strategy","type":"single_choice","prompt":"¿Qué estrategia diagnóstica responde de forma más completa a la pregunta clínica?","options":[{"id":"integrated","label":"Aclarar el estado de IDH, estudiar por separado la metilación del promotor de MGMT e integrar de forma adecuada el clasificador de metilación/NGS de glioma."},{"id":"dna_only","label":"Realizar únicamente un DNA-NGS amplio y asumir que con ello queda respondida toda la pregunta clínica."},{"id":"tmb_first","label":"Priorizar TMB/MSI porque el tumor es de alto grado."},{"id":"mgmt_mutation","label":"Buscar MGMT como mutación dentro del panel NGS."}],"correct":["integrated"],"rationale":"La amplitud diagnóstica no sustituye una pregunta específica de método. La metilación del promotor de MGMT debe abordarse por separado."}],"decision_task":"Planifique el estudio molecular y formule después para el comité de neurooncología: ¿Qué hallazgos sustentan el diagnóstico integrado, qué hallazgo es relevante para el contexto de temozolomida y qué información diagnóstica no es sustituida por un DNA-NGS aislado?","expected_path":["Utilizar la morfología y el contexto clínico como punto de partida.","Aclarar el estado de IDH.","Planificar la metilación del promotor de MGMT como análisis epigenético separado.","Integrar adecuadamente el clasificador de metilación en la clasificación/integración diagnóstica.","Utilizar el NGS de glioma como nivel molecular adicional.","Ponderar los resultados según su función clínica.","No describir MGMT como una mutación driver."],"acceptable_alternatives":["El estado de IDH puede aclararse mediante IHC/secuenciación dirigida o mediante un estudio NGS de glioma adecuado.","Un panel molecular más amplio puede aportar información adicional relevante, siempre que quede claro qué preguntas clínicas no responde.","El alcance diagnóstico puede variar en función de los hallazgos previos y del flujo de trabajo institucional."],"low_value_traps":[{"label":"Panel amplio = diagnóstico completo","why_bad":"La amplitud técnica no indica si se ha cubierto la pregunta clínica concreta."},{"label":"MGMT como mutación","why_bad":"Confunde niveles diagnósticos epigenéticos y genéticos."},{"label":"TMB/MSI como foco principal","why_bad":"No es un eje principal de decisión para la pregunta actual de IDH/MGMT/temozolomida."},{"label":"Limitarse a enumerar marcadores","why_bad":"Un informe integrado debe explicar qué información es diagnóstica o predictivamente relevante."}],"twist":{"title":"Un panel grande, y aun así falta la información decisiva","content":"La secuenciación muestra IDH1/2 de tipo salvaje, una mutación del promotor de TERT y una señal de amplificación de EGFR; los hallazgos moleculares encajan con el contexto de glioblastoma. En el comité alguien dice: Entonces ya hemos terminado. Sin embargo, MGMT no se ha estudiado. Solo la prueba dirigida posterior demuestra un promotor de MGMT metilado; el clasificador de metilación apoya la clase glioblastoma, IDH de tipo salvaje, con una puntuación alta del clasificador.","why_critical":"Un resultado diagnósticamente amplio puede dejar sin responder una pregunta terapéutica concreta. El nivel epigenético de MGMT no es sustituido por el DNA-NGS convencional."},"result_packages":[{"id":"optimal","title":"Informe integrado","class":"optimal","result":"IDH de tipo salvaje; promotor de MGMT metilado; la clase de metilación apoya glioblastoma, IDH de tipo salvaje; los hallazgos moleculares adicionales son compatibles con el contexto global.","feedback":"Muy bien. Los distintos métodos se integran según su función diagnóstica."},{"id":"incomplete","title":"Mucha secuenciación, pregunta terapéutica pendiente","class":"incomplete","result":"DNA-NGS amplio, pero sin resultado de metilación del promotor de MGMT.","feedback":"Técnicamente amplio, clínicamente incompleto. La cuestión de temozolomida sigue abierta."},{"id":"wrong","title":"Foco incorrecto","class":"wrong","result":"Pruebas adicionales de TMB/MSI sin integración completa de IDH/MGMT.","feedback":"Las pruebas no abordan la pregunta central del caso."}],"followup_logic":[{"trigger":"Falta MGMT","action":"Añadir un análisis dirigido de metilación de MGMT.","consequence":"La interpretación terapéutica seguirá incompleta hasta entonces."},{"trigger":"MGMT se interpreta como una mutación","action":"Abordar el error conceptual en el debriefing.","consequence":"Penalización clara en razonamiento."},{"trigger":"Integración completa","action":"Formular el informe final de neurooncología/MTB.","consequence":"Ruta Deep Dive completa."}],"debrief_points":["La morfología, la clasificación molecular y los biomarcadores predictivos responden a preguntas distintas.","La metilación del promotor de MGMT constituye un nivel diagnóstico epigenético.","Un panel de secuenciación amplio no equivale automáticamente a un informe clínico completo.","Una buena patología molecular prioriza la información según su relevancia para el diagnóstico y la toma de decisiones."],"instructor_notes":{"model_answer":"La constelación morfológica es compatible con un tumor glial de alto grado. Para el diagnóstico integrado se determina el estado de IDH. La metilación del promotor de MGMT debe evaluarse por separado como marcador predictivo epigenético y no queda sustituida por un DNA-NGS convencional. El clasificador de metilación y el NGS de glioma pueden complementar la integración diagnóstica. Lo decisivo es ponderar funcionalmente los hallazgos individuales.","scoring_focus":["Niveles diagnósticos claramente separados.","IDH correctamente clasificado.","MGMT correctamente clasificado.","Sin sobreinterpretación de la secuenciación amplia.","Comunicación clara para MTB/neurooncología."],"discussion_questions":["¿Cuándo aporta un panel amplio un verdadero valor añadido?","¿Qué significa un diagnóstico completo en este caso?","¿Cómo deberían hacerse visibles lingüísticamente los distintos niveles diagnósticos en el informe?"]},"report_additions":{"content_status":"Deep Dive curado en ES","key_turning_point":"NGS amplio, pero falta MGMT","core_trap":"MGMT no es una mutación driver clásica","pattern":"Morfología → clasificación → predicción → integración"},"is_signature_case":true},"LAB_DOC_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"LAB_DOC_001_v1_0","title":"«PCR como siempre»: analíticamente válido, pero aun así un caso de QM","domain":"LAB","target_course":"QM Basics","deep_dive_priority":"signature","target_role":"Dirección de laboratorio / QM / laboratorio de patología molecular","estimated_minutes_deep":"12–15","learning_objectives":["Evaluar por separado la validez analítica y la conformidad del proceso/documentación.","Reconstruir sistemáticamente los datos primarios disponibles antes de repetir de forma refleja.","Liberar una muestra de paciente con señal débil mediante una decisión basada en riesgo cuando la base analítica se haya reconstruido de forma sólida.","Reconocer que una laguna sistémica relevante de documentación debe tratarse, pese a una reconstrucción exitosa, como desviación/near miss y, en este caso, derivar en una CAPA.","Comprobar la eficacia de una CAPA."],"opening_scene":"Por la mañana comienza la preparación de una auditoría interna en el laboratorio de patología molecular. Se selecciona como muestra un run de qPCR de KRAS. En el cuaderno de laboratorio aparece exactamente una frase: «PCR como siempre. Ha funcionado. Muestra 4 débil». La compañera recuerda el run y dice: «Todo estaba bien. Los controles eran buenos». El resultado de la muestra 4 es clínicamente relevante. La pregunta ya no es solo: ¿La PCR fue técnicamente correcta? Sino: ¿Podemos demostrarlo hoy de forma sólida y qué hacemos si podemos?","case_briefing":"Ensayo rutinario de hotspots de KRAS por qPCR. La anotación del cuaderno de laboratorio no contiene ni una referencia metodológica suficiente ni un audit trail completo. Faltan, entre otros, fecha/hora, operador, versión de SOP, identificadores inequívocos de muestra, kit/lote/caducidad, equipo y run-ID, controles positivo/negativo/NTC, valores Ct/réplicas, ruta de datos brutos y la evaluación profesional documentada de la muestra débil. Sin embargo, los datos brutos y metadatos reales podrían seguir disponibles en el equipo, el LIMS y los sistemas electrónicos.","context_cards":[{"title":"Anotación original","content":"«PCR como siempre. Ha funcionado. Muestra 4 débil».","teaching_point":"La plausibilidad no equivale a trazabilidad."},{"title":"Ensayo","content":"Ensayo rutinario de hotspots de KRAS por qPCR.","teaching_point":"La rutina no reduce los requisitos de documentación."},{"title":"Muestra del paciente","content":"La muestra 4 presenta una señal débil.","teaching_point":"Precisamente las señales limítrofes/débiles requieren datos primarios trazables y una evaluación documentada."},{"title":"Conflicto","content":"¿Reconstruir o repetir todo de forma preventiva?","teaching_point":"Un buen QM se basa en el riesgo, no en un maximalismo reflejo."}],"pre_results":[{"title":"Situación documental","content":"La documentación original es insuficiente, pero no hay indicios de un fallo técnico conocido del run."},{"title":"Fuentes disponibles","content":"Siguen disponibles la exportación del equipo, el LIMS y otros metadatos electrónicos."},{"title":"Contexto de material/tiempo","content":"El material restante del paciente es limitado. Una repetición consumiría tiempo y material adicionales."},{"title":"Pregunta abierta","content":"Aún no está claro si puede reconstruirse de forma sólida toda la cadena analítica, incluida la muestra débil."}],"material_or_resource_constraints":["El material del paciente no está disponible de forma ilimitada.","Cada repetición consume material y genera costes de tiempo y recursos.","Por tanto, una repetición innecesaria no es automáticamente más segura.","Por otro lado, una liberación sin una reconstrucción sólida no sería aceptable.","Las medidas de QM deben abordar la causa real y no limitarse a eliminar síntomas."],"reasoning_gate_upgrade":[{"id":"labdoc_primary_problem","type":"single_choice","prompt":"¿Cuál es el problema principal?","options":[{"id":"auto_invalid","label":"El run es automáticamente inválido desde el punto de vista analítico."},{"id":"traceability","label":"La trazabilidad y la base documentada para la evaluación son insuficientes."},{"id":"weak_never_release","label":"Una muestra débil nunca puede liberarse por principio."},{"id":"routine_less_docs","label":"La PCR rutinaria requiere menos documentación."}],"correct":["traceability"],"rationale":"Una deficiencia documental no implica automáticamente un fallo analítico. Primero debe comprobarse si la validez analítica puede reconstruirse a partir de fuentes primarias."},{"id":"labdoc_reconstruct","type":"multi_select","prompt":"¿Qué información debe utilizarse para una reconstrucción apta para auditoría?","options":[{"id":"who_when","label":"Operador y momento de realización"},{"id":"sop","label":"Versión de SOP"},{"id":"lot","label":"Lote de kit/reactivos y fecha de caducidad"},{"id":"sample_id","label":"Identidad inequívoca de la muestra"},{"id":"run_id","label":"Equipo y run-ID"},{"id":"controls","label":"Controles positivo/negativo/NTC"},{"id":"ct_replicates","label":"Valores Ct y réplicas"},{"id":"rawdata","label":"Ruta de datos brutos/datos primarios"},{"id":"sample4_review","label":"Evaluación profesional de la muestra 4"},{"id":"memory_only","label":"El recuerdo verbal de la compañera como única evidencia"}],"correct":["who_when","sop","lot","sample_id","run_id","controls","ct_replicates","rawdata","sample4_review"],"rationale":"La reconstrucción debe basarse en fuentes y ser apta para auditoría; el recuerdo por sí solo no es suficiente."},{"id":"labdoc_release_or_repeat","type":"single_choice","prompt":"La reconstrucción muestra una asignación inequívoca de muestras, datos válidos de SOP/lote, controles válidos, datos brutos completos y una señal débil reproducible en la muestra 4. ¿Qué es correcto ahora?","options":[{"id":"release_after_review","label":"Documentar de forma transparente la reconstrucción y la reevaluación profesional; liberar la muestra 4; evitar una repetición innecesaria."},{"id":"repeat_all","label":"Repetir el run completo independientemente de los datos primarios disponibles."},{"id":"weak_hold","label":"No liberar la muestra 4 porque una señal débil es por definición poco fiable."},{"id":"release_no_docs","label":"Liberar simplemente el resultado y dejar sin cambios la documentación original."}],"correct":["release_after_review"],"rationale":"La validez analítica es trazable a partir de los datos primarios. Repetir no es un fin en sí mismo y consumiría innecesariamente material, tiempo y recursos."},{"id":"labdoc_capa","type":"single_choice","prompt":"¿Está cerrado el caso tras reconstruir con éxito el resultado?","options":[{"id":"done_no_harm","label":"Sí. No se ha producido daño al paciente."},{"id":"near_miss_capa","label":"No. La laguna documental relevante se evalúa según riesgo como desviación/near miss; el problema sistémico identificado aquí se aborda mediante CAPA y comprobación de eficacia."},{"id":"verbal_reminder","label":"Basta con recordar informalmente al equipo que documente mejor."},{"id":"rewrite_old","label":"Se elimina la entrada antigua del cuaderno de laboratorio y se vuelve a escribir."}],"correct":["near_miss_capa"],"rationale":"La reconstrucción exitosa evita un error, pero no elimina la debilidad sistémica que casi lo hizo posible."}],"decision_task":"Tome dos decisiones separadas: ¿Puede liberarse el resultado concreto del paciente tras la reconstrucción? ¿Qué consecuencia de QM deriva del proceso original insuficiente?","expected_path":["Reconocer la deficiencia documental.","No descartar automáticamente el resultado.","Reconstruir sistemáticamente datos primarios y metadatos.","Confirmar la validez del run mediante los controles.","Reevaluar profesionalmente la muestra débil usando Ct/réplicas y datos brutos.","Liberar el resultado de forma transparente.","Registrar la deficiencia documental original como desviación/near miss.","Analizar la causa raíz.","Implementar CAPA.","Comprobar la eficacia mediante documentación posterior."],"acceptable_alternatives":["Una repetición es justificable si elementos decisivos como identidad de muestra, controles, datos primarios o evaluación profesional no pueden reconstruirse de forma sólida.","La repetición deriva del riesgo, no de la mera existencia de una desviación."],"low_value_traps":[{"label":"Repetir siempre que exista una desviación","why_bad":"Puede consumir innecesariamente material del paciente, tiempo y recursos y no resuelve la causa del proceso."},{"label":"No ha pasado nada, así que no hace falta CAPA","why_bad":"Persisten el near miss y la debilidad sistémica del proceso."},{"label":"Añadir únicamente el valor Ct después","why_bad":"La trazabilidad sigue siendo incompleta."},{"label":"Solo formación","why_bad":"Una formación sin relación con la causa raíz y sin comprobación de eficacia no es una CAPA sólida."},{"label":"Recuerdo verbal","why_bad":"No es un sustituto de los datos primarios apto para auditoría."}],"twist":{"title":"La muestra débil sí puede liberarse","content":"La reconstrucción muestra que el run fue técnicamente válido, los controles fueron correctos y la muestra 4 presenta una señal débil reproducible en los datos primarios. Tras una reevaluación profesional documentada, la muestra puede liberarse; no es necesario repetir todo. Sin embargo, una revisión por muestreo de otras anotaciones del cuaderno de laboratorio revela varias formulaciones abreviadas similares: de un caso aislado se pasa a una debilidad documental sistémica.","why_critical":"La validez analítica y la conformidad del proceso son preguntas diferentes. El resultado concreto puede rescatarse, mientras que el near miss sigue exigiendo una gestión de desviación/CAPA basada en riesgo."},"result_packages":[{"id":"optimal","title":"Liberación basada en riesgo + CAPA","class":"optimal","result":"Run y muestra 4 completamente reconstruidos, liberación profesional, desviación documentada, causa raíz abordada y CAPA establecida con comprobación de eficacia.","feedback":"Muy bien. La validez analítica y la conformidad del proceso se evaluaron por separado y según riesgo."},{"id":"incomplete","title":"Reflejo de seguridad: repetir todo","class":"incomplete","result":"Se repite el run completo aunque estaban disponibles todos los datos primarios relevantes.","feedback":"Repetir no es un fin en sí mismo. No se consideraron el consumo de material y recursos; la causa del proceso sigue sin resolverse."},{"id":"release_no_capa","title":"Resultado correcto, QM incorrecto","class":"incomplete","result":"La muestra se libera correctamente, pero después se considera resuelto el problema documental.","feedback":"El resultado concreto se ha rescatado, pero la causa sistémica no."},{"id":"wrong","title":"Liberación basada solo en el recuerdo","class":"wrong","result":"Liberación únicamente por rutina y memoria.","feedback":"No es apto para auditoría ni sólido."}],"followup_logic":[{"trigger":"Los datos primarios no pueden reconstruirse por completo","action":"Mantener en hold y realizar una repetición dirigida y/o aclaración adicional.","consequence":"No liberar sin una base sólida."},{"trigger":"Reconstrucción completa más controles válidos","action":"Realizar y documentar una reevaluación profesional.","consequence":"La liberación puede ser posible."},{"trigger":"Laguna documental sistémica","action":"Realizar análisis de causa raíz y CAPA.","consequence":"Adaptar plantilla/proceso/formación según la causa identificada."},{"trigger":"CAPA implementada","action":"Revisar una muestra de la documentación qPCR posterior.","consequence":"Comprobación de eficacia en lugar de simple cierre de la medida."}],"debrief_points":["La validez analítica y la conformidad del proceso son preguntas distintas.","Una desviación no invalida automáticamente un resultado.","Una repetición debe justificarse en función del riesgo.","El material limitado, el tiempo y los recursos forman parte de la valoración del riesgo.","Un near miss es especialmente instructivo cuando se detecta la debilidad antes de que se produzca un daño.","La CAPA termina con una comprobación de eficacia, no con «personal formado»."],"instructor_notes":{"model_answer":"Primero se reconstruye la trazabilidad a partir de LIMS, exportación del equipo, SOP, lote, controles y datos brutos. Si la identidad de la muestra, la validez del run y la positividad débil de la muestra 4 pueden demostrarse de forma sólida, el resultado puede liberarse tras una reevaluación documentada. No es necesaria una repetición general. La deficiencia documental original se gestiona, no obstante, como una desviación relevante con carácter de near miss. Si se identifica un problema sistémico, siguen un análisis de causa raíz, una CAPA adecuada y una comprobación de eficacia.","scoring_focus":["Reconstrucción antes que repetición.","Datos primarios en lugar de recuerdos.","Liberación correcta de la muestra débil.","Desviación/near miss no ignorado.","CAPA vinculada a la causa raíz.","Comprobación de eficacia."],"discussion_questions":["¿Cuándo es realmente necesaria una repetición?","¿Puede un resultado ser válido aunque el proceso haya sido defectuoso?","¿Dónde está el límite entre correction y CAPA?","¿Por qué más seguridad no significa automáticamente más repeticiones?"]},"report_additions":{"content_status":"Deep Dive curado en ES","key_turning_point":"Muestra débil liberable tras reconstrucción","core_message":"Validez analítica ≠ conformidad del proceso","pattern":"Reconstrucción → evaluación de riesgo → liberación → CAPA → comprobación de eficacia"},"is_signature_case":true},"RES_OMICS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_OMICS_001_v1_0","title":"200 DEGs, ¿un biomarcador? De la señal de RNA-seq a una hipótesis robusta de resistencia","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Investigación traslacional / patología molecular / bioinformática","estimated_minutes_deep":"18–22","learning_objectives":["Traducir listas de DEGs en programas biológicos en lugar de historias de un solo gen.","Operacionalizar una observación ómica como hipótesis comprobable y PICO.","Distinguir discovery, validación técnica, validación morfológica y replicación externa.","No sobreinterpretar resultados exploratorios como un biomarcador ya establecido.","Priorizar la robustez de una firma frente a un gen individual atractivo."],"opening_scene":"Lunes por la mañana en la reunión de investigación traslacional. Una doctoranda ha terminado su primer análisis de RNA-seq: 30 tumores tratados con ICI, 15 respondedores y 15 no respondedores. En su diapositiva aparece: «200 DEGs significativos». Debajo, una tabla ordenada. Pregunta: «¿Qué gen elijo ahora como biomarcador?». El p-valor más bajo parece espectacular. Pero justo aquí empieza el verdadero trabajo científico.","case_briefing":"RNA-seq de 30 tumores tratados con ICI: 15 respondedores y 15 no respondedores. En los no respondedores están aumentados, entre otros, TGFB1, COL1A1, CXCL12, ACTA2, FN1 y otros genes de ECM; HLA-A, B2M, TAP1, CXCL9 y GZMB están disminuidos. El análisis de pathways muestra TGFβ/ECM alto y presentación de antígeno/activación de células T baja. Clínicamente, los tumores ricos en estroma se asocian con peor respuesta a ICI.","context_cards":[{"title":"Cohorte de discovery","content":"30 tumores tratados con ICI, 15 respondedores frente a 15 no respondedores.","teaching_point":"Las cohortes pequeñas de discovery son adecuadas para generar hipótesis, no automáticamente para afirmar un biomarcador."},{"title":"Señal de RNA-seq","content":"200 genes diferencialmente expresados.","teaching_point":"Una lista de genes todavía no es una explicación biológica."},{"title":"Patrón biológico","content":"TGFβ/ECM alto, presentación de antígeno/activación de células T baja.","teaching_point":"Los programas coordinados pueden ser más informativos que un solo gen."},{"title":"Objetivo traslacional","content":"Desarrollar un mecanismo y una firma clínicamente comprobable.","teaching_point":"Pasar de ómica a traslación requiere varios niveles de validación."}],"pre_results":[{"title":"No respondedores – aumentados","content":"TGFB1, COL1A1, CXCL12, ACTA2, FN1 y otros genes de ECM."},{"title":"No respondedores – disminuidos","content":"HLA-A, B2M, TAP1, CXCL9 y GZMB."},{"title":"Enriquecimiento de pathways","content":"TGFβ/ECM alto; presentación de antígeno/activación de células T baja."},{"title":"Aún no decidido","content":"El gen individual más fuerte, una firma y un programa biológico no son lo mismo. La interpretación debe priorizarse de forma activa."}],"material_or_resource_constraints":["Cohorte de discovery: n = 30.","Deben tenerse en cuenta las pruebas múltiples/FDR.","Deben registrarse confusores clínicos como tratamiento, entidad tumoral, ECOG y contenido tumoral.","El presupuesto permite una validación técnica y morfológica dirigida, no multi-ómica ilimitada.","Es necesaria una validación independiente antes de realizar una afirmación de biomarcador."],"reasoning_gate_upgrade":[{"id":"omics_from_degs","type":"single_choice","prompt":"¿Cómo se convierten 200 DEGs en una pregunta de investigación robusta?","options":[{"id":"lowest_p","label":"Seleccionar el gen con el p-valor más bajo."},{"id":"all_genes","label":"Informar los 200 genes como si tuvieran la misma importancia."},{"id":"programs","label":"Identificar programas biológicos coordinados y pathways compartidos."},{"id":"expected_only","label":"Conservar únicamente los genes que encajan con la historia esperada."}],"correct":["programs"],"rationale":"El patrón estromal/inmunológico compartido proporciona una hipótesis más robusta que un gen individual aislado."},{"id":"omics_hypothesis","type":"single_choice","prompt":"¿Qué hipótesis encaja mejor con los datos disponibles?","options":[{"id":"stroma_immune","label":"La no respuesta primaria a ICI se asocia con un microambiente tumoral dominado por estroma/TGFβ y, al mismo tiempo, pobre en antígenos."},{"id":"tgfb1_marker","label":"TGFB1 es el nuevo biomarcador predictivo."},{"id":"all_degs_explain","label":"Los 200 DEGs ya explican por completo la resistencia a ICI."},{"id":"one_resistance_gene","label":"Todos los no respondedores tienen el mismo gen de resistencia."}],"correct":["stroma_immune"],"rationale":"La hipótesis integra varios programas de expresión coordinados y sigue siendo comprobable sin sobreinterpretar un hit individual exploratorio."},{"id":"omics_pico","type":"multi_select","prompt":"¿Qué elementos forman parte de una operacionalización limpia de la hipótesis?","options":[{"id":"population","label":"Población: tumores tratados con ICI"},{"id":"exposure","label":"Exposición/firma: firma CAF/TGFβ alta"},{"id":"comparison","label":"Comparación: firma baja"},{"id":"outcome","label":"Outcome: respuesta/PFS"},{"id":"score_cutoff","label":"Definir la estrategia de score/cutoff antes de la validación"},{"id":"confounders","label":"Definir confusores relevantes y el plan de análisis"},{"id":"posthoc_cutoff","label":"Fijar el cutoff solo después de ver el resultado de validación más favorable"}],"correct":["population","exposure","comparison","outcome","score_cutoff","confounders"],"rationale":"La hipótesis, el PICO, el score/cutoff y el plan de análisis deben operacionalizarse antes de la validación."},{"id":"omics_validation","type":"multi_select","prompt":"¿Qué pasos de validación son sólidos para el desarrollo traslacional?","options":[{"id":"targeted","label":"RNA dirigido/qPCR/NanoString"},{"id":"external","label":"Cohorte ICI independiente"},{"id":"morphology","label":"αSMA/FAP/CD8/HLA-I/B2M como puente morfológico"},{"id":"fdr","label":"Informar FDR y pruebas múltiples de forma transparente"},{"id":"heatmap_only","label":"Volver a dibujar el heatmap"},{"id":"single_wb","label":"Confirmar solo el gen individual más fuerte mediante Western blot"}],"correct":["targeted","external","morphology","fdr"],"rationale":"La validación técnica, morfológica e independiente se complementan; una mera visualización o un único ensayo de confirmación no bastan para una hipótesis de firma."}],"decision_task":"Desarrolle a partir del análisis exploratorio de RNA-seq una estrategia traslacional sólida: hipótesis biológica, PICO, concepto de firma/análisis, validación técnica, puente morfológico, validación externa y límite de una afirmación de biomarcador permisible.","expected_path":["No tratar la lista de DEGs como producto final.","Priorizar el nivel de pathway/red.","Formular un patrón dominado por estroma/TGFβ y pobre en antígenos.","Definir hipótesis y PICO.","Operacionalizar la firma.","Tener en cuenta FDR y confusores.","Realizar una validación técnica dirigida.","Conectar morfológicamente con marcadores de TME.","Utilizar una cohorte independiente.","Solo entonces discutir el potencial de biomarcador."],"acceptable_alternatives":["Concluir el estudio expresamente como exploratorio y sin afirmación de biomarcador.","Desarrollar una firma focalizada más pequeña en lugar de un score complejo.","Utilizar expresión dirigida/NanoString en lugar de repetir RNA-seq para la validación técnica.","Añadir validación funcional si la pregunta mecanística es prioritaria."],"low_value_traps":[{"label":"p-valor más bajo = biomarcador","why_bad":"Los genes individuales pueden ser inestables y perder el contexto biológico."},{"label":"Heatmap = validación","why_bad":"La visualización no demuestra reproducibilidad independiente."},{"label":"200 DEGs como resultado","why_bad":"La cantidad de datos no sustituye una hipótesis."},{"label":"Optimizar el cutoff a posteriori","why_bad":"Riesgo de overfitting/HARKing."},{"label":"Eliminar resultados que no encajan","why_bad":"Reporte selectivo."}],"twist":{"title":"El «mejor gen» desaparece, la biología permanece","content":"En una cohorte de validación independiente, el gen individual con el p-valor más bajo en discovery no se reproduce de forma convincente. En cambio, la firma estromal/inmune definida previamente sigue mostrando el mismo patrón coordinado: componente estromal/TGFβ aumentado y componente de presentación de antígeno/células T disminuido. La validación morfológica también respalda la interpretación a nivel de programa.","why_critical":"El hit individual más atractivo de discovery no es necesariamente la señal biológica más robusta. El caso separa gen individual, firma, mecanismo y biomarcador validado."},"result_packages":[{"id":"optimal","title":"Hipótesis de firma validada","class":"optimal","result":"Hipótesis basada en pathways, firma predefinida, validación técnica, puente morfológico y cohorte independiente muestran un patrón consistente.","feedback":"Muy buen desarrollo traslacional. Ahora puede discutirse con cautela el potencial como biomarcador."},{"id":"incomplete","title":"Colapso del gen individual","class":"incomplete","result":"El gen individual más fuerte de discovery no se reproduce, pero la firma global se mantiene consistente.","feedback":"No supone el fracaso del proyecto si la hipótesis biológica se apoya de forma independiente."},{"id":"heatmap_story","title":"Heatmap bonito, sin validación","class":"incomplete","result":"Cluster exploratorio sin replicación independiente.","feedback":"Interesante, pero no un biomarcador sólido."},{"id":"wrong","title":"Overclaim","class":"wrong","result":"La firma de discovery se describe directamente como biomarcador predictivo.","feedback":"La interpretación excede la fuerza de evidencia de los datos."}],"followup_logic":[{"trigger":"Solo se prioriza un gen individual","action":"Reintegrar el análisis de pathways/redes en el razonamiento.","consequence":"Reasoning cap por interpretación monomarcador."},{"trigger":"Sin validación independiente","action":"Etiquetar el resultado como exploratorio.","consequence":"Sin afirmación de biomarcador."},{"trigger":"La firma se replica","action":"Evaluar la traslación morfológica y clínica.","consequence":"Ruta óptima del Deep Dive."}],"debrief_points":["Una lista de DEGs todavía no es un modelo biológico.","La información de pathways y firmas puede ser más robusta que un único gen de discovery.","La validación técnica, morfológica y externa responde a preguntas distintas.","Discovery y validation deben mantenerse separadas.","La falta de replicación de un hit individual puede mejorar una hipótesis en lugar de destruir el proyecto.","Un biomarcador es el resultado de una cadena de validación, no de un heatmap bonito."],"instructor_notes":{"model_answer":"Los datos se interpretan primero a nivel de pathways/redes. El patrón coordinado TGFβ/ECM alto y presentación de antígeno baja se formula como hipótesis exploratoria de resistencia. A continuación se operacionalizan población, firma, comparación y outcome. La firma se valida técnica y morfológicamente y en una cohorte independiente. Los genes individuales y los cutoffs no se sobreinterpretan post hoc como biomarcadores ya establecidos.","scoring_focus":["Pathway antes que gen individual.","Hipótesis/PICO claros.","FDR/confusores considerados.","Discovery frente a validation separados.","Puente morfológico.","Afirmación de biomarcador limitada adecuadamente."],"discussion_questions":["¿Cuándo es superior una firma a un marcador individual?","¿Qué significa realmente una validación independiente?","¿Cómo puede ser científicamente valioso un resultado negativo de validación?","¿Cuándo puede una asociación convertirse en un proyecto de biomarcador?"]},"report_additions":{"content_status":"Deep Dive curado en ES","key_turning_point":"El mejor hit individual no se replica","core_message":"DEG → pathway → hipótesis → firma → validación","pattern":"No confundir discovery con demostración de biomarcador"},"is_signature_case":true},"RES_ETH_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_ETH_001_v1_0","title":"120 bloques de archivo y sin consentimiento claro: ¿puede comenzar el proyecto?","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Dirección de proyecto traslacional / patología / QM de investigación","estimated_minutes_deep":"18–22","learning_objectives":["Entender la governance como requisito previo del trabajo científico y no como una formalidad posterior.","Planificar por separado ética/consentimiento, protección del material, protección de datos y gestión de hallazgos incidentales.","Reconocer por qué el material remanente y la anonimización no constituyen autorizaciones generales.","Planificar una decisión de investigación de forma que queden cubiertas desde el inicio posibles situaciones posteriores de sospecha germinal y data sharing."],"opening_scene":"Un grupo de investigación presenta un nuevo proyecto: se quieren estudiar 120 bloques tumorales FFPE archivados con un panel ampliado de DNA/RNA para identificar nuevos marcadores de resistencia. El ensayo, la bioinformática y el presupuesto están disponibles. La dirección del proyecto dice: «Solo es material remanente. Podemos empezar la semana que viene». Sin embargo, los bloques proceden de años diferentes, la situación de consentimiento es heterogénea y en algunos bloques pequeños no está clara la reserva diagnóstica restante. Además, el panel tumor-only previsto puede generar indicios de variantes potencialmente relevantes para línea germinal. Por tanto, la primera decisión debe tomarse antes incluso de cortar una muestra.","case_briefing":"Objetivo del proyecto: identificar nuevos marcadores moleculares de resistencia terapéutica en una cohorte tumoral retrospectiva. Se prevén 120 bloques FFPE rutinarios, un panel ampliado de DNA/RNA, vinculación con datos clínicos y follow-up, publicación y, en su caso, validación externa/data sharing. La situación de consentimiento/governance es heterogénea, la reserva de tejido es limitada en algunos casos y todavía falta un proceso definido para hallazgos incidentales/sospecha germinal.","context_cards":[{"title":"Material","content":"FFPE rutinario, en parte bloques pequeños; la reserva diagnóstica no está garantizada en todos los casos.","teaching_point":"La investigación no debe poner en riesgo la atención futura del paciente."},{"title":"Consentimiento","content":"Años de archivo diferentes y situación heterogénea de consent/governance.","teaching_point":"Archivado no significa automáticamente disponible libremente."},{"title":"Datos","content":"Se quieren vincular datos clínicos y follow-up.","teaching_point":"La protección de datos y el acceso forman parte del diseño del estudio."},{"title":"Genética","content":"El análisis tumor-only puede generar sospecha de un hallazgo germinal.","teaching_point":"Las vías de comunicación deben estar definidas antes del análisis."},{"title":"Data sharing","content":"Se prevén validación externa y publicación.","teaching_point":"El uso posterior de los datos debe estar cubierto por el marco de governance."}],"pre_results":[{"title":"Cohorte","content":"120 casos potenciales procedentes de diferentes años."},{"title":"Governance","content":"No existe una situación uniforme de consentimiento; falta la liberación final del material."},{"title":"Plan de datos","content":"Los datos clínicos se completarán retrospectivamente; la validación externa se plantea como opción posterior."},{"title":"Hallazgos incidentales previsibles","content":"El panel tumor-only puede identificar variantes potencialmente relevantes para línea germinal; debe existir un proceso regulado antes de iniciar el proyecto."}],"material_or_resource_constraints":["La reserva diagnóstica restante tiene prioridad sobre el consumo para investigación.","No es obligatorio incluir todos los casos en la cohorte final.","El follow-up y la capacidad de realizar una comunicación regulada pueden entrar en conflicto con una anonimización completa.","El alcance de los datos y el acceso deben limitarse a lo necesario.","Las decisiones de governance deben tomarse antes de procesar de forma irreversible material y datos."],"reasoning_gate_upgrade":[{"id":"eth_start","type":"single_choice","prompt":"¿Puede comenzar el proyecto inmediatamente?","options":[{"id":"leftover_yes","label":"Sí, porque se trata de material remanente."},{"id":"anonymized_yes","label":"Sí, si se eliminan todos los números de caso."},{"id":"governance_first","label":"No; primero deben aclararse la situación ética/de consentimiento, la protección de datos, la liberación del material y el proceso de hallazgos incidentales."},{"id":"dna_extract_first","label":"Sí, siempre que inicialmente solo se extraiga DNA."}],"correct":["governance_first"],"rationale":"La governance y la protección del material deben aclararse antes de cualquier uso irreversible de muestras y datos."},{"id":"eth_prerequisites","type":"multi_select","prompt":"¿Qué requisitos previos deben estar aclarados antes de iniciar los análisis?","options":[{"id":"ethics","label":"Dictamen ético/enmienda"},{"id":"consent","label":"Revisar consentimiento/broad consent/opt-out o la base de governance aplicable"},{"id":"material_release","label":"Liberación del material por patología"},{"id":"reserve","label":"Protección de la reserva diagnóstica"},{"id":"pseudonym","label":"Concepto de pseudonimización/gestión de la clave"},{"id":"roles","label":"Concepto de roles y acceso"},{"id":"side_findings","label":"Gestión definida de hallazgos incidentales/sospecha germinal"},{"id":"sharing","label":"Concepto de data sharing"},{"id":"leftover_note","label":"Una nota de «material remanente» como única autorización"}],"correct":["ethics","consent","material_release","reserve","pseudonym","roles","side_findings","sharing"],"rationale":"La governance incluye ética, consentimiento/base jurídica, protección del material, protección de datos, roles, hallazgos incidentales y uso posterior de los datos."},{"id":"eth_anonymization","type":"single_choice","prompt":"¿La anonimización completa resuelve automáticamente las cuestiones de governance?","options":[{"id":"no","label":"No. No sustituye la revisión ética/del material y puede dificultar el follow-up o una comunicación regulada."},{"id":"yes","label":"Sí. Tras la anonimización, consentimiento, liberación del material y hallazgos incidentales dejan de ser relevantes."},{"id":"always_best","label":"Sí. La anonimización completa es el estándar preferido para cualquier estudio traslacional."}],"correct":["no"],"rationale":"La anonimización es un concepto de protección de datos, no un borrador universal de governance."},{"id":"eth_material_guard","type":"single_choice","prompt":"La revisión del material muestra que varias biopsias pequeñas tienen una reserva diagnóstica escasa. ¿Qué es correcto?","options":[{"id":"exclude_reduce","label":"Excluir casos o reducir el alcance de investigación y proteger la reserva diagnóstica."},{"id":"use_all","label":"Utilizar todos los casos para maximizar el tamaño de muestra científico."},{"id":"split_half","label":"Reservar siempre la mitad del material para investigación, independientemente de la reserva diagnóstica restante."}],"correct":["exclude_reduce"],"rationale":"Una cohorte más pequeña y conforme con la governance es mejor que una cohorte mayor a costa del diagnóstico futuro."}],"decision_task":"Elabore un concepto de governance y liberación que cubra todo el ciclo de vida del proyecto: inicio, uso de material, datos clínicos, pseudonimización/acceso, hallazgos genéticos incidentales, publicación y data sharing.","expected_path":["Poner inicialmente el proyecto en hold.","Definir claramente la pregunta de investigación/PICO.","Revisar la situación ética/de consentimiento.","Realizar la liberación del material por patología.","Proteger la reserva diagnóstica.","Definir pseudonimización y roles/acceso.","Definir un conjunto mínimo de datos.","Establecer por adelantado un proceso para hallazgos incidentales/sospecha germinal.","Alinear el data sharing con la governance.","Solo entonces liberar el material e iniciar el análisis."],"acceptable_alternatives":["Restringir la cohorte a casos con situación clara de governance y material.","Reducir el alcance de investigación.","Realizar el proyecto como estudio piloto más pequeño.","Limitar el data sharing si el marco original de governance no lo permite."],"low_value_traps":[{"label":"Material remanente = libremente disponible","why_bad":"El material derivado de pacientes sigue sujeto a governance."},{"label":"La anonimización lo resuelve todo","why_bad":"Persisten las cuestiones de material, ética y comunicación."},{"label":"Tamaño de muestra antes que protección del material","why_bad":"La investigación no debe desplazar la reserva diagnóstica."},{"label":"Aclarar los hallazgos incidentales más adelante","why_bad":"El proceso debe existir antes de que aparezca un hallazgo previsible."},{"label":"Revisar el data sharing solo al publicar","why_bad":"Demasiado tarde si los datos ya se han recogido en una estructura inadecuada para ese uso."}],"twist":{"title":"El hallazgo incidental previsible se hace realidad","content":"El proyecto se inicia tras completar la revisión de governance. Durante el análisis tumor-only aparece en un caso una constelación potencialmente patogénica de BRCA1 con posible relevancia germinal. El equipo pregunta de inmediato: «¿Tenemos que llamar ahora a la paciente?». La respuesta correcta no es ni ignorarlo ni comunicarlo inmediatamente. Se aplica el proceso de hallazgos incidentales/sospecha germinal definido antes del inicio del proyecto.","why_critical":"El valor de una buena governance no se demuestra en la solicitud al comité ético, sino en el momento en que realmente aparece una situación difícil previsible."},"result_packages":[{"id":"optimal","title":"Governance first","class":"optimal","result":"Ética, consent/governance, reserva de material, protección de datos, roles de acceso, proceso de hallazgos incidentales y data sharing están aclarados antes del análisis. Los bloques problemáticos se protegen o excluyen.","feedback":"Muy buena arquitectura de proyecto."},{"id":"wrong","title":"Start now","class":"wrong","result":"Se procesa material antes de aclarar la situación de consentimiento y la reserva diagnóstica.","feedback":"Error crítico de governance."},{"id":"incomplete","title":"Anonymize everything","class":"incomplete","result":"La vinculación del caso se elimina completamente de forma precoz; el follow-up y la comunicación regulada se vuelven problemáticos mientras siguen abiertas otras cuestiones de governance.","feedback":"Un paso técnico de protección de datos no sustituye un concepto global."},{"id":"material_wrong","title":"Science before material","class":"wrong","result":"Se consumen bloques pequeños con relevancia diagnóstica para maximizar el tamaño de la muestra.","feedback":"El interés científico se antepuso a la protección del material."}],"followup_logic":[{"trigger":"Reserva diagnóstica escasa","action":"Excluir el caso o reducir el consumo para investigación.","consequence":"Cohorte más pequeña, pero responsable."},{"trigger":"Posible sospecha germinal","action":"Aplicar el proceso predefinido de hallazgos incidentales/genética clínica.","consequence":"Sin comunicación ad hoc."},{"trigger":"Un colaborador externo solicita datos brutos","action":"Revisar el marco de consent/governance/data sharing.","consequence":"Compartir solo los datos permitidos o limitar el sharing."},{"trigger":"Governance no aclarada","action":"El proyecto permanece en hold.","consequence":"Sin liberación del material."}],"debrief_points":["La governance forma parte del diseño del estudio.","El material remanente no es automáticamente material de investigación libremente disponible.","La reserva diagnóstica tiene prioridad.","Pseudonimización, anonimización y governance no son lo mismo.","Los hallazgos genéticos incidentales previsibles requieren un proceso previamente definido.","Un buen diseño de investigación incluye ya el manejo posterior de publicación y data sharing.","Una cohorte más pequeña y bien definida puede ser científica y éticamente más sólida que el máximo tamaño muestral posible."],"instructor_notes":{"model_answer":"El proyecto solo puede comenzar después de aclarar la situación ética/de consentimiento, la protección de datos, la liberación del material y la gestión de hallazgos incidentales. Se protege la reserva diagnóstica para cada caso. Los datos clínicos se pseudonimizan y procesan con acceso basado en roles. Una posible sospecha germinal derivada de datos tumor-only no se comunica ad hoc, sino que se gestiona mediante un proceso previamente definido. El data sharing se realiza únicamente dentro del marco de governance establecido.","scoring_focus":["Governance antes del inicio del proyecto.","Protección del material.","Pseudonimización/acceso.","Proceso de hallazgos incidentales.","Sin comunicación ad hoc.","Data sharing previsto desde el inicio."],"discussion_questions":["¿Cuándo es una cohorte más pequeña el mejor estudio?","¿Por qué la anonimización completa no siempre es la solución más elegante?","¿Qué consecuencias tiene la secuenciación tumor-only ya en la fase de planificación del estudio?","¿Cuándo debe planificarse conceptualmente el data sharing?"]},"report_additions":{"content_status":"Deep Dive curado en ES","key_turning_point":"Posible sospecha germinal BRCA1","core_message":"La governance debe preceder al inicio del proyecto","pattern":"Inicio → material → análisis → hallazgo incidental → data sharing"},"is_signature_case":true}},"fr":{"MTB_CNS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"MTB_CNS_001_v1_0","title":"Glioblastome avant décision thérapeutique : intégrer correctement IDH, MGMT et la méthylation","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Pathologie moléculaire / neuropathologie / RCP moléculaire","estimated_minutes_deep":"15–18","learning_objectives":["Reconnaître la classification diagnostique, la caractérisation moléculaire et les biomarqueurs prédictifs comme des niveaux distincts.","Attribuer correctement les rôles fonctionnels d’IDH, de la méthylation du promoteur de MGMT et du classifieur de méthylation.","Reconnaître qu’un DNA-NGS large ne répond pas automatiquement à toutes les questions cliniques.","Prioriser un compte rendu intégré selon sa pertinence clinique plutôt que selon l’étendue technique."],"opening_scene":"Vendredi midi en neuropathologie. Le compte rendu d’un patient de 68 ans après résection subtotale d’une tumeur cérébrale primitive de haut grade doit être finalisé avant la prochaine planification thérapeutique neuro-oncologique. L’histologie est très évocatrice d’un glioblastome. La neuro-oncologie a toutefois également besoin d’une classification intégrée et, explicitement, d’une évaluation du contexte du témozolomide. Le matériel est suffisant. La question décisive n’est donc pas : jusqu’où pouvons-nous tester ? Mais plutôt : quel examen répond à quelle question clinique ?","case_briefing":"Patient de 68 ans présentant une crise épileptique et une aphasie progressive. L’IRM montre une masse à rehaussement annulaire. Après résection subtotale, l’histologie met en évidence une tumeur gliale de haut grade avec nécrose et prolifération microvasculaire ; Ki-67 d’environ 30–40 %. Le diagnostic de travail est un glioblastome. Pour l’intégration moléculaire et la planification thérapeutique, il faut notamment préciser le statut IDH, la méthylation du promoteur de MGMT et la classe de méthylation.","context_cards":[{"title":"Contexte clinique","content":"Crise épileptique, aphasie progressive, résection subtotale ; une radiochimiothérapie est discutée.","teaching_point":"Le compte rendu moléculaire remplit des fonctions diagnostiques et thérapeutiques différentes."},{"title":"Histologie","content":"Tumeur gliale de haut grade avec nécrose et prolifération microvasculaire ; Ki-67 env. 30–40 %.","teaching_point":"La morphologie est fortement orientatrice, mais ne remplace pas l’intégration moléculaire."},{"title":"Matériel","content":"Pièce de résection FFPE, bloc T3, env. 80 % de tumeur ; les zones tumorales viables peuvent être repérées ; 14 coupes peuvent être planifiées.","teaching_point":"Il n’existe pas de pénurie aiguë de matériel, mais une stratégie diagnostique rationnelle reste nécessaire."},{"title":"Demande clinique","content":"La classification, le pronostic et le contexte du témozolomide doivent être précisés avant la planification thérapeutique.","teaching_point":"Tous les marqueurs ne répondent pas à la même question."}],"pre_results":[{"title":"H&E","content":"Tumeur gliale de haut grade avec nécrose et prolifération microvasculaire."},{"title":"Ki-67","content":"Élevé, environ 30–40 %."},{"title":"Diagnostic de travail","content":"Glioblastome probable."},{"title":"QC / niveaux encore ouverts","content":"Forte cellularité tumorale ; les analyses basées sur l’ADN et les analyses épigénétiques sont techniquement interprétables. Le statut IDH, la méthylation du promoteur de MGMT et l’intégration moléculaire restent à préciser."}],"material_or_resource_constraints":["Le compte rendu doit être finalisé avant la prochaine planification thérapeutique.","La quantité de tissu disponible permet plusieurs analyses, mais ne justifie pas une exploration maximale sans pertinence diagnostique.","Le séquençage basé sur l’ADN et les analyses de méthylation répondent à des questions différentes.","Un compte rendu techniquement très étendu peut néanmoins rester cliniquement incomplet."],"reasoning_gate_upgrade":[{"id":"cns_question_levels","type":"multi_select","prompt":"Quels niveaux devez-vous distinguer dans ce cas ?","options":[{"id":"classification","label":"Classification histologique/moléculaire"},{"id":"tmz_prediction","label":"Contexte prédictif du témozolomide"},{"id":"molecular_characterization","label":"Caractérisation moléculaire supplémentaire"},{"id":"max_gene_count","label":"Nombre maximal possible de gènes testés"},{"id":"tmb_msi_primary","label":"TMB/MSI comme axe décisionnel principal"}],"correct":["classification","tmz_prediction","molecular_characterization"],"rationale":"La valeur diagnostique découle de la question clinique. Tester le plus grand nombre possible de gènes ne constitue pas en soi un niveau diagnostique."},{"id":"cns_marker_roles","type":"multi_select","prompt":"Quelles associations sont correctes ?","options":[{"id":"idh_classification","label":"IDH → classification moléculaire"},{"id":"mgmt_prediction","label":"Méthylation du promoteur de MGMT → contexte thérapeutique épigénétique/prédictif"},{"id":"classifier_integration","label":"Classifieur de méthylation → niveau supplémentaire de classification/intégration diagnostique"},{"id":"ngs_characterization","label":"NGS du gliome → caractérisation moléculaire supplémentaire"},{"id":"mgmt_driver","label":"MGMT → mutation driver classique en DNA-NGS"}],"correct":["idh_classification","mgmt_prediction","classifier_integration","ngs_characterization"],"rationale":"IDH, MGMT et le classifieur de méthylation répondent à des questions différentes ; MGMT n’est pas ici une mutation driver classique."},{"id":"cns_strategy","type":"single_choice","prompt":"Quelle stratégie diagnostique répond le plus complètement à la question clinique ?","options":[{"id":"integrated","label":"Préciser le statut IDH, analyser séparément la méthylation du promoteur de MGMT et intégrer de manière pertinente le classifieur de méthylation/le NGS du gliome."},{"id":"dna_only","label":"Réaliser uniquement un DNA-NGS large et considérer que toute la question clinique est ainsi résolue."},{"id":"tmb_first","label":"Prioriser TMB/MSI parce que la tumeur est de haut grade."},{"id":"mgmt_mutation","label":"Rechercher MGMT comme une mutation au sein du panel NGS."}],"correct":["integrated"],"rationale":"L’étendue diagnostique ne remplace pas une question spécifique à la méthode. La méthylation du promoteur de MGMT doit être abordée séparément."}],"decision_task":"Planifiez le bilan moléculaire puis formulez pour la RCP neuro-oncologique : quels résultats soutiennent le diagnostic intégré, quel résultat est pertinent pour le contexte du témozolomide et quelle information diagnostique n’est pas remplacée par le DNA-NGS seul ?","expected_path":["Utiliser la morphologie et le contexte clinique comme point de départ.","Préciser le statut IDH.","Planifier la méthylation du promoteur de MGMT comme analyse épigénétique distincte.","Positionner correctement le classifieur de méthylation dans la classification/l’intégration diagnostique.","Utiliser le NGS du gliome comme niveau moléculaire supplémentaire.","Pondérer les résultats selon leur fonction clinique.","Ne pas décrire MGMT comme une mutation driver."],"acceptable_alternatives":["Le statut IDH peut être déterminé par IHC/séquençage ciblé ou par un NGS du gliome approprié.","Un panel moléculaire plus large peut fournir des informations supplémentaires pertinentes, à condition de préciser quelles questions cliniques il ne résout pas.","L’étendue du bilan peut varier selon les résultats antérieurs et le workflow institutionnel."],"low_value_traps":[{"label":"Panel large = diagnostic complet","why_bad":"L’étendue technique ne dit pas si la question clinique précise a été couverte."},{"label":"MGMT comme mutation","why_bad":"Confond les niveaux diagnostiques épigénétiques et génétiques."},{"label":"TMB/MSI comme axe principal","why_bad":"Ce n’est pas un axe décisionnel principal pour la question actuelle IDH/MGMT/témozolomide."},{"label":"Se contenter d’énumérer les marqueurs","why_bad":"Un compte rendu intégré doit expliquer quelles informations sont pertinentes sur le plan diagnostique ou prédictif."}],"twist":{"title":"Un grand panel – et l’information décisive manque toujours","content":"Le séquençage montre IDH1/2 de type sauvage, une mutation du promoteur de TERT et un signal d’amplification d’EGFR ; les résultats moléculaires sont compatibles avec le contexte de glioblastome. En RCP, quelqu’un dit : alors nous avons terminé. Pourtant, MGMT n’a pas été analysé. Seule l’analyse ciblée complémentaire montre un promoteur de MGMT méthylé ; le classifieur de méthylation soutient la classe glioblastome, IDH de type sauvage, avec un score élevé du classifieur.","why_critical":"Un résultat diagnostiquement très large peut laisser une question thérapeutique précise sans réponse. Le niveau épigénétique de MGMT n’est pas remplacé par le DNA-NGS conventionnel."},"result_packages":[{"id":"optimal","title":"Compte rendu intégré","class":"optimal","result":"IDH de type sauvage ; promoteur de MGMT méthylé ; la classe de méthylation soutient un glioblastome, IDH de type sauvage ; les résultats moléculaires supplémentaires sont compatibles avec le contexte global.","feedback":"Très bien. Les différentes méthodes sont intégrées selon leur fonction diagnostique."},{"id":"incomplete","title":"Beaucoup de séquençage, question thérapeutique non résolue","class":"incomplete","result":"DNA-NGS étendu, mais absence de résultat sur la méthylation du promoteur de MGMT.","feedback":"Techniquement étendu, cliniquement incomplet. La question du témozolomide reste ouverte."},{"id":"wrong","title":"Mauvais axe","class":"wrong","result":"Analyses TMB/MSI supplémentaires sans intégration complète d’IDH/MGMT.","feedback":"Les examens ne répondent pas à la question centrale du cas."}],"followup_logic":[{"trigger":"MGMT manque","action":"Ajouter une analyse ciblée de la méthylation de MGMT.","consequence":"L’interprétation thérapeutique reste incomplète jusque-là."},{"trigger":"MGMT est interprété comme une mutation","action":"Aborder l’erreur conceptuelle dans le débriefing.","consequence":"Pénalité nette de raisonnement."},{"trigger":"Intégration complète","action":"Formuler le compte rendu final de neuro-oncologie/RCP.","consequence":"Parcours Deep Dive complet."}],"debrief_points":["La morphologie, la classification moléculaire et les biomarqueurs prédictifs répondent à des questions différentes.","La méthylation du promoteur de MGMT constitue un niveau diagnostique épigénétique.","Un large panel de séquençage ne constitue pas automatiquement un compte rendu clinique complet.","Une bonne pathologie moléculaire priorise les informations selon leur pertinence pour le diagnostic et la décision."],"instructor_notes":{"model_answer":"La constellation morphologique est compatible avec une tumeur gliale de haut grade. Le statut IDH est déterminé pour le diagnostic intégré. La méthylation du promoteur de MGMT doit être évaluée séparément comme marqueur prédictif épigénétique et n’est pas remplacée par un DNA-NGS conventionnel. Le classifieur de méthylation et le NGS du gliome peuvent compléter l’intégration diagnostique. L’élément décisif est la pondération fonctionnelle des différents résultats.","scoring_focus":["Niveaux diagnostiques clairement séparés.","IDH correctement interprété.","MGMT correctement interprété.","Pas de surinterprétation d’un séquençage large.","Communication claire en RCP/neuro-oncologie."],"discussion_questions":["Quand un panel large apporte-t-il une réelle valeur ajoutée ?","Que signifie un diagnostic complet dans ce cas ?","Comment les différents niveaux diagnostiques doivent-ils être rendus explicites dans la formulation du compte rendu ?"]},"report_additions":{"content_status":"Deep Dive curé en FR","key_turning_point":"NGS large, mais MGMT manque","core_trap":"MGMT n’est pas une mutation driver classique","pattern":"Morphologie → classification → prédiction → intégration"},"is_signature_case":true},"LAB_DOC_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"LAB_DOC_001_v1_0","title":"« PCR comme d’habitude » : analytiquement valide, mais tout de même un cas de QM","domain":"LAB","target_course":"QM Basics","deep_dive_priority":"signature","target_role":"Direction de laboratoire / QM / laboratoire de pathologie moléculaire","estimated_minutes_deep":"12–15","learning_objectives":["Évaluer séparément la validité analytique et la conformité du processus/de la documentation.","Reconstruire systématiquement les données primaires disponibles avant de répéter l’analyse par réflexe.","Libérer une faible positivité d’un échantillon patient sur la base du risque lorsque le fondement analytique a été reconstitué de manière robuste.","Reconnaître qu’une lacune documentaire systémique pertinente doit, malgré une reconstruction réussie, être traitée comme une déviation/near miss et, dans ce cas, conduire à une CAPA.","Vérifier l’efficacité d’une CAPA."],"opening_scene":"Dans la matinée, la préparation d’un audit interne commence au laboratoire de pathologie moléculaire. Un run de qPCR KRAS est choisi comme échantillon d’audit. Le cahier de laboratoire contient exactement une phrase : « PCR comme d’habitude. Ça a marché. Échantillon 4 faible. » La collègue se souvient du run et dit : « Tout était correct. Les contrôles étaient bons. » Le résultat de l’échantillon 4 est cliniquement pertinent. La question n’est désormais plus seulement : la PCR était-elle techniquement correcte ? Mais : pouvons-nous encore le démontrer de manière robuste aujourd’hui – et que faisons-nous si nous le pouvons ?","case_briefing":"Test de routine qPCR des hotspots KRAS. L’entrée du cahier de laboratoire ne contient ni référence méthodologique suffisante ni audit trail complet. Il manque notamment la date/l’heure, l’opérateur, la version de SOP, des identifiants d’échantillons univoques, le kit/lot/date d’expiration, l’appareil et l’ID du run, les contrôles positif/négatif/NTC, les valeurs Ct/réplicats, le chemin des données brutes et l’évaluation professionnelle documentée de l’échantillon faible. Les données brutes et métadonnées réelles peuvent toutefois encore être disponibles dans l’appareil, le LIMS et les systèmes électroniques.","context_cards":[{"title":"Entrée originale","content":"« PCR comme d’habitude. Ça a marché. Échantillon 4 faible. »","teaching_point":"La plausibilité n’est pas la traçabilité."},{"title":"Test","content":"Test de routine qPCR des hotspots KRAS.","teaching_point":"La routine ne réduit pas les exigences de documentation."},{"title":"Échantillon patient","content":"L’échantillon 4 présente un signal faible.","teaching_point":"Les signaux limites/faibles nécessitent précisément des données primaires traçables et une évaluation documentée."},{"title":"Conflit","content":"Reconstruire ou tout répéter par précaution ?","teaching_point":"Un bon QM est fondé sur le risque, pas sur un maximalisme réflexe."}],"pre_results":[{"title":"État de la documentation","content":"La documentation initiale est insuffisante, mais rien n’indique un échec technique connu du run."},{"title":"Sources disponibles","content":"L’export de l’appareil, le LIMS et d’autres métadonnées électroniques sont encore disponibles."},{"title":"Contexte matériel/temps","content":"Le matériel patient restant est limité. Une répétition consommerait du temps et du matériel supplémentaires."},{"title":"Question ouverte","content":"Il n’est pas encore établi si l’ensemble de la chaîne analytique, y compris l’échantillon faible, peut être reconstitué de manière robuste."}],"material_or_resource_constraints":["Le matériel patient n’est pas disponible de façon illimitée.","Chaque répétition consomme du matériel et mobilise du temps et des ressources.","Une répétition inutile n’est donc pas automatiquement plus sûre.","À l’inverse, une libération sans reconstruction robuste ne serait pas acceptable.","Les mesures de QM doivent traiter la cause réelle et non seulement supprimer les symptômes."],"reasoning_gate_upgrade":[{"id":"labdoc_primary_problem","type":"single_choice","prompt":"Quel est le problème principal ?","options":[{"id":"auto_invalid","label":"Le run est automatiquement invalide sur le plan analytique."},{"id":"traceability","label":"La traçabilité et la base documentée de l’évaluation sont insuffisantes."},{"id":"weak_never_release","label":"Un échantillon faible ne peut jamais être libéré par principe."},{"id":"routine_less_docs","label":"Une PCR de routine nécessite moins de documentation."}],"correct":["traceability"],"rationale":"Une lacune documentaire n’implique pas automatiquement une erreur analytique. Il faut d’abord vérifier si la validité analytique peut être reconstruite à partir des données sources."},{"id":"labdoc_reconstruct","type":"multi_select","prompt":"Quelles informations doivent être utilisées pour une reconstruction compatible avec un audit ?","options":[{"id":"who_when","label":"Opérateur et moment de l’analyse"},{"id":"sop","label":"Version de SOP"},{"id":"lot","label":"Lot du kit/des réactifs et date d’expiration"},{"id":"sample_id","label":"Identité univoque de l’échantillon"},{"id":"run_id","label":"Appareil et ID du run"},{"id":"controls","label":"Contrôles positif/négatif/NTC"},{"id":"ct_replicates","label":"Valeurs Ct et réplicats"},{"id":"rawdata","label":"Chemin des données brutes/données primaires"},{"id":"sample4_review","label":"Évaluation professionnelle de l’échantillon 4"},{"id":"memory_only","label":"Le souvenir oral de la collègue comme seule preuve"}],"correct":["who_when","sop","lot","sample_id","run_id","controls","ct_replicates","rawdata","sample4_review"],"rationale":"La reconstruction doit reposer sur des sources et être audit-compatible ; le souvenir seul ne suffit pas."},{"id":"labdoc_release_or_repeat","type":"single_choice","prompt":"La reconstruction montre une attribution univoque des échantillons, des données SOP/lot valides, des contrôles valides, des données brutes complètes et un signal faible reproductible dans l’échantillon 4. Quelle est maintenant la bonne conduite ?","options":[{"id":"release_after_review","label":"Documenter de manière transparente la reconstruction et la réévaluation professionnelle ; libérer l’échantillon 4 ; éviter une répétition inutile."},{"id":"repeat_all","label":"Répéter l’ensemble du run indépendamment des données primaires disponibles."},{"id":"weak_hold","label":"Ne pas libérer l’échantillon 4 parce qu’un signal faible est par principe non fiable."},{"id":"release_no_docs","label":"Libérer simplement le résultat et laisser la documentation originale inchangée."}],"correct":["release_after_review"],"rationale":"La validité analytique est traçable à partir des données primaires. Répéter n’est pas une fin en soi et consommerait inutilement du matériel, du temps et des ressources."},{"id":"labdoc_capa","type":"single_choice","prompt":"Le cas est-il clos après la reconstruction réussie du résultat ?","options":[{"id":"done_no_harm","label":"Oui. Aucun dommage n’est survenu pour le patient."},{"id":"near_miss_capa","label":"Non. La lacune documentaire pertinente est évaluée selon le risque comme déviation/near miss ; le problème systémique identifié ici est traité par CAPA et contrôle d’efficacité."},{"id":"verbal_reminder","label":"Un rappel informel à l’équipe suffit."},{"id":"rewrite_old","label":"L’ancienne entrée du cahier de laboratoire est supprimée puis réécrite."}],"correct":["near_miss_capa"],"rationale":"La reconstruction réussie évite une erreur mais n’élimine pas la faiblesse systémique qui aurait presque permis qu’elle survienne."}],"decision_task":"Prenez deux décisions séparées : le résultat concret du patient est-il libérable après reconstruction ? Quelle conséquence QM découle du processus initial insuffisant ?","expected_path":["Reconnaître la lacune documentaire.","Ne pas rejeter automatiquement le résultat.","Reconstruire systématiquement les données primaires et les métadonnées.","Confirmer la validité du run à partir des contrôles.","Réévaluer professionnellement l’échantillon faible à partir des Ct/réplicats et des données brutes.","Libérer le résultat de manière transparente.","Enregistrer la lacune documentaire initiale comme déviation/near miss.","Analyser la cause racine.","Mettre en œuvre une CAPA.","Vérifier l’efficacité à l’aide des documentations ultérieures."],"acceptable_alternatives":["Une répétition est justifiable si des éléments déterminants tels que l’identité de l’échantillon, les contrôles, les données primaires ou l’évaluation professionnelle ne peuvent pas être reconstruits de manière robuste.","La répétition découle du risque – pas de la simple existence d’une déviation."],"low_value_traps":[{"label":"Toujours répéter en cas de déviation","why_bad":"Peut consommer inutilement du matériel patient, du temps et des ressources sans résoudre la cause du processus."},{"label":"Il ne s’est rien passé, donc pas de CAPA","why_bad":"Le near miss et la faiblesse systémique du processus persistent."},{"label":"Ajouter uniquement la valeur Ct après coup","why_bad":"La traçabilité reste incomplète."},{"label":"Formation uniquement","why_bad":"Une formation sans lien avec la cause racine et sans contrôle d’efficacité ne constitue pas une CAPA robuste."},{"label":"Souvenir oral","why_bad":"Ne remplace pas des données primaires compatibles avec un audit."}],"twist":{"title":"L’échantillon faible est effectivement libérable","content":"La reconstruction montre que le run était techniquement valide, que les contrôles étaient corrects et que l’échantillon 4 présente un signal faible reproductible dans les données primaires. Après réévaluation professionnelle documentée, l’échantillon peut être libéré ; une répétition complète n’est pas nécessaire. Cependant, une revue par échantillonnage d’autres entrées du cahier de laboratoire révèle plusieurs formulations abrégées similaires : ce qui semblait être un cas isolé devient une faiblesse documentaire systémique.","why_critical":"La validité analytique et la conformité du processus sont deux questions distinctes. Le résultat concret peut être sauvé, tandis que le near miss exige néanmoins une gestion déviation/CAPA fondée sur le risque."},"result_packages":[{"id":"optimal","title":"Libération fondée sur le risque + CAPA","class":"optimal","result":"Run et échantillon 4 entièrement reconstruits, libération professionnelle, déviation documentée, cause racine traitée, CAPA mise en place avec contrôle d’efficacité.","feedback":"Très bien. La validité analytique et la conformité du processus ont été évaluées séparément et selon le risque."},{"id":"incomplete","title":"Réflexe de sécurité : tout répéter","class":"incomplete","result":"L’ensemble du run est répété alors que toutes les données primaires pertinentes étaient disponibles.","feedback":"Répéter n’est pas une fin en soi. La consommation de matériel et de ressources n’a pas été prise en compte ; la cause du processus reste non résolue."},{"id":"release_no_capa","title":"Résultat correct, QM incorrect","class":"incomplete","result":"L’échantillon est correctement libéré, puis le problème documentaire est considéré comme réglé.","feedback":"Le résultat concret est sauvé, mais pas la cause systémique."},{"id":"wrong","title":"Libération fondée uniquement sur le souvenir","class":"wrong","result":"Libération uniquement sur la base de la routine et de la mémoire.","feedback":"Ni audit-compatible ni robuste."}],"followup_logic":[{"trigger":"Les données primaires ne peuvent pas être entièrement reconstruites","action":"Mettre en hold et effectuer une répétition ciblée et/ou des clarifications supplémentaires.","consequence":"Pas de libération sans base robuste."},{"trigger":"Reconstruction complète plus contrôles valides","action":"Effectuer et documenter une réévaluation professionnelle.","consequence":"La libération peut être possible."},{"trigger":"Lacune documentaire systémique","action":"Réaliser une analyse de cause racine et une CAPA.","consequence":"Adapter template/processus/formation selon la cause identifiée."},{"trigger":"CAPA mise en œuvre","action":"Examiner un échantillon des documentations qPCR ultérieures.","consequence":"Contrôle d’efficacité plutôt qu’une simple clôture de l’action."}],"debrief_points":["La validité analytique et la conformité du processus sont des questions différentes.","Une déviation ne rend pas automatiquement un résultat invalide.","Une répétition doit être justifiée selon le risque.","Le matériel limité, le temps et les ressources font partie de l’évaluation du risque.","Un near miss est particulièrement instructif lorsque la faiblesse est identifiée avant qu’un dommage ne survienne.","Une CAPA se termine par un contrôle d’efficacité, pas par « personnel formé »."],"instructor_notes":{"model_answer":"La traçabilité est d’abord reconstruite à partir du LIMS, de l’export de l’appareil, de la SOP, du lot, des contrôles et des données brutes. Si l’identité de l’échantillon, la validité du run et la faible positivité de l’échantillon 4 sont traçables de manière robuste, le résultat peut être libéré après réévaluation documentée. Une répétition systématique n’est pas nécessaire. La lacune documentaire initiale est néanmoins traitée comme une déviation pertinente à caractère de near miss. Si un problème systémique est identifié, une analyse de cause racine, une CAPA appropriée et un contrôle d’efficacité sont réalisés.","scoring_focus":["Reconstruction avant répétition.","Données primaires plutôt que souvenir.","Libération correcte de l’échantillon faible.","Déviation/near miss non ignoré.","CAPA liée à la cause racine.","Contrôle d’efficacité."],"discussion_questions":["Quand une répétition est-elle réellement nécessaire ?","Un résultat peut-il être valide alors que le processus était défectueux ?","Où se situe la limite entre correction et CAPA ?","Pourquoi davantage de sécurité ne signifie-t-il pas automatiquement davantage de répétitions ?"]},"report_additions":{"content_status":"Deep Dive curé en FR","key_turning_point":"Échantillon faible libérable après reconstruction","core_message":"Validité analytique ≠ conformité du processus","pattern":"Reconstruction → évaluation du risque → libération → CAPA → contrôle d’efficacité"},"is_signature_case":true},"RES_OMICS_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_OMICS_001_v1_0","title":"200 DEGs, un biomarqueur ? Du signal RNA-seq à une hypothèse robuste de résistance","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Recherche translationnelle / pathologie moléculaire / bioinformatique","estimated_minutes_deep":"18–22","learning_objectives":["Transformer les listes de DEGs en programmes biologiques plutôt qu’en récits centrés sur un gène unique.","Opérationnaliser une observation omique sous forme d’hypothèse testable et de PICO.","Distinguer discovery, validation technique, validation morphologique et réplication externe.","Ne pas surinterpréter des résultats exploratoires comme un biomarqueur déjà établi.","Prioriser la robustesse d’une signature par rapport à un gène unique séduisant."],"opening_scene":"Lundi matin, réunion de recherche translationnelle. Une doctorante vient de terminer sa première analyse RNA-seq : 30 tumeurs traitées par ICI, 15 répondeurs et 15 non-répondeurs. Sur sa diapositive : « 200 DEGs significatifs ». En dessous, un tableau trié. Elle demande : « Quel gène dois-je maintenant choisir comme biomarqueur ? » La valeur p la plus faible paraît spectaculaire. Mais c’est précisément ici que commence le véritable travail scientifique.","case_briefing":"RNA-seq de 30 tumeurs traitées par ICI : 15 répondeurs et 15 non-répondeurs. Chez les non-répondeurs, TGFB1, COL1A1, CXCL12, ACTA2, FN1 et d’autres gènes de l’ECM sont augmentés, tandis que HLA-A, B2M, TAP1, CXCL9 et GZMB sont diminués. L’analyse des pathways montre TGFβ/ECM élevés et présentation antigénique/activation des lymphocytes T faibles. Cliniquement, les tumeurs riches en stroma sont associées à une moins bonne réponse aux ICI.","context_cards":[{"title":"Cohorte de discovery","content":"30 tumeurs traitées par ICI, 15 répondeurs versus 15 non-répondeurs.","teaching_point":"Les petites cohortes de discovery conviennent à la génération d’hypothèses, pas automatiquement à une revendication de biomarqueur."},{"title":"Signal RNA-seq","content":"200 gènes différentiellement exprimés.","teaching_point":"Une liste de gènes n’est pas encore une explication biologique."},{"title":"Profil biologique","content":"TGFβ/ECM élevés, présentation antigénique/activation des lymphocytes T faibles.","teaching_point":"Des programmes coordonnés peuvent être plus informatifs qu’un gène unique."},{"title":"Objectif translationnel","content":"Développer un mécanisme et une signature testable cliniquement.","teaching_point":"Passer de l’omique à la translation nécessite plusieurs niveaux de validation."}],"pre_results":[{"title":"Non-répondeurs – augmentés","content":"TGFB1, COL1A1, CXCL12, ACTA2, FN1 et autres gènes de l’ECM."},{"title":"Non-répondeurs – diminués","content":"HLA-A, B2M, TAP1, CXCL9 et GZMB."},{"title":"Enrichissement des pathways","content":"TGFβ/ECM élevés ; présentation antigénique/activation des lymphocytes T faibles."},{"title":"Pas encore tranché","content":"Le gène unique le plus fort, une signature et un programme biologique ne sont pas la même chose. L’interprétation doit être activement priorisée."}],"material_or_resource_constraints":["Cohorte de discovery : n = 30.","Les tests multiples/la FDR doivent être pris en compte.","Les facteurs de confusion cliniques tels que traitement, entité tumorale, ECOG et cellularité tumorale doivent être recueillis.","Le budget permet une validation technique et morphologique ciblée, pas du multi-omics illimité.","Une validation indépendante est nécessaire avant toute revendication de biomarqueur."],"reasoning_gate_upgrade":[{"id":"omics_from_degs","type":"single_choice","prompt":"Comment transformer 200 DEGs en une question de recherche robuste ?","options":[{"id":"lowest_p","label":"Sélectionner le gène ayant la valeur p la plus faible."},{"id":"all_genes","label":"Rapporter les 200 gènes comme s’ils avaient la même importance."},{"id":"programs","label":"Identifier des programmes biologiques coordonnés et des pathways communs."},{"id":"expected_only","label":"Ne conserver que les gènes qui correspondent au récit attendu."}],"correct":["programs"],"rationale":"Le profil stromal/immunitaire partagé fournit une hypothèse plus robuste qu’un gène unique isolé."},{"id":"omics_hypothesis","type":"single_choice","prompt":"Quelle hypothèse correspond le mieux aux données disponibles ?","options":[{"id":"stroma_immune","label":"La non-réponse primaire aux ICI est associée à un microenvironnement tumoral dominé par le stroma/TGFβ et simultanément pauvre en antigènes."},{"id":"tgfb1_marker","label":"TGFB1 est le nouveau biomarqueur prédictif."},{"id":"all_degs_explain","label":"Les 200 DEGs expliquent déjà complètement la résistance aux ICI."},{"id":"one_resistance_gene","label":"Tous les non-répondeurs possèdent le même gène de résistance."}],"correct":["stroma_immune"],"rationale":"L’hypothèse intègre plusieurs programmes d’expression coordonnés et reste testable sans surinterpréter un hit exploratoire unique."},{"id":"omics_pico","type":"multi_select","prompt":"Quels éléments appartiennent à une opérationnalisation rigoureuse de l’hypothèse ?","options":[{"id":"population","label":"Population : tumeurs traitées par ICI"},{"id":"exposure","label":"Exposition/signature : signature CAF/TGFβ élevée"},{"id":"comparison","label":"Comparaison : signature faible"},{"id":"outcome","label":"Outcome : réponse/PFS"},{"id":"score_cutoff","label":"Définir la stratégie de score/cutoff avant la validation"},{"id":"confounders","label":"Définir les facteurs de confusion pertinents et le plan d’analyse"},{"id":"posthoc_cutoff","label":"Fixer le cutoff uniquement après avoir vu le résultat de validation le plus favorable"}],"correct":["population","exposure","comparison","outcome","score_cutoff","confounders"],"rationale":"L’hypothèse, le PICO, le score/cutoff et le plan d’analyse doivent être opérationnalisés avant la validation."},{"id":"omics_validation","type":"multi_select","prompt":"Quelles étapes de validation sont robustes pour le développement translationnel ?","options":[{"id":"targeted","label":"RNA ciblé/qPCR/NanoString"},{"id":"external","label":"Cohorte ICI indépendante"},{"id":"morphology","label":"αSMA/FAP/CD8/HLA-I/B2M comme pont morphologique"},{"id":"fdr","label":"Rapporter de façon transparente la FDR et les tests multiples"},{"id":"heatmap_only","label":"Redessiner la heatmap"},{"id":"single_wb","label":"Confirmer uniquement le gène unique le plus fort par Western blot"}],"correct":["targeted","external","morphology","fdr"],"rationale":"Les validations technique, morphologique et indépendante se complètent ; une simple visualisation ou un seul test de confirmation ne suffisent pas pour une hypothèse de signature."}],"decision_task":"À partir de l’analyse exploratoire RNA-seq, développez une stratégie translationnelle robuste : hypothèse biologique, PICO, concept de signature/analyse, validation technique, pont morphologique, validation externe et limite d’une revendication de biomarqueur acceptable.","expected_path":["Ne pas traiter la liste de DEGs comme le produit final.","Prioriser le niveau pathways/réseaux.","Formuler un profil dominé par le stroma/TGFβ et pauvre en antigènes.","Définir l’hypothèse et le PICO.","Opérationnaliser la signature.","Prendre en compte FDR et facteurs de confusion.","Réaliser une validation technique ciblée.","Relier morphologiquement les résultats à l’aide de marqueurs du TME.","Utiliser une cohorte indépendante.","Seulement ensuite discuter le potentiel de biomarqueur."],"acceptable_alternatives":["Conclure explicitement l’étude comme exploratoire sans revendication de biomarqueur.","Développer une signature plus petite et ciblée plutôt qu’un score complexe.","Utiliser une expression ciblée/NanoString plutôt qu’un nouveau RNA-seq pour la validation technique.","Ajouter une validation fonctionnelle si la question mécanistique est centrale."],"low_value_traps":[{"label":"Valeur p la plus faible = biomarqueur","why_bad":"Les gènes uniques peuvent être instables et perdre le contexte biologique."},{"label":"Heatmap = validation","why_bad":"La visualisation ne démontre pas une reproductibilité indépendante."},{"label":"200 DEGs comme résultat","why_bad":"La quantité de données ne remplace pas une hypothèse."},{"label":"Optimiser le cutoff a posteriori","why_bad":"Risque d’overfitting/HARKing."},{"label":"Supprimer les résultats qui ne conviennent pas","why_bad":"Reporting sélectif."}],"twist":{"title":"Le « meilleur gène » disparaît – la biologie reste","content":"Dans une cohorte de validation indépendante, le gène unique ayant la valeur p la plus faible en discovery ne se reproduit pas de façon convaincante. En revanche, la signature stromale/immunitaire définie au préalable continue de montrer le même profil coordonné : composante stromale/TGFβ augmentée, composante présentation antigénique/lymphocytes T diminuée. La validation morphologique soutient également l’interprétation au niveau du programme.","why_critical":"Le hit individuel de discovery le plus séduisant n’est pas nécessairement le signal biologique le plus robuste. Le cas distingue gène unique, signature, mécanisme et biomarqueur validé."},"result_packages":[{"id":"optimal","title":"Hypothèse de signature validée","class":"optimal","result":"Hypothèse basée sur les pathways, signature prédéfinie, validation technique, pont morphologique et cohorte indépendante montrent un profil cohérent.","feedback":"Très bon développement translationnel. Le potentiel de biomarqueur peut maintenant être discuté avec prudence."},{"id":"incomplete","title":"Effondrement du gène unique","class":"incomplete","result":"Le gène unique le plus fort de discovery ne se reproduit pas, mais la signature globale reste cohérente.","feedback":"Ce n’est pas un échec du projet si l’hypothèse biologique est soutenue indépendamment."},{"id":"heatmap_story","title":"Belle heatmap, pas de validation","class":"incomplete","result":"Cluster exploratoire sans réplication indépendante.","feedback":"Intéressant, mais pas un biomarqueur robuste."},{"id":"wrong","title":"Overclaim","class":"wrong","result":"La signature de discovery est directement qualifiée de biomarqueur prédictif.","feedback":"L’interprétation dépasse la force probante des données."}],"followup_logic":[{"trigger":"Seul un gène unique est priorisé","action":"Réintégrer l’analyse pathways/réseaux dans le raisonnement.","consequence":"Reasoning cap en cas d’interprétation monomarqueur."},{"trigger":"Pas de validation indépendante","action":"Qualifier le résultat d’exploratoire.","consequence":"Pas de revendication de biomarqueur."},{"trigger":"La signature se réplique","action":"Évaluer la translation morphologique et clinique.","consequence":"Parcours optimal du Deep Dive."}],"debrief_points":["Une liste de DEGs n’est pas encore un modèle biologique.","Les informations de pathways et de signature peuvent être plus robustes qu’un seul gène de discovery.","Les validations technique, morphologique et externe répondent à des questions différentes.","Discovery et validation doivent être séparées.","La non-réplication d’un hit unique peut améliorer une hypothèse au lieu de détruire le projet.","Un biomarqueur est le résultat d’une chaîne de validation, pas d’une belle heatmap."],"instructor_notes":{"model_answer":"Les données sont d’abord interprétées au niveau des pathways/réseaux. Le profil coordonné TGFβ/ECM élevé et présentation antigénique faible est formulé comme hypothèse exploratoire de résistance. La population, la signature, la comparaison et l’outcome sont ensuite opérationnalisés. La signature est validée techniquement, morphologiquement et dans une cohorte indépendante. Les gènes uniques et les cutoffs ne sont pas surinterprétés post hoc comme des biomarqueurs établis.","scoring_focus":["Pathway avant gène unique.","Hypothèse/PICO clairs.","FDR/facteurs de confusion pris en compte.","Discovery et validation séparées.","Pont morphologique.","Revendication de biomarqueur correctement limitée."],"discussion_questions":["Quand une signature est-elle supérieure à un marqueur unique ?","Que signifie réellement une validation indépendante ?","Comment un résultat négatif de validation peut-il avoir une valeur scientifique ?","Quand une association peut-elle devenir un projet de biomarqueur ?"]},"report_additions":{"content_status":"Deep Dive curé en FR","key_turning_point":"Le meilleur hit unique ne se réplique pas","core_message":"DEG → pathway → hypothèse → signature → validation","pattern":"Ne pas confondre discovery et preuve d’un biomarqueur"},"is_signature_case":true},"RES_ETH_001_v1_0":{"version":"v2.3.0b_signature_deepdive_expansion","case_id":"RES_ETH_001_v1_0","title":"120 blocs d’archive et aucun consentement clair : le projet peut-il démarrer ?","domain":"RES","target_course":"RES Basics","deep_dive_priority":"signature","target_role":"Direction de projet translationnel / pathologie / QM de recherche","estimated_minutes_deep":"18–22","learning_objectives":["Comprendre la governance comme une condition préalable du travail scientifique, et non comme une formalité en aval.","Planifier séparément éthique/consentement, protection du matériel, protection des données et gestion des découvertes fortuites.","Reconnaître pourquoi le matériel résiduel et l’anonymisation ne constituent pas des autorisations générales.","Planifier la décision de recherche de sorte que les situations ultérieures de suspicion germinale et de data sharing soient couvertes dès le départ."],"opening_scene":"Une équipe de recherche présente un nouveau projet : 120 blocs tumoraux FFPE archivés doivent être analysés avec un panel DNA/RNA élargi afin d’identifier de nouveaux marqueurs de résistance. L’essai, la bioinformatique et le budget sont en place. La direction du projet dit : « Ce n’est que du matériel résiduel. Nous pouvons commencer la semaine prochaine. » Pourtant, les blocs proviennent d’années différentes, la situation du consentement est hétérogène et la réserve diagnostique restante n’est pas claire pour certains petits blocs. De plus, le panel tumor-only prévu peut révéler des variants potentiellement pertinents sur le plan germinal. La première décision doit donc être prise avant même de couper un échantillon.","case_briefing":"Objectif du projet : identifier de nouveaux marqueurs moléculaires de résistance thérapeutique dans une cohorte tumorale rétrospective. Sont prévus 120 blocs FFPE de routine, un panel DNA/RNA élargi, un lien avec les données cliniques et le follow-up, une publication et, le cas échéant, une validation externe/un data sharing. La situation consentement/governance est hétérogène, la réserve tissulaire est limitée dans certains cas et aucun processus défini pour les découvertes fortuites/suspicion germinale n’est encore en place.","context_cards":[{"title":"Matériel","content":"FFPE de routine, parfois petits blocs ; la réserve diagnostique n’est pas garantie dans tous les cas.","teaching_point":"La recherche ne doit pas compromettre la prise en charge future du patient."},{"title":"Consentement","content":"Années de prélèvement différentes et situation hétérogène de consent/governance.","teaching_point":"Archivé ne signifie pas automatiquement librement disponible."},{"title":"Données","content":"Les données cliniques et le follow-up doivent être reliés.","teaching_point":"La protection des données et les droits d’accès font partie du design de l’étude."},{"title":"Génétique","content":"Une analyse tumor-only peut générer une suspicion de résultat germinal.","teaching_point":"Les voies de retour d’information doivent être définies avant l’analyse."},{"title":"Data sharing","content":"Une validation externe et une publication sont prévues.","teaching_point":"L’utilisation ultérieure des données doit être couverte par le cadre de governance."}],"pre_results":[{"title":"Cohorte","content":"120 cas potentiels issus d’années différentes."},{"title":"Governance","content":"Pas de situation uniforme de consentement ; la libération finale du matériel reste en attente."},{"title":"Plan de données","content":"Les données cliniques doivent être complétées rétrospectivement ; une validation externe est envisagée comme option ultérieure."},{"title":"Découvertes fortuites prévisibles","content":"Le panel tumor-only peut identifier des variants potentiellement pertinents sur le plan germinal ; un processus encadré doit exister avant le démarrage."}],"material_or_resource_constraints":["La réserve diagnostique restante est prioritaire sur la consommation pour la recherche.","Tous les cas ne doivent pas obligatoirement être inclus dans la cohorte finale.","Le follow-up et la possibilité d’un retour d’information encadré peuvent entrer en conflit avec une anonymisation complète.","L’étendue des données et les accès doivent être limités au nécessaire.","Les décisions de governance doivent être prises avant tout traitement irréversible du matériel et des données."],"reasoning_gate_upgrade":[{"id":"eth_start","type":"single_choice","prompt":"Le projet peut-il démarrer immédiatement ?","options":[{"id":"leftover_yes","label":"Oui, puisqu’il s’agit de matériel résiduel."},{"id":"anonymized_yes","label":"Oui, si tous les numéros de cas sont supprimés."},{"id":"governance_first","label":"Non ; il faut d’abord clarifier la situation éthique/consentement, la protection des données, la libération du matériel et le processus de découvertes fortuites."},{"id":"dna_extract_first","label":"Oui, tant que seule une extraction d’ADN est réalisée au départ."}],"correct":["governance_first"],"rationale":"La governance et la protection du matériel doivent être clarifiées avant toute utilisation irréversible des échantillons et des données."},{"id":"eth_prerequisites","type":"multi_select","prompt":"Quelles conditions préalables doivent être clarifiées avant le début des analyses ?","options":[{"id":"ethics","label":"Avis éthique/amendement"},{"id":"consent","label":"Vérifier consentement/broad consent/opt-out ou la base de governance applicable"},{"id":"material_release","label":"Libération du matériel par la pathologie"},{"id":"reserve","label":"Protection de la réserve diagnostique"},{"id":"pseudonym","label":"Concept de pseudonymisation/gestion de la clé"},{"id":"roles","label":"Concept de rôles et d’accès"},{"id":"side_findings","label":"Gestion définie des découvertes fortuites/suspicion germinale"},{"id":"sharing","label":"Concept de data sharing"},{"id":"leftover_note","label":"Une mention « matériel résiduel » comme seule autorisation"}],"correct":["ethics","consent","material_release","reserve","pseudonym","roles","side_findings","sharing"],"rationale":"La governance comprend éthique, consentement/base juridique, protection du matériel, protection des données, rôles, découvertes fortuites et utilisation ultérieure des données."},{"id":"eth_anonymization","type":"single_choice","prompt":"Une anonymisation complète résout-elle automatiquement les questions de governance ?","options":[{"id":"no","label":"Non. Elle ne remplace pas l’évaluation du matériel/de l’éthique et peut rendre le follow-up ou un retour d’information encadré plus difficiles."},{"id":"yes","label":"Oui. Après anonymisation, le consentement, la libération du matériel et les découvertes fortuites ne sont plus pertinents."},{"id":"always_best","label":"Oui. L’anonymisation complète est la norme à privilégier pour toute étude translationnelle."}],"correct":["no"],"rationale":"L’anonymisation est un concept de protection des données, pas une gomme universelle de governance."},{"id":"eth_material_guard","type":"single_choice","prompt":"L’évaluation du matériel montre une réserve diagnostique limitée dans plusieurs petites biopsies. Quelle est la bonne conduite ?","options":[{"id":"exclude_reduce","label":"Exclure les cas ou réduire l’ampleur de la recherche et protéger la réserve diagnostique."},{"id":"use_all","label":"Utiliser tous les cas afin de maximiser l’effectif scientifique."},{"id":"split_half","label":"Toujours réserver la moitié du matériel à la recherche, indépendamment de la réserve diagnostique restante."}],"correct":["exclude_reduce"],"rationale":"Une cohorte plus petite et conforme à la governance est préférable à une cohorte plus grande au détriment du diagnostic futur."}],"decision_task":"Élaborez un concept de governance et de libération couvrant tout le cycle de vie du projet : démarrage, utilisation du matériel, données cliniques, pseudonymisation/accès, découvertes génétiques fortuites, publication et data sharing.","expected_path":["Mettre initialement le projet en hold.","Définir clairement la question de recherche/PICO.","Vérifier la situation éthique/consentement.","Effectuer la libération du matériel par la pathologie.","Protéger la réserve diagnostique.","Définir pseudonymisation et rôles/accès.","Définir un jeu de données minimal.","Établir à l’avance le processus de découvertes fortuites/suspicion germinale.","Aligner le data sharing sur la governance.","Ce n’est qu’ensuite que le matériel peut être libéré et l’analyse démarrer."],"acceptable_alternatives":["Limiter la cohorte aux cas dont la situation de governance et de matériel est claire.","Réduire l’ampleur de la recherche.","Réaliser le projet sous forme d’étude pilote plus petite.","Limiter le data sharing si le cadre de governance initial ne le permet pas."],"low_value_traps":[{"label":"Matériel résiduel = librement disponible","why_bad":"Le matériel issu des patients reste soumis à la governance."},{"label":"L’anonymisation résout tout","why_bad":"Les questions de matériel, d’éthique et de retour d’information persistent."},{"label":"Effectif avant protection du matériel","why_bad":"La recherche ne doit pas évincer la réserve diagnostique."},{"label":"Clarifier les découvertes fortuites plus tard","why_bad":"Le processus doit exister avant qu’un résultat prévisible ne survienne."},{"label":"Vérifier le data sharing seulement au moment de publier","why_bad":"Trop tard si les données ont déjà été recueillies dans une structure inadéquate pour cette utilisation."}],"twist":{"title":"La découverte fortuite prévisible devient réalité","content":"Le projet démarre après réalisation complète de la revue de governance. Au cours de l’analyse tumor-only, un cas présente une constellation BRCA1 potentiellement pathogène avec possible pertinence germinale. L’équipe demande immédiatement : « Devons-nous appeler la patiente maintenant ? » La bonne réponse n’est ni d’ignorer le résultat ni de le communiquer immédiatement. Le processus de découvertes fortuites/suspicion germinale défini avant le démarrage du projet est appliqué.","why_critical":"La valeur d’une bonne governance ne se manifeste pas dans le dossier d’éthique, mais au moment où une situation difficile prévisible survient réellement."},"result_packages":[{"id":"optimal","title":"Governance first","class":"optimal","result":"Éthique, consent/governance, réserve tissulaire, protection des données, rôles d’accès, processus de découvertes fortuites et data sharing sont clarifiés avant l’analyse. Les blocs problématiques sont protégés ou exclus.","feedback":"Très bonne architecture de projet."},{"id":"wrong","title":"Start now","class":"wrong","result":"Le matériel est traité avant clarification de la situation du consentement et de la réserve diagnostique.","feedback":"Erreur critique de governance."},{"id":"incomplete","title":"Anonymize everything","class":"incomplete","result":"Le lien avec le cas est supprimé complètement et précocement ; le follow-up et le retour d’information encadré deviennent problématiques alors que d’autres questions de governance restent ouvertes.","feedback":"Une mesure technique de protection des données ne remplace pas un concept global."},{"id":"material_wrong","title":"Science before material","class":"wrong","result":"De petits blocs diagnostiquement importants sont consommés pour maximiser l’effectif.","feedback":"L’intérêt scientifique a été placé avant la protection du matériel."}],"followup_logic":[{"trigger":"Réserve diagnostique limitée","action":"Exclure le cas ou réduire la consommation pour la recherche.","consequence":"Cohorte plus petite, mais responsable."},{"trigger":"Suspicion germinale potentielle","action":"Appliquer le processus prédéfini de découvertes fortuites/génétique clinique.","consequence":"Pas de communication ad hoc."},{"trigger":"Un partenaire externe demande les données brutes","action":"Vérifier le cadre consent/governance/data sharing.","consequence":"Ne transmettre que les données autorisées ou limiter le partage."},{"trigger":"Governance non clarifiée","action":"Le projet reste en hold.","consequence":"Pas de libération du matériel."}],"debrief_points":["La governance fait partie du design de l’étude.","Le matériel résiduel n’est pas automatiquement du matériel de recherche librement disponible.","La réserve diagnostique est prioritaire.","Pseudonymisation, anonymisation et governance ne sont pas la même chose.","Les découvertes génétiques fortuites prévisibles nécessitent un processus défini à l’avance.","Un bon design de recherche inclut déjà la gestion ultérieure de la publication et du data sharing.","Une cohorte plus petite et bien définie peut être scientifiquement et éthiquement plus solide que l’effectif maximal possible."],"instructor_notes":{"model_answer":"Le projet ne peut démarrer qu’après clarification de la situation éthique/consentement, de la protection des données, de la libération du matériel et de la gestion des découvertes fortuites. La réserve diagnostique est protégée pour chaque cas. Les données cliniques sont pseudonymisées et traitées avec des accès basés sur les rôles. Une éventuelle suspicion germinale issue de données tumor-only n’est pas communiquée ad hoc mais gérée via un processus défini au préalable. Le data sharing n’est effectué que dans le cadre de governance établi.","scoring_focus":["Governance avant démarrage du projet.","Protection du matériel.","Pseudonymisation/accès.","Processus de découvertes fortuites.","Pas de retour ad hoc.","Data sharing anticipé dès la conception."],"discussion_questions":["Quand une cohorte plus petite constitue-t-elle la meilleure étude ?","Pourquoi une anonymisation complète n’est-elle pas toujours la solution la plus élégante ?","Quelles conséquences le séquençage tumor-only a-t-il déjà au stade de la planification de l’étude ?","Quand le data sharing doit-il être planifié conceptuellement ?"]},"report_additions":{"content_status":"Deep Dive curé en FR","key_turning_point":"Suspicion germinale potentielle BRCA1","core_message":"La governance doit précéder le démarrage du projet","pattern":"Démarrage → matériel → analyse → découverte fortuite → data sharing"},"is_signature_case":true}}};
const SUPPORTED=['de','en','ro','el','es','fr'];
function langNow(){
  let raw='';
  try{raw=(document.body&&document.body.getAttribute('data-molpath-lang'))||localStorage.getItem('molpath_lang')||document.documentElement.lang||'de';}catch(_e){raw=(document.documentElement&&document.documentElement.lang)||'de';}
  raw=String(raw||'de').toLowerCase().replace('_','-').split('-')[0];
  return SUPPORTED.indexOf(raw)>=0?raw:'de';
}
function syncStrings(target,source){
  if(!target||!source)return;
  if(Array.isArray(target)&&Array.isArray(source)){
    const n=Math.min(target.length,source.length);
    for(let i=0;i<n;i++){
      if(typeof source[i]==='string'){target[i]=source[i];}
      else if(target[i]&&source[i]&&typeof target[i]==='object'&&typeof source[i]==='object'){syncStrings(target[i],source[i]);}
    }
    return;
  }
  if(typeof target==='object'&&typeof source==='object'){
    Object.keys(source).forEach(function(k){
      if(!(k in target))return;
      if(typeof source[k]==='string'){target[k]=source[k];}
      else if(target[k]&&source[k]&&typeof target[k]==='object'&&typeof source[k]==='object'){syncStrings(target[k],source[k]);}
    });
  }
}
function applyLanguage(lang){
  lang=SUPPORTED.indexOf(lang)>=0?lang:'de';
  if(typeof DEEP_DIVE_CASES_V17==='undefined'||typeof DEEP_DIVE_MAP_V17==='undefined')return false;
  CASE_IDS.forEach(function(id){
    const target=DEEP_DIVE_CASES_V17.find(function(x){return x&&x.case_id===id;})||DEEP_DIVE_MAP_V17[id];
    if(!target)return;
    const src=(lang==='de'?SOURCE_DE[id]:(LOCALIZED[lang]&&LOCALIZED[lang][id]))||SOURCE_DE[id];
    syncStrings(target,src);
    DEEP_DIVE_MAP_V17[id]=target;
    try{
      if(typeof cases!=='undefined'){
        const c=cases.find(function(x){return x&&x.id===id;});
        if(c)c.deep_dive_title=src.title;
      }
    }catch(_e){}
  });
  try{
    if(window.MolPathSignatureDeepDiveExpansion230b){
      // metadata-only replacement; no runtime behavior depends on this field
      window.MolPathSignatureDeepDiveI18n230c=Object.freeze({
        release:PATCH_RELEASE,name:PATCH_NAME,base:'v2.3.0b',sourceLanguage:'de',
        languages:['en','ro','el','es','fr'],caseIds:CASE_IDS.slice(),deepDiveCountLocalized:CASE_IDS.length
      });
    }
  }catch(_e){}
  return true;
}
const PREV_RENDER=window.render;
if(typeof PREV_RENDER==='function'){
  window.render=function(){
    try{applyLanguage(langNow());}catch(err){console.error(PATCH_RELEASE+' deep-dive i18n apply failed',err);}
    const out=PREV_RENDER.apply(this,arguments);
    setTimeout(function(){try{if(window.MolPathI18n&&typeof window.MolPathI18n.apply==='function')window.MolPathI18n.apply();}catch(_e){}},0);
    return out;
  };
}
function boot(){
  try{applyLanguage(langNow());}catch(err){console.error(PATCH_RELEASE+' boot i18n failed',err);}
  try{if(typeof window.render==='function')window.render();}catch(err){console.error(PATCH_RELEASE+' render after i18n failed',err);}
  try{console.log('[MolPath '+PATCH_RELEASE+'] 4 Signature Deep Dives localized: EN/RO/EL/ES/FR');}catch(_e){}
}
window.MolPathApplySignatureDeepDiveI18n230c=applyLanguage;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
